"use strict";

/**
 * Course lesson data and page content.
 * Keep lesson copy, activity prompts, and page markup here. The reader owns
 * navigation, progress, journals, and interactive lab behavior.
 */
(() => {
  const activities={"module-1-1":{"prompt":"Draw a path from a phone to a website. Mark the end systems, access networks, routers, and protocols.","walkthrough":"The phone and server are end systems. Wi-Fi and ISP links connect them to routers; provider networks carry packets between them."},"module-1-2":{"prompt":"Compare two designs for sending a burst of data: reserve a circuit first, or send packets over shared links.","walkthrough":"A circuit reserves capacity and may leave it unused; packet switching shares capacity but can create queues when bursts overlap."},"module-1-3":{"prompt":"Estimate transmission delay for a 1,500-byte packet on a 10-Mbps link; then compare it with 100 km of propagation.","walkthrough":"Bits take 12,000 / 10,000,000 seconds, or 1.2 ms, to transmit. At 200,000 km/s, 100 km takes 0.5 ms to propagate."},"module-1-4":{"prompt":"Trace one message down the stack. Name what each layer adds before the message reaches a link.","walkthrough":"Application data becomes a transport segment, then an IP datagram, then a link frame; the receiver removes these headers in reverse."},"module-2-1":{"prompt":"Sketch a client-server app and a peer-to-peer app. Mark which processes listen and which initiate communication.","walkthrough":"A server listens at a known address and port; peers may initiate connections while also serving requests from other peers."},"module-2-2":{"prompt":"Trace a browser loading one page and two images. Mark where connection reuse and caching can save a round trip.","walkthrough":"A persistent TCP connection can carry multiple requests; a cached image may need no request to the origin server."},"module-2-3":{"prompt":"Follow an email from sender to recipient. Separate SMTP transfer from mailbox access.","walkthrough":"SMTP submits and relays the message between mail servers; the recipient later reads it through an access protocol such as IMAP."},"module-2-4":{"prompt":"Trace a video request from its hostname to the media chunks. Mark where DNS and a CDN influence the path.","walkthrough":"DNS resolves the service name; the service selects a nearby CDN node, and the player requests chunks at a suitable quality."},"module-3-1":{"prompt":"List the source and destination ports for a browser request and its reply. Explain how the reply reaches the right process.","walkthrough":"The client uses a temporary source port and the server’s listening port; the returned segment’s address-and-port tuple identifies the socket."},"module-3-2":{"prompt":"Choose UDP or TCP for a live voice packet and for a file download. Explain the cost of each choice.","walkthrough":"Voice often prioritizes timeliness and can tolerate some loss, favoring UDP; a file needs reliable in-order delivery, favoring TCP."},"module-3-3":{"prompt":"Trace four packets with packet 2 lost. Compare what Go-Back-N and Selective Repeat retransmit.","walkthrough":"Go-Back-N repeats packet 2 and later unacknowledged packets; Selective Repeat repeats packet 2 while buffering later packets."},"module-3-4":{"prompt":"Diagnose two slow transfers: one receiver advertises a tiny window; another path shows rising loss and queues.","walkthrough":"The first is receiver-limited, so flow control applies; the second suggests network congestion, so congestion control reduces sending."},"module-4-1":{"prompt":"Given a route learned by the network, trace the local forwarding-table action for one datagram.","walkthrough":"Routing establishes the path and next hops; each router independently uses its local table to select the outgoing link."},"module-4-2":{"prompt":"Trace a packet through input port, switching fabric, output queue, and link. Mark where it can wait.","walkthrough":"The input looks up the header; the fabric transfers the packet; it may queue at the output if arrivals outpace transmission."},"module-4-3":{"prompt":"Use the forwarding table to select a route for 203.0.113.150. Compare /24, /25, and /28.","walkthrough":"All three prefixes match; /28 contains the most bits, so longest-prefix matching selects that route."},"module-4-4":{"prompt":"Write a match/action rule that sends packets from one source subnet to a monitoring port.","walkthrough":"Match the source-prefix field, then apply a forward-to-monitor-port action; the controller installs the rule on the device."},"module-5-1":{"prompt":"On a small graph, assign link costs and run Dijkstra from one router. Record each destination’s next hop.","walkthrough":"Repeatedly add the closest unreached node and relax its neighbors; the predecessor chain gives the least-cost path."},"module-5-2":{"prompt":"Give router X two neighbors with advertised costs to destination D. Compute X’s updated distance through each.","walkthrough":"Add X’s link cost to each neighbor’s advertised distance; choose the smaller total and that neighbor as next hop."},"module-5-3":{"prompt":"Divide a large campus network into OSPF areas. Decide which topology details stay local and which are summarized.","walkthrough":"Routers flood detailed state within an area; area-border routers summarize reachability to reduce the amount of state carried elsewhere."},"module-5-4":{"prompt":"Compare two BGP routes to the same destination, one shorter and one preferred by local policy.","walkthrough":"BGP can choose the policy-preferred route even when it has more AS hops; path length is only one route attribute."},"module-5-5":{"prompt":"Design an SDN rule that blocks one type of traffic while allowing another to a service.","walkthrough":"The controller matches relevant packet fields, installs a drop action for disallowed traffic, and a forward action for permitted traffic."},"module-5-6":{"prompt":"Use ping and traceroute to separate reachability from path visibility. Identify where ICMP appears.","walkthrough":"Ping uses echo requests/replies; traceroute infers hops from time-exceeded messages. SNMP can expose device counters."},"module-6-1":{"prompt":"For a laptop sending an IP datagram over Wi-Fi, list the link service it needs at that hop.","walkthrough":"The link must frame the datagram and deliver it over the local medium; it may also detect errors and coordinate access."},"module-6-2":{"prompt":"Flip one bit in a frame protected by a checksum or CRC. Explain what the receiver can conclude.","walkthrough":"The check will usually detect corruption, but it does not identify the corrected bit; the receiver discards the frame."},"module-6-3":{"prompt":"Compare channel partitioning, random access, and taking turns for a group sharing a medium.","walkthrough":"Partitioning reserves capacity, random access contends, and taking-turns grants sequential opportunities; each trades efficiency against coordination."},"module-6-4":{"prompt":"Your laptop contacts a server outside its subnet. Identify the ARP target and the switch’s forwarding decision.","walkthrough":"ARP resolves the default gateway’s MAC address; the switch forwards the frame toward the router, which routes the IP datagram onward."},"module-6-5":{"prompt":"Place staff, guests, and lab machines into VLANs. State which traffic should cross the router.","walkthrough":"Use separate VLANs for the groups; only explicitly permitted inter-VLAN traffic crosses the router or layer-3 switch."},"module-7-1":{"prompt":"Move a wireless device farther from its access point and add a wall. Predict signal and rate changes.","walkthrough":"Attenuation and obstruction reduce received signal quality; the link may lower its rate or retry frames more often."},"module-7-2":{"prompt":"Trace two Wi-Fi stations trying to send at once. Show how carrier sensing and backoff reduce collisions.","walkthrough":"Each station senses the channel, waits if busy, and chooses a random backoff; acknowledgments confirm successful frame delivery."},"module-7-3":{"prompt":"Choose Bluetooth, Zigbee, or Wi-Fi for a wearable, sensor, and laptop. Compare range, power, and data needs.","walkthrough":"Bluetooth suits nearby personal devices; Zigbee favors low-power sensors; Wi-Fi supports higher data rates at greater power cost."},"module-7-4":{"prompt":"Trace a phone’s data from radio access to the Internet. Mark the role of the carrier core.","walkthrough":"The base station provides radio access; the core authenticates the device, manages its session, and routes traffic outward."},"module-8-1":{"prompt":"Threat-model a login request. List what an attacker might read, alter, replay, or impersonate.","walkthrough":"Map each threat to a goal: confidentiality, integrity, freshness, or authentication; then identify a protection for each."},"module-8-2":{"prompt":"Choose which cryptographic method handles bulk data and which helps establish a shared secret.","walkthrough":"Symmetric encryption efficiently protects bulk traffic; public-key cryptography helps authenticate or establish keys during setup."},"module-8-3":{"prompt":"For a signed update, distinguish the roles of a hash, MAC, and digital signature.","walkthrough":"A hash summarizes data; a MAC authenticates with a shared secret; a signature lets anyone with the public key verify the signer."},"module-8-4":{"prompt":"Add a fresh challenge to an authentication exchange. Explain why reusing an old response fails.","walkthrough":"The server sends a nonce; the client proves knowledge of a secret while including it, so a captured older response will not match."},"module-8-5":{"prompt":"Plan a secure email exchange where only the recipient can read the message and can verify its sender.","walkthrough":"Encrypt with the recipient’s public key and sign with the sender’s private key; both depend on trustworthy key distribution."},"module-9-1":{"prompt":"Classify a movie download, live stream, and voice call by tolerance for delay, loss, and buffering.","walkthrough":"Stored video can buffer; live video has tighter delay; voice is highly delay-sensitive and may tolerate limited packet loss."},"module-9-2":{"prompt":"A player’s buffer is shrinking as bandwidth falls. Choose the next chunk quality and explain the tradeoff.","walkthrough":"Request a lower-bitrate chunk to refill the buffer; visual quality drops, but playback is less likely to stall."},"module-9-3":{"prompt":"Packets arrive unevenly at a voice receiver. Adjust the jitter buffer and compare delay with smoothness.","walkthrough":"A longer buffer absorbs more variation but adds conversational delay; a shorter buffer is timely but risks late or missing audio."},"module-9-4":{"prompt":"Sequence a SIP call setup and RTP media exchange. Identify which protocol carries the audio.","walkthrough":"SIP negotiates and manages the session; RTP carries timestamped, sequenced audio packets during the call."},"module-9-5":{"prompt":"Give voice and bulk file traffic different service needs. Choose a QoS policy and name its risk.","walkthrough":"Prioritize low-delay voice and reserve capacity carefully; excessive priority can starve other traffic, so admission and limits matter."}};
  const lessonDetails={"module-1-1":{"why":"The Internet model explains why a feature can work in one location and fail in another.","engineering":"Use the end-to-end path to separate application, access-provider, routing, and server-edge responsibilities.","caseStudy":"A request succeeds from the office but times out at home. The users run identical code but enter through different providers and routes.","debug":"Compare DNS, connection setup, and route reachability from both networks; record the first divergence."},"module-1-2":{"why":"Packet switching lets bursty applications share links efficiently; queueing explains why that flexibility can become latency under load.","engineering":"This explains why a background upload can make an interactive app feel slow even when both services work correctly alone.","caseStudy":"A release upload shares a 100-Mbit/s uplink with API traffic. The API becomes laggy while the bulk transfer runs.","debug":"Measure queue delay, loss, and offered load at the bottleneck; consider shaping, scheduling, or moving bulk work off peak."},"module-1-3":{"why":"Separating processing, queueing, transmission, and propagation prevents engineers from buying bandwidth when distance is the real issue.","engineering":"Use the components to set latency budgets, place services, size payloads, and choose the right performance fix.","caseStudy":"An API moves to a distant region and gains 90 ms despite low CPU and ample throughput; a backup job separately creates variable queueing.","debug":"Compare client, server, and network timings and latency percentiles; averages can hide the component that needs a fix."},"module-1-4":{"why":"Layering gives teams stable interfaces and an incident map. Each layer owns a different part of the delivery problem.","engineering":"Use it to locate whether an outage belongs to name resolution, transport, security, HTTP semantics, or application logic.","caseStudy":"DNS, TCP, and TLS succeed, but the API returns HTTP 503. The service is unavailable even though the network path is up.","debug":"Use traces across DNS, transport, TLS, HTTP, and application logic; pair signals with request IDs."},"module-2-1":{"why":"Network applications are processes with explicit communication roles. Architecture decides who must stay available and where coordination lives.","engineering":"Apply socket, client-server, and peer models when designing APIs, workers, multiplayer systems, or file transfer.","caseStudy":"A central upload service simplifies authorization and auditability; peer-assisted transfer reduces server load but adds discovery and trust work.","debug":"Check process health, listener binding, address, port, firewall policy, and connection count before changing the protocol."},"module-2-2":{"why":"HTTP semantics shape API correctness, retry safety, caching, and perceived speed; they are design tools, not just syntax.","engineering":"Use methods, status codes, headers, and cache rules to make services predictable, safe, and efficient.","caseStudy":"A dashboard repeatedly requests the same profile. Consolidating calls helps, but a shared cache must not leak one user's data.","debug":"Inspect method, status, headers, payload size, connection reuse, and cache keys; a 200 response can still be unsafe."},"module-2-3":{"why":"DNS, SMTP, and mailbox access are separate services. Knowing the boundaries helps engineers trace notification delivery.","engineering":"Use record lookups, message queues, relay responses, and mailbox access to distinguish where an email is delayed.","caseStudy":"A sender receives a temporary SMTP failure. A queued retry is appropriate; an MX lookup can reveal a recipient-side issue.","debug":"Track queue age, SMTP response class, retry count, and DNS results; accepted by the app does not mean delivered."},"module-2-4":{"why":"DNS, CDNs, adaptive video, and peer distribution solve placement and scale problems for global products.","engineering":"Use cache placement, bitrate adaptation, and distributed delivery to reduce origin load and user-perceived latency.","caseStudy":"DNS selects a nearby CDN edge, but a cache miss sends the first request back to origin; later requests are faster.","debug":"Track resolution, selected edge, cache hit ratio, origin time, and startup delay separately."},"module-3-1":{"why":"Multiplexing keeps a laptop's browser, voice client, DNS resolver, and API traffic attached to the right process.","engineering":"Use port and socket knowledge to diagnose connection limits, bind failures, service exposure, and firewall behavior.","caseStudy":"Two local services bind the same address and port. One fails, while a separate firewall rule blocks a database connection.","debug":"Inspect listening sockets, process IDs, connection states, and firewall rules; ping does not prove a process is listening."},"module-3-2":{"why":"UDP is a small transport service, not a promise of speed or reliability; applications may need to manage timing, loss, and congestion.","engineering":"Choose UDP for workloads that can benefit from its minimal service, and account for the behavior the app must implement itself.","caseStudy":"A voice packet arriving after its playback deadline may be less useful than dropping it; QUIC adds reliability above UDP.","debug":"Measure loss, jitter, deadline misses, and sending rate; UDP applications still need responsible congestion behavior."},"module-3-3":{"why":"Reliable transfer explains how TCP recovers ordered data and why application retries need careful design.","engineering":"Use sequence and acknowledgment behavior to diagnose stalls; use idempotency to make state-changing retries safe.","caseStudy":"A lost segment blocks delivery of later bytes; at the app layer, retrying a payment can duplicate the charge.","debug":"Separate transport retransmissions from application retries in traces; use idempotency keys for state-changing operations."},"module-3-4":{"why":"Flow control protects the receiver; congestion control protects the network. The distinction matters when tuning throughput.","engineering":"Use advertised receive windows and congestion signals to identify whether the receiver or the path is limiting a transfer.","caseStudy":"A small receive window points to a slow client; rising loss and queue delay with a large window suggest path congestion.","debug":"Inspect RTT, retransmissions, receive window, congestion window, and queue delay; do not diagnose every slow transfer as low bandwidth."},"module-4-1":{"why":"Routing decides paths; forwarding applies a local decision per packet. This split locates failures between intent and execution.","engineering":"Use control-plane and data-plane checks to debug stale routes, convergence, and forwarding performance.","caseStudy":"A routing protocol converges, but one router still uses an old next hop because its forwarding table was not updated.","debug":"Check route computation, control-plane distribution, forwarding-table installation, and actual interface behavior."},"module-4-2":{"why":"Router lookup, switching fabric, buffers, and scheduling affect latency even when the selected route is correct.","engineering":"Use queue and link measurements to find packet-processing bottlenecks that CPU graphs may miss.","caseStudy":"Several services burst toward one egress link. Its output queue grows and calls lag while router CPU looks normal.","debug":"Measure queue occupancy, drops, per-class delay, and link use; CPU alone can miss a forwarding bottleneck."},"module-4-3":{"why":"IP prefixes scale destination lookup and appear in subnet design, deployment, NAT, firewall rules, and IPv6 migration.","engineering":"Use longest-prefix reasoning to validate route tables, address plans, and service reachability.","caseStudy":"A /24, /25, and /28 all match a destination; the most specific /28 sends traffic to an unintended subnet.","debug":"Check address, prefix length, gateway, route selection, NAT mapping, and IPv4/IPv6 path independently."},"module-4-4":{"why":"Match/action forwarding and packet scheduling turn network policy into programmable infrastructure and resource allocation.","engineering":"Use rule design and precedence checks in network automation, access policy, telemetry, and traffic engineering.","caseStudy":"A monitoring rule matches a test subnet, but a broader higher-priority rule sends packets elsewhere.","debug":"Check rule priority, installed state, match/action counters, and queue drops; source configuration may not be active configuration."},"module-5-1":{"why":"Link-state routing is a distributed map-making problem. Dijkstra also builds intuition for path algorithms and topology changes.","engineering":"Use graph costs and route recomputation to reason about path selection and convergence after link changes.","caseStudy":"An operator raises a link cost to avoid congestion; routers recompute paths while briefly holding different topology versions.","debug":"Compare advertisements, link costs, computed paths, and installed routes; measure convergence after changes."},"module-5-2":{"why":"Distance-vector routing explains how local estimates create global paths and why failures can converge slowly.","engineering":"Use neighbor updates and loop behavior to understand stale reachability and route instability.","caseStudy":"After a link fails, neighbors advertise stale routes through one another; the destination appears reachable while costs rise.","debug":"Watch next-hop changes, increasing metrics, and convergence delay; routing loops can look like application timeouts."},"module-5-3":{"why":"OSPF areas reduce the scope of detailed topology updates while preserving reachability across a campus or enterprise.","engineering":"Use hierarchy to reason about flooding scope, summarized routes, area boundaries, and large internal networks.","caseStudy":"A new campus building adds links. Areas contain topology detail while area-border routers advertise useful summaries.","debug":"Inspect neighbor adjacency, area membership, database freshness, route calculation, and installed next hop."},"module-5-4":{"why":"BGP connects independently operated networks; route choice reflects policy as well as hop count.","engineering":"Use provider and region comparisons to reason about global reachability, anycast, and traffic engineering.","caseStudy":"One ISP reaches a service region while another does not. Their providers may choose different paths based on policy.","debug":"Compare reachability and latency from multiple networks; your own provider shows only one Internet path."},"module-5-5":{"why":"SDN makes network-wide policy a software deployment problem involving state, rollout, consistency, and rollback.","engineering":"Use staged changes and device verification when automating routing, access policy, or traffic engineering.","caseStudy":"A controller blocks a vulnerable service across switches; partial rollout could leave some paths exposed.","debug":"Track controller health, device acknowledgments, installed rule versions, and traffic counters; an accepted API call is not proof of enforcement."},"module-5-6":{"why":"ICMP and management data turn network behavior into evidence, but each diagnostic sees only part of the system.","engineering":"Combine probes, device counters, and application metrics to locate a failure without overinterpreting a single tool.","caseStudy":"Traceroute stops at a filtered hop while interface counters reveal rising discards on the service path.","debug":"Correlate probes and counters with application success, latency, and errors; diagnostic silence alone is ambiguous."},"module-6-1":{"why":"The link layer delivers a datagram across one adjacent hop. Ethernet and Wi-Fi differ below IP, so local delivery has its own failure modes.","engineering":"Use the hop-by-hop boundary to reason about framing, local addressing, and why MAC addresses change across routers.","caseStudy":"A laptop sends to a remote API, but its first link-layer frame must reach the local gateway, not the remote server.","debug":"Check link state, framing errors, local address resolution, and gateway before blaming the remote service."},"module-6-2":{"why":"Checksums and CRCs detect corruption, but detection is not correction. Recovery belongs to retransmission or added redundancy.","engineering":"Use integrity signals to distinguish link errors from failures in storage, transport recovery, or application data.","caseStudy":"A bad frame is discarded; TCP may retransmit missing bytes, while a one-way sensor datagram may simply be lost.","debug":"Measure corruption, retry rate, and end-to-end hashes separately; a link check does not verify a stored object."},"module-6-3":{"why":"Multiple-access protocols coordinate devices sharing one medium; their tradeoffs affect throughput, fairness, and latency.","engineering":"Apply the same shared-resource reasoning to Wi-Fi airtime and other systems with many competing senders.","caseStudy":"A busy access point serves voice and bulk downloads. Airtime contention hurts the call even though it uses little bandwidth.","debug":"Measure airtime, retries, collision indicators, and per-device latency; signal strength alone does not show fairness."},"module-6-4":{"why":"ARP and Ethernet switching explain local delivery. An off-subnet datagram is framed for the gateway's MAC address.","engineering":"Use ARP, switch tables, VLANs, and gateway settings to debug why a reachable LAN host cannot reach a remote service.","caseStudy":"A laptop calls a remote API, ARPs for the gateway, and sends the first frame through a switch to the router.","debug":"Inspect ARP cache, switch MAC table, VLAN, subnet mask, and gateway; each covers a different step."},"module-6-5":{"why":"VLANs and data-center fabrics separate logical network structure from physical wiring, shaping isolation and east-west traffic.","engineering":"Use segmentation and fabric knowledge to reason about service reachability, trust boundaries, and scale between racks.","caseStudy":"Guest devices and employee laptops share switches but should not share a broadcast domain or internal access.","debug":"Check VLAN tags, trunk allowlists, gateway policy, routes, and fabric utilization from endpoints as well as configuration."},"module-7-1":{"why":"Radio links change with distance, walls, reflection, interference, and competing senders; applications inherit that variability.","engineering":"Use wireless measurements to understand why an app slows in a location even when its code and IP address are unchanged.","caseStudy":"A photo upload is fast at home but slow in a crowded cafe where interference and retries consume airtime.","debug":"Compare signal quality, retries, channel use, and application latency before blaming the server."},"module-7-2":{"why":"Wi-Fi shares radio airtime through access points. Many small requests can slow a crowded network despite modest bandwidth use.","engineering":"Reduce unnecessary polling and account for contention when designing mobile and campus applications.","caseStudy":"An app works in an empty lab but stalls in a lecture hall where hundreds of clients contend for one access point.","debug":"Measure channel busy time, retries, client count, and request rate; reducing unnecessary polling can help."},"module-7-3":{"why":"Bluetooth and Zigbee connect nearby devices with different power, range, and throughput goals; protocol choice affects battery and pairing.","engineering":"Use these tradeoffs when designing wearables, sensor products, and mobile integrations that rely on a phone or hub as gateway.","caseStudy":"A sensor sends one reading per minute; a low-power link to a phone or hub may fit better than Wi-Fi.","debug":"Track battery, reconnect time, packet loss, gateway uptime, and pairing failures; radio choice affects support burden."},"module-7-4":{"why":"Cellular networks combine radio access and a carrier core; handoff can briefly change the path as users move between cells.","engineering":"Build client retry and reconnect behavior around mobility instead of assuming every network transition is seamless.","caseStudy":"A delivery app streams location while a driver crosses a cell boundary; client retries should tolerate a brief interruption.","debug":"Compare signal, handoff events, reconnect time, and app-level delivery; test moving devices, not only stationary ones."},"module-8-1":{"why":"Security starts with a threat model, not a library choice. Engineers identify assets, attackers, boundaries, and desired guarantees first.","engineering":"Use threats to choose controls for confidentiality, integrity, authentication, and availability instead of adding security features at random.","caseStudy":"A login API handles passwords, tokens, and reset links; threats include eavesdropping, replay, impersonation, and request floods.","debug":"Connect each control to a threat and guarantee; avoid adding unrelated security mechanisms."},"module-8-2":{"why":"Cryptography supports confidentiality and key establishment, but key storage, distribution, rotation, and compromise response are system design.","engineering":"Use cryptographic mechanisms with a key-management plan for API sessions, backups, and service secrets.","caseStudy":"A backup is encrypted, but its key is stored beside the file; the cipher is strong while the key-management design fails.","debug":"Review key source, lifetime, access policy, rotation, recovery, and compromise response."},"module-8-3":{"why":"Integrity mechanisms show whether data changed and sometimes who created it. A plain hash does not authenticate a publisher.","engineering":"Use hashes, MACs, and signatures for release verification, API integrity, and trusted audit events.","caseStudy":"A build server publishes a binary and hash from the same compromised location; an attacker can replace both.","debug":"Audit signing-key access, provenance, verification, and rotation; trusted origin matters as much as integrity."},"module-8-4":{"why":"Endpoint authentication proves which participant is on the other end; fresh challenges and trusted certificates resist impersonation and replay.","engineering":"Validate server identity and freshness before sending credentials, payments, commands, or private data.","caseStudy":"A client accepts any server certificate, allowing an attacker on public Wi-Fi to impersonate the API despite encryption.","debug":"Test expired, mismatched, untrusted, and replayed credentials; monitor failures without logging secrets."},"module-8-5":{"why":"Security spans message, transport, network, wireless, and perimeter controls. Each protects a different boundary.","engineering":"Combine TLS, VPNs, wireless protection, firewalls, and detection according to their roles; no one layer replaces app authorization.","caseStudy":"A remote engineer uses Wi-Fi, TLS, possibly a VPN, and firewall policy to reach an API; each layer has distinct responsibilities.","debug":"Map evidence to certificate errors, VPN state, Wi-Fi authentication, firewall denies, and IDS alerts."},"module-9-1":{"why":"Multimedia quality depends on timing and continuity, not just complete delivery; different applications tolerate delay and loss differently.","engineering":"Design around what users perceive in calls, live streams, and stored video, not only successful HTTP responses.","caseStudy":"A recorded lecture can buffer ahead, while a live support call becomes awkward if audio arrives late.","debug":"Track startup, rebuffer ratio, end-to-end delay, late packets, and perceived quality; throughput alone is not enough."},"module-9-2":{"why":"Adaptive streaming responds to changing capacity by selecting chunk quality, helping playback degrade gracefully instead of stall.","engineering":"Use buffer state, throughput estimates, and cache placement to balance picture quality and uninterrupted playback.","caseStudy":"A nearly empty buffer and falling bandwidth make the next high-bitrate chunk risky; lower bitrate can preserve playback.","debug":"Measure buffer level, selected bitrate, download time, rebuffer events, and CDN behavior together."},"module-9-3":{"why":"Voice over IP trades smooth playback against conversational delay using jitter buffers and loss handling.","engineering":"Use deadlines and arrival variation to tune real-time media rather than retransmitting packets after they are useful.","caseStudy":"Packets arrive at 30, 45, and 95 ms intervals; a longer buffer smooths playback but delays speakers.","debug":"Track jitter, late loss, packet loss, one-way delay, and buffer depth under realistic wireless conditions."},"module-9-4":{"why":"Session signaling and media transport are separate jobs. A call can connect while audio fails.","engineering":"Debug call setup and media delivery as distinct paths, including negotiated endpoints, NAT, and firewall behavior.","caseStudy":"SIP setup succeeds, but RTP packets are blocked by NAT or a firewall; the call is connected with no sound.","debug":"Monitor call setup, RTP arrival, loss, jitter, and codec negotiation independently."},"module-9-5":{"why":"QoS allocates limited capacity to traffic with different needs. Priority can protect interactive services but can also starve others.","engineering":"Treat QoS as resource-allocation policy: bound priority, preserve fairness, and verify behavior across the whole path.","caseStudy":"Unlimited voice priority may starve file transfers or network-control traffic during a burst of calls.","debug":"Measure per-class delay, loss, utilization, and fairness; QoS is policy, not extra bandwidth."}};

  function buildLessonPages({ active, modules, txt, esc }) {
  const id=active.id,section=active.closest("section");
  const title=txt(active,"h3"),intro=txt(active,":scope > p"),chapterTitle=txt(section,"h2")||"Computer Networking";
  const lesson=lessonDetails[id];
  const bodyParagraphs=[...(active.querySelector(".module-body")?.querySelectorAll("p")||[])];
  const explanation=bodyParagraphs[0]?.textContent.trim()||intro;
  const example=bodyParagraphs[1]?.textContent.replace(/^In practice:\\s*/,"").trim()||"Trace one request through the system and identify what the destination observes.";
  const following=modules[modules.indexOf(active)+1],nextTitle=following?txt(following,"h3"):"the end-to-end system";
  const act=activities[id]||{prompt:"Trace the system from input to result, then explain what changes under failure.",walkthrough:explanation};
  const goals=["Explain why "+title.toLowerCase()+" matters to a networked product.","Trace the mechanism and identify which component owns each step.","Apply the model to a design or debugging decision."];
  if(id==="module-1-1") return ["<div class='section-kicker'>START WITH THE WHOLE JOURNEY · CHAPTER 1</div><h2 id='reader-title' tabindex='-1'>From URL to page</h2><p class='reader-intro'>When you enter a URL, your browser coordinates several systems to turn a name into a response and then into pixels. The request crosses your device’s access network, one or more provider networks, and the service’s network. Each part has a different job.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>When a feature fails, the cause may sit outside your code: name resolution, the local network, a route, congestion, or the service edge. Knowing the path helps you locate the boundary where behavior first changes.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Trace a browser request from a URL to a server and back.</li><li>Explain the roles of end systems, access networks, routers, and the network core.</li><li>Use observations from a browser and basic network tools to form a testable failure hypothesis.</li></ol><p><strong>Keep this distinction in mind:</strong> a browser request is application data; the network carries it in packets, hop by hop.</p>","<div class='section-kicker'>FOLLOW ONE REQUEST · BUILD THE SYSTEM MODEL</div><h2 id='reader-title' tabindex='-1'>Six stops along the path</h2><p class='reader-intro'>A simplified page load is a chain of cooperating jobs. Real browsers reuse cached DNS answers and connections, so not every visit repeats every step.</p><ol><li><strong>Browser and device:</strong> the browser interprets the URL and prepares a request for the host and resource.</li><li><strong>Name lookup:</strong> DNS helps the device find an IP address for the host. This is a separate network exchange.</li><li><strong>Access network:</strong> Wi-Fi or Ethernet carries packets from the device toward a local router and the provider.</li><li><strong>Network core:</strong> routers forward packets toward the destination using routing and forwarding information. Shared links can queue packets when traffic is heavy.</li><li><strong>Service edge:</strong> the destination network delivers packets to a server or load balancer; the application creates a response.</li><li><strong>Return and render:</strong> response packets travel back, the browser receives the response, and application code builds the visible page.</li></ol><div class='reader-callout'><strong>What changes at each hop?</strong><p>The link used for the next hop can change as a packet crosses networks. The destination remains the service’s IP address until the packet reaches that destination or a network function changes it.</p></div><p>The path for the response may differ from the outbound path. This is why “the server is reachable from somewhere” does not prove every user has a healthy path.</p>","<div class='section-kicker'>INCIDENT THINKING · A SOFTWARE CASE</div><h2 id='reader-title' tabindex='-1'>Works at the office, fails at home</h2><p class='reader-intro'>A customer reports that your app loads at work but hangs on their home connection. The release and account are unchanged. Treat the report as a clue about where the paths differ, not proof that the home router is at fault.</p><ol><li><strong>Clarify the symptom:</strong> does the page fail before it appears, after a long wait, or only for one API call?</li><li><strong>Compare the name:</strong> does the hostname resolve on both networks, and do the answers differ?</li><li><strong>Locate the connection boundary:</strong> does the browser establish a connection and complete TLS, or does it time out earlier?</li><li><strong>Separate server response from page load:</strong> is the first response slow, or are later assets and API calls slow?</li><li><strong>Compare paths and locations:</strong> test from another network or region, then compare server, CDN, and provider telemetry.</li></ol><div class='reader-callout'><strong>Engineering lesson</strong><p>Change one variable at a time. If you change DNS, retry logic, and a server setting together, you may restore service without learning which boundary failed.</p></div><p>A 403 or 500 response means an HTTP server answered; a connection timeout means the browser did not get that far. Those symptoms call for different investigations.</p>","<div class='section-kicker'>APPLY IT · TRACE A REAL REQUEST</div><h2 id='reader-title' tabindex='-1'>Build your own evidence</h2><p class='reader-intro'>Use a public example domain to observe what each tool can tell you. You can do the browser steps alone; the terminal commands are optional.</p><ol><li>Open your browser’s Network panel, visit <strong>https://example.com</strong>, and select the main document request.</li><li>Record the status, remote address if shown, protocol, and timing. Notice whether time is spent waiting for the server or downloading the response.</li><li>Look up the hostname with <code>nslookup example.com</code>. Record whether it resolves and the address returned.</li><li>Inspect a route with <code>traceroute example.com</code> on macOS/Linux or <code>tracert example.com</code> on Windows. Some hops may not answer; that alone does not mean the path is broken.</li><li>Run <code>curl -v https://example.com</code> to observe connection and TLS negotiation alongside the HTTP response. Compare its result with the browser.</li></ol><div class='reader-callout'><strong>Write down the boundary</strong><p>For each observation, name what it confirms and what it cannot confirm. DNS resolution does not prove the server is reachable; one unanswered traceroute hop does not prove packets stop there.</p></div><label for='practice-notes'><strong>Your trace notes</strong></label><textarea id='practice-notes' placeholder='URL → DNS → access link → routers → service edge → response. Note evidence and unknowns…'></textarea><details><summary>Compare with one possible interpretation</summary><p>If DNS returns an address, the name lookup succeeded for that resolver at that moment. If curl completes TLS and receives an HTTP status, a service answered over that path. The browser waterfall shows where the page load spent time. None of these alone proves every user or every route is healthy.</p></details>","<div class='section-kicker'>TURN EVIDENCE INTO A DECISION · TRANSFER</div><h2 id='reader-title' tabindex='-1'>From observation to diagnosis</h2><p class='reader-intro'>A useful incident note separates what you observed from what you infer. That keeps a team from jumping straight to “the network is down” or “the server is slow.”</p><div class='reader-callout'><strong>Use this four-part report</strong><p><strong>Symptom:</strong> what the user sees. <strong>Boundary:</strong> the last step known to work. <strong>Evidence:</strong> the measurement that supports it. <strong>Next test:</strong> the smallest check that distinguishes likely causes.</p></div><p><strong>Self-check:</strong></p><ol><li>Why can identical application code behave differently from two networks?</li><li>What does a successful DNS lookup establish, and what is still unknown?</li><li>How would you distinguish a slow server response from a slow download?</li></ol><details><summary>Review one diagnosis</summary><p>If DNS resolves and TLS completes, but the first byte takes several seconds, compare server and CDN response timing before changing client retries. If the first byte arrives quickly but the page finishes slowly, inspect response size, later API calls, and other assets. These tests narrow the boundary; they do not identify a root cause by themselves.</p></details><p><strong>Connect forward:</strong> next, see how packets share links and why queues can add delay even when every router is forwarding correctly.</p>"];
  const genericPages = [
   '<div class="section-kicker">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id="reader-title" tabindex="-1">Why learn this?</h2><p class="reader-intro">'+esc(lesson.why)+'</p><div class="reader-callout"><strong>Where software engineers use it</strong><p>'+esc(lesson.engineering)+'</p></div><p><strong>By the end, you should be able to:</strong></p><ol>'+goals.map(x=>"<li>"+esc(x)+"</li>").join("")+'</ol><p><strong>Chapter connection:</strong> '+esc(chapterTitle)+' connects application behavior to the network services beneath it.</p>',
   '<div class="section-kicker">THE MECHANISM · BUILD A MENTAL MODEL</div><h2 id="reader-title" tabindex="-1">System model</h2><p class="reader-intro">'+esc(explanation)+'</p><div class="reader-callout"><strong>See it in practice</strong><p>'+esc(example)+'</p></div><ol><li>Identify the input, sender, receiver, or state this mechanism uses.</li><li>Trace the rule or exchange that changes what happens next.</li><li>Name the result and the guarantee it provides to the next component.</li></ol><p>Keep the boundary clear: this mechanism may solve one part of delivery while another layer owns reliability, security, or application meaning.</p>',
   '<div class="section-kicker">DESIGN AND OPERATIONS · A SOFTWARE CASE</div><h2 id="reader-title" tabindex="-1">Engineering case</h2><p class="reader-intro">'+esc(lesson.caseStudy)+'</p><div class="reader-callout"><strong>What to investigate</strong><p>'+esc(lesson.debug)+'</p></div><p>Reason through the case: identify the symptom, locate the component and state that control it, then choose a change and name the tradeoff it introduces.</p>',
   '<div class="section-kicker">APPLY IT · WORK LIKE AN ENGINEER</div><h2 id="reader-title" tabindex="-1">Hands-on practice</h2><p class="reader-intro">'+esc(act.prompt)+'</p><div class="reader-callout"><strong>Connect it to a software system</strong><p>'+esc(lesson.caseStudy)+'</p></div><p>Write down assumptions, trace the mechanism, and predict what you would observe if it failed. Use the notes area to sketch a path, compare options, or plan a test.</p><label for="practice-notes"><strong>Your working notes</strong></label><textarea id="practice-notes" placeholder="Draw the path, list assumptions, or write a test plan…"></textarea><details><summary>Compare with one possible solution</summary><p>'+esc(act.walkthrough)+'</p></details>',
   '<div class="section-kicker">DEBUG · CONNECT · TRANSFER</div><h2 id="reader-title" tabindex="-1">Transfer checkpoint</h2><p class="reader-intro">Use this topic in a code review, incident, or design discussion.</p><div class="reader-callout"><strong>What to inspect in a real system</strong><p>'+esc(lesson.debug)+'</p></div><p><strong>Self-check:</strong></p><ol><li>Why does this topic matter for the product or network?</li><li>Can you trace the mechanism without looking back?</li><li>What measurement would support your explanation during an incident?</li></ol><details><summary>Review the core idea</summary><p>'+esc(explanation)+' '+esc(example)+'</p></details><p><strong>Connect forward:</strong> '+(following?'connect this idea to '+esc(nextTitle)+' and identify what service or information that module depends on.':'bring this idea together with the end-to-end system and identify how the layers cooperate.')+'</p>'
  ];
  if(id==="module-1-2") genericPages[3]="<div class='section-kicker'>EXPERIMENT · PACKETS COMPETE FOR A LINK</div><h2 id='reader-title' tabindex='-1'>Make the queue visible</h2><p class='reader-intro'>A link can transmit only so many packets per second. When packets arrive faster than it can send them, they wait in a queue; if the buffer fills, new packets are dropped. Adjust the controls and watch the system change.</p><div class='queue-lab' data-queue-lab><div class='queue-lab-grid'><div class='queue-controls'><div class='queue-control'><label for='queue-arrival'>Average packet arrivals</label><output data-queue-output='arrival'>4 packets/s</output><input id='queue-arrival' data-queue-input='arrival' type='range' min='1' max='10' step='1' value='4'></div><div class='queue-control'><label for='queue-service'>Link service capacity</label><output data-queue-output='service'>6 packets/s</output><input id='queue-service' data-queue-input='service' type='range' min='1' max='10' step='1' value='6'></div><div class='queue-control'><label for='queue-burst'>Packets grouped in each burst</label><output data-queue-output='burst'>2 packets</output><input id='queue-burst' data-queue-input='burst' type='range' min='1' max='4' step='1' value='2'></div><button class='queue-reset' type='button' data-queue-reset>Reset experiment</button><p class='queue-note'>The model runs a repeatable 10-second sample with a buffer for 5 waiting packets. Burstiness changes how arrivals are grouped; it does not change the average arrival rate.</p></div><div class='queue-results'><div class='queue-metrics'><div class='queue-metric'><span>Offered load</span><strong data-queue-metric='load'>67%</strong></div><div class='queue-metric'><span>Peak packets in system</span><strong data-queue-metric='peak'>2</strong></div><div class='queue-metric'><span>Average wait before service</span><strong data-queue-metric='wait'>0.08 s</strong></div><div class='queue-metric'><span>Packets dropped</span><strong data-queue-metric='dropped'>0</strong></div></div><div class='queue-lane' aria-label='Packet path'><div class='queue-lane-node'>Arrivals</div><span class='queue-lane-arrow' aria-hidden='true'>→</span><div class='queue-lane-node'>Queue<div class='queue-packets' data-queue-stack aria-hidden='true'>■ ■</div></div><span class='queue-lane-arrow' aria-hidden='true'>→</span><div class='queue-lane-node'>Link</div></div><p class='queue-status' data-queue-status role='status' aria-live='polite'>Average capacity is sufficient, but bursts build temporary queues.</p></div></div></div><p><strong>Notice:</strong> a low average load can still create short waits when packets arrive together. Near or above 100% utilization, the link has little room to drain bursts; a bigger buffer can postpone drops, but cannot solve sustained overload.</p><label for='practice-notes'><strong>Your experiment notes</strong></label><textarea id='practice-notes' placeholder='Try one change at a time. What happened to waiting time and drops?…'></textarea><details><summary>Compare with one possible explanation</summary><p>With arrivals at 4 packets/s and service at 6 packets/s, average utilization is about 67%. Grouping arrivals in pairs still creates a brief queue, but the link has time to drain it before the next burst. Raise arrivals above service and the backlog grows until the finite buffer drops packets. This simplified model isolates queueing; real networks have variable packet sizes, scheduling, and many flows.</p></details>";
  if(id==="module-1-3") return ["<div class=\"section-kicker\">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id=\"reader-title\" tabindex=\"-1\">Why delay and throughput matter</h2><p class=\"reader-intro\">A request can be correct and still feel broken if it takes too long. Delay describes how long one packet or operation takes to cross a system; throughput describes how much data the system can move over time. They are related, but they answer different questions.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>These measures shape API latency targets, upload progress, database placement, streaming quality, and the capacity needed for a service. “Add bandwidth” only helps when link capacity is the bottleneck; it will not remove the speed-of-light delay to a distant region or slow server processing.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Separate processing, queueing, transmission, and propagation delay.</li><li>Calculate transmission and propagation delay from packet size, link rate, distance, and signal speed.</li><li>Find a path’s throughput bottleneck and choose a fix that targets the measured cause.</li></ol><p><strong>Anchor idea:</strong> latency is the time for a particular trip; throughput is the rate of sustained delivery. A fast highway can carry many cars per hour, but it does not make a faraway destination closer.</p>","<div class=\"section-kicker\">THE MECHANISM · FOUR SOURCES OF DELAY</div><h2 id=\"reader-title\" tabindex=\"-1\">What a packet’s wait is made of</h2><p class=\"reader-intro\">At each router, a packet may be processed, wait for its outgoing link, take time to be pushed onto that link, and then travel across the medium. Across multiple hops, the pieces accumulate.</p><ol><li><strong>Processing delay:</strong> time to inspect a header, check for errors, and choose an outgoing interface. It is often small, but overloaded hardware can increase it.</li><li><strong>Queueing delay:</strong> time waiting behind other packets for the outgoing link. It varies with traffic; as offered load approaches capacity, queues can grow sharply.</li><li><strong>Transmission delay:</strong> time to put all packet bits onto the link. It is <code>L / R</code>, where <code>L</code> is packet length in bits and <code>R</code> is link rate in bits per second.</li><li><strong>Propagation delay:</strong> time for a signal to travel across the physical medium. It is <code>d / s</code>, where <code>d</code> is distance and <code>s</code> is signal propagation speed.</li></ol><div class=\"reader-callout\"><strong>Do not mix these up</strong><p>Transmission is about packet size and link rate; propagation is about distance and medium. A packet can finish transmission before its first bit has reached the far end.</p></div><p>For one hop, <code>d<sub>nodal</sub> = d<sub>proc</sub> + d<sub>queue</sub> + d<sub>trans</sub> + d<sub>prop</sub></code>. For an end-to-end path, sum the delays across hops and include endpoint and application work where relevant.</p>","<div class=\"section-kicker\">DESIGN AND OPERATIONS · A SOFTWARE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">The API that is slow only from one region</h2><p class=\"reader-intro\">Your service has a 100-Mbit/s server link and healthy CPU metrics. Users in a distant region report that every request takes about 110 ms longer, while users near the service remain fast. A bulk upload also causes occasional spikes for everyone.</p><ol><li><strong>Compare the baseline:</strong> measure client-to-server round-trip time, server processing time, and time-to-first-byte by region.</li><li><strong>Separate constant from variable delay:</strong> a stable regional increase suggests path distance or routing; spikes that correlate with the upload suggest queueing.</li><li><strong>Check the bottleneck:</strong> the path includes 1-Gbit/s, 100-Mbit/s, and 20-Mbit/s links. Sustained throughput cannot exceed the 20-Mbit/s hop, before protocol overhead.</li><li><strong>Choose a targeted change:</strong> a nearby edge or regional deployment can reduce propagation; shaping or scheduling the backup can reduce queueing; raising capacity can improve throughput only if the constrained link is upgraded.</li></ol><div class=\"reader-callout\"><strong>Engineering lesson</strong><p>Do not use one “slow network” metric to explain every symptom. Compare latency percentiles, throughput, server time, and queue or loss signals; each points toward a different part of the system.</p></div><p>A CDN can shorten the trip for cacheable content, but dynamic requests still depend on the origin path. A larger pipe helps a large transfer; it may barely change a tiny request whose delay is dominated by round-trip time.</p>","<div class=\"section-kicker\">APPLY IT · CALCULATE, THEN TEST</div><h2 id=\"reader-title\" tabindex=\"-1\">Build a latency budget</h2><p class=\"reader-intro\">Work through this upload path. A 12-MB file crosses a 20-Mbit/s bottleneck link; the link is 1,000 km long; signal speed is approximately 200,000 km/s. Ignore headers and endpoint processing for the first estimate. Assume queueing adds 50 ms.</p><div class='latency-lab' data-latency-lab><div class='latency-lab-head'><span>CHAPTER 1 LAB · LATENCY BUDGET</span><strong>Change one constraint at a time</strong></div><div class='latency-lab-grid'><div class='latency-controls'><label>File size <output data-latency-value='file'>12 MB</output><input data-latency-input='file' type='range' min='1' max='40' value='12'></label><label>Link rate <output data-latency-value='rate'>20 Mbit/s</output><input data-latency-input='rate' type='range' min='5' max='200' step='5' value='20'></label><label>Distance <output data-latency-value='distance'>1,000 km</output><input data-latency-input='distance' type='range' min='100' max='10000' step='100' value='1000'></label><label>Queueing <output data-latency-value='queue'>50 ms</output><input data-latency-input='queue' type='range' min='0' max='500' step='10' value='50'></label></div><div class='latency-results'><div><span>Transmission</span><strong data-latency-result='transmission'>4,800 ms</strong></div><div><span>Propagation</span><strong data-latency-result='propagation'>5 ms</strong></div><div><span>Queueing</span><strong data-latency-result='queue'>50 ms</strong></div><div class='latency-total'><span>Estimated one-link time</span><strong data-latency-result='total'>4,855 ms</strong></div><p data-latency-status>Transmission dominates this large transfer. Raising the link rate changes the budget most.</p></div></div></div><ol><li>Convert the file to bits: <code>12 MB × 8 = 96 Mbit</code>.</li><li>Find transmission delay: <code>96 Mbit ÷ 20 Mbit/s = 4.8 s</code>.</li><li>Find propagation delay: <code>1,000 km ÷ 200,000 km/s = 0.005 s = 5 ms</code>.</li><li>Add the given queueing: <code>4,800 ms + 5 ms + 50 ms = 4,855 ms</code> for this simplified one-link estimate.</li></ol><div class=\"reader-callout\"><strong>Try the counterfactual</strong><p>If the link rate rises to 100 Mbit/s, transmission becomes 960 ms and the estimate becomes 1,015 ms. If instead the route is shortened to 100 km, propagation falls by only 4.5 ms. For this large file, which change buys more time, and why?</p></div><label for=\"practice-notes\"><strong>Your decision notes</strong></label><textarea id=\"practice-notes\" placeholder=\"Which delay component dominates? What would you measure before spending on a fix?\"></textarea><details><summary>Check your reasoning</summary><p>The 100-Mbit/s upgrade reduces transmission delay by 3.84 seconds in this simplified example; shortening the path saves 4.5 ms. But this does not mean bandwidth is always the answer. For a small API request, fixed propagation and round trips can dominate; for a loaded shared link, queueing may dominate; for slow application code, network changes may not help.</p></details>","<div class=\"section-kicker\">DEBUG · CONNECT · TRANSFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Choose the right lever</h2><p class=\"reader-intro\">A useful performance investigation starts with a symptom and a measurement, then maps the evidence to a delay component or bottleneck. Keep latency and throughput separate in the incident report.</p><div class=\"reader-callout\"><strong>Quick diagnostic map</strong><p><strong>Large transfer is slow, RTT is fine:</strong> inspect bottleneck capacity, congestion, loss, and receiver limits. <strong>Small requests are slow across a distant path:</strong> inspect round trips, placement, and connection reuse. <strong>Latency spikes under a burst:</strong> inspect queueing and offered load. <strong>Network timing is low but response is slow:</strong> inspect application and database work.</p></div><p><strong>Self-check:</strong></p><ol><li>Why can a 1-Gbit/s link still have high propagation delay?</li><li>What happens to transmission delay if packet length doubles while link rate stays fixed?</li><li>Why does the slowest link constrain end-to-end throughput?</li><li>Which measurement would distinguish a distant path from a congested queue?</li></ol><details><summary>Review the core ideas</summary><p>Propagation depends on distance and signal speed, not link bandwidth. Doubling packet length doubles transmission delay at a fixed rate. The bottleneck link limits sustained throughput along a path. Stable added delay by region is consistent with distance; variable delay under load is consistent with queueing, so compare latency distributions and load-correlated metrics.</p></details><p><strong>Connect forward:</strong> next, use layering to locate which part of the request owns each measurement and which protocol provides the service.</p>"];
  if(id==="module-1-4") return ["<div class=\"section-kicker\">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id=\"reader-title\" tabindex=\"-1\">Why networking uses layers</h2><p class=\"reader-intro\">A web request is not one indivisible message. It is application meaning carried by transport behavior, addressed across networks, delivered over a local link, and encoded as signals. Layering divides that work into boundaries so each part can evolve without requiring every other part to be redesigned.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Layers help you locate ownership. A failed name lookup, refused TCP connection, TLS error, HTTP 503, and malformed response are different failures; the right logs and fix depend on which boundary failed. They also let an API use TCP or QUIC without changing what its request means.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Describe the job each Internet layer provides to the one above it.</li><li>Trace encapsulation as data moves down the stack and decapsulation on the way back up.</li><li>Use protocol and header evidence to locate a failure without blaming the whole “network.”</li></ol><p><strong>Anchor idea:</strong> each layer adds just enough control information for its own delivery job; it does not replace the meaning owned by the layers above it.</p>","<div class=\"section-kicker\">THE MECHANISM · ENCAPSULATION</div><h2 id=\"reader-title\" tabindex=\"-1\">One request, nested for delivery</h2><p class=\"reader-intro\">Imagine an application creates an HTTP request. As it moves down the stack, each layer wraps the data it receives with its own header. At the destination, the process reverses: each layer reads and removes the header it understands, then hands the remaining payload upward.</p><ol><li><strong>Application:</strong> HTTP defines the request and response semantics; the application data might be a request line, headers, and a body.</li><li><strong>Transport:</strong> TCP provides a reliable, ordered byte stream between processes using port numbers; UDP offers datagrams with less built-in behavior. The transport unit is commonly called a segment for TCP.</li><li><strong>Network:</strong> IP addresses a packet from source host to destination host and supports forwarding across multiple networks; its unit is a datagram or packet.</li><li><strong>Link:</strong> Ethernet or Wi-Fi delivers a frame across one local link to the next hop. Link-layer addresses are used on that local segment.</li><li><strong>Physical:</strong> bits are represented as electrical, radio, or optical signals in the medium.</li></ol><div class=\"reader-callout\"><strong>The wrapper changes at each hop</strong><p>A router typically removes the incoming link-layer frame and places the IP datagram inside a new frame for the next link. The IP destination generally remains the final host; the link destination changes to the next hop.</p></div><p>Common names for the data units are application message, TCP segment or UDP datagram, IP datagram, link-layer frame, and bits. Exact names and details vary by protocol, but the nesting model is a useful debugging map.</p>","<div class=\"section-kicker\">DESIGN AND OPERATIONS · A SOFTWARE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">The connection works, but the feature fails</h2><p class=\"reader-intro\">A mobile client can resolve the API hostname and complete a TCP connection. TLS succeeds too; the server then returns HTTP 503. The team reports “the network is broken,” but the evidence already narrows the failure boundary.</p><ol><li><strong>DNS succeeded:</strong> a resolver returned an address. This does not prove the address is current or that the service is healthy.</li><li><strong>Transport connected:</strong> a TCP handshake completed, so a process accepted the connection at that address and port.</li><li><strong>TLS succeeded:</strong> the client and endpoint negotiated encryption and identity checks for this connection.</li><li><strong>HTTP returned 503:</strong> an HTTP-speaking server or intermediary responded that the service is unavailable. The request reached an application-facing layer.</li></ol><div class=\"reader-callout\"><strong>What to do next</strong><p>Correlate request IDs across the load balancer and service; inspect upstream health, deployment state, and application logs. Keep the status code and protocol milestones in the incident note instead of collapsing them into “connectivity.”</p></div><p>Layer boundaries also guide design. If a client retries a request, ask whether the operation is safe to repeat; transport reliability does not automatically make an application operation idempotent.</p>","<div class=\"section-kicker\">APPLY IT · TRACE THE WRAPPERS</div><h2 id=\"reader-title\" tabindex=\"-1\">Build the packet around an API request</h2><p class=\"reader-intro\">Work through this simplified outbound request. The application creates an 800-byte HTTP message. Ignore TLS, TCP options, IP options, VLAN tags, and padding so the arithmetic stays focused.</p><div class='encapsulation-lab' data-encapsulation-lab><div class='encapsulation-lab-head'><div><span class='encapsulation-kicker'>CHAPTER 1 LAB · ENCAPSULATION</span><h3>Assemble one request</h3></div><button type='button' class='encapsulation-reset' data-encapsulation-reset>Reset</button></div><p class='encapsulation-status' data-encapsulation-status>Start with an 800-byte HTTP message. Add the transport wrapper when the application hands it to TCP.</p><div class='encapsulation-stack' data-encapsulation-stack aria-live='polite'><div class='packet-layer packet-app'><b>HTTP message</b><span>800 B · method, path, headers, body</span></div></div><div class='encapsulation-readout'><div><span>Current data unit</span><strong data-encapsulation-unit>Application message</strong></div><div><span>Bytes before link overhead</span><strong data-encapsulation-bytes>800 B</strong></div><div><span>Identifier in focus</span><strong data-encapsulation-id>HTTP method + path</strong></div></div><button type='button' class='encapsulation-next' data-encapsulation-next>Add TCP header</button><p class='encapsulation-note'>Each wrapper has a different job. Ports locate a process; IP addresses route across networks; MAC addresses deliver across one local link.</p></div><ol><li><strong>Application message:</strong> 800 bytes containing the HTTP request and its application headers.</li><li><strong>TCP segment:</strong> add a 20-byte TCP header; total is <code>820 bytes</code>. The source and destination ports identify the communicating processes.</li><li><strong>IP datagram:</strong> add a 20-byte IPv4 header; total is <code>840 bytes</code>. Source and destination IP addresses support delivery across networks.</li><li><strong>Ethernet frame:</strong> add a 14-byte header and 4-byte frame check sequence; total is <code>858 bytes</code>. The destination MAC is typically the local router’s interface if the API is remote.</li><li><strong>On the wire:</strong> the frame is transmitted as bits/signals on the local medium. The switch or access point uses link-layer information; a router uses the IP destination to choose the next network hop.</li></ol><div class=\"reader-callout\"><strong>Now reverse it at the server</strong><p>The receiver checks each wrapper at its layer and passes the enclosed data upward. The server’s network interface receives a frame addressed to it; IP recognizes the host; TCP delivers bytes to the socket; the application parses the HTTP message.</p></div><label for=\"practice-notes\"><strong>Your encapsulation sketch</strong></label><textarea id=\"practice-notes\" placeholder=\"HTTP message → TCP segment → IP datagram → Ethernet frame → bits. Note which address or identifier each layer uses.\"></textarea><details><summary>Check the address roles</summary><p>TCP ports identify processes at the two endpoints. IP addresses identify the source and destination hosts across networks. Ethernet source/destination addresses deliver a frame on one link; for a remote server, the first frame is usually addressed to the local router, not directly to the remote server.</p></details>","<div class=\"section-kicker\">DEBUG · CONNECT · TRANSFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Use layers as an incident map</h2><p class=\"reader-intro\">In practice, teams mix browser traces, operating-system tools, packet captures, and service logs. Layering gives those observations a shared structure and keeps the investigation moving from the earliest failing boundary upward.</p><div class=\"reader-callout\"><strong>A compact fault-isolation ladder</strong><p><strong>Name:</strong> does DNS return an expected address? <strong>Path and host:</strong> can packets reach the host? <strong>Transport:</strong> does the port accept a connection? <strong>Security:</strong> does TLS validate and negotiate? <strong>Application:</strong> does HTTP or the API return the expected result?</p></div><p><strong>Self-check:</strong></p><ol><li>Why can an Ethernet frame’s destination change at a router while the IP destination stays the same?</li><li>Which layer uses port numbers to deliver bytes to a process?</li><li>If TCP and TLS succeed but HTTP returns 503, where would you investigate next?</li><li>Why does TCP reliability not guarantee that retrying a payment request is safe?</li></ol><details><summary>Review the core ideas</summary><p>Each link uses its own frame and next-hop address, while the IP datagram is routed toward its destination. Transport ports identify processes. An HTTP 503 narrows the issue to an application-facing server or intermediary, so inspect service and upstream health. TCP can faithfully deliver a request twice if an application retries; safe repetition must be designed at the application layer, often with idempotency keys.</p></details><p><strong>Connect forward:</strong> next, zoom into application processes and sockets; they use these lower-layer services to communicate across the Internet.</p>"];
  if(id==="module-2-1") return ["<div class=\"section-kicker\">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id=\"reader-title\" tabindex=\"-1\">A network app is processes talking</h2><p class=\"reader-intro\">A user sees a screen, but networking begins with processes: running programs that need to exchange data. The browser, your API service, a database proxy, and a background worker can all be separate processes, sometimes on different machines. The network is the communication path between them.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>This model helps you decide where work runs, which component must stay available, how clients find a service, and what to inspect when a connection fails. It also makes architecture tradeoffs concrete: a central service is easier to govern; a peer system can distribute load but adds discovery and trust problems.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Distinguish a process, a host, and a socket.</li><li>Explain client-server and peer-to-peer roles, including how one process can play both roles.</li><li>Trace a connection using endpoint addresses, ports, and the transport protocol.</li></ol><p><strong>Start with the whole:</strong> the user action causes one process to ask another process for a service; sockets connect those processes to the transport layer that carries their messages.</p>","<div class=\"section-kicker\">THE MECHANISM · PROCESS TO SOCKET</div><h2 id=\"reader-title\" tabindex=\"-1\">Where an application meets the network</h2><p class=\"reader-intro\">An application process writes to and reads from a socket, its software doorway to transport. A server listens on a known port; a client opens a socket from a temporary local port to that server endpoint.</p><ol><li><strong>Process:</strong> a running program, such as a browser or API server. A host can run many processes at once.</li><li><strong>Socket:</strong> the interface an application uses to send or receive data through a transport protocol.</li><li><strong>Endpoint:</strong> an IP address plus a port identifies a host interface and a transport destination for a process. A client might use <code>192.0.2.14:53124</code>; an HTTPS service might listen at <code>203.0.113.80:443</code>.</li><li><strong>Connection:</strong> for TCP, a flow is identified by protocol and the source/destination IP-address and port pair. Many clients can connect to the same server port because their full endpoint pairs differ.</li></ol><div class=\"reader-callout\"><strong>Client-server is a role, not a kind of computer</strong><p>The client initiates a request for a service; the server process waits for requests and responds. One host may be a client in one conversation and a server in another.</p></div><p>With UDP, applications exchange datagrams without TCP’s connection setup and reliable ordered byte stream. The service still needs to know which process should receive each datagram; ports help provide that delivery.</p>","<div class=\"section-kicker\">DESIGN AND OPERATIONS · AN ARCHITECTURE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">One service, many clients</h2><p class=\"reader-intro\">A mobile app, web browser, and scheduled job all need the same account and billing rules. A client-server API centralizes those rules behind a service endpoint. But the choice is not free: a central service becomes a capacity and availability dependency.</p><ol><li><strong>Where does authority live?</strong> Authentication, billing state, and audit records usually need a trusted source of truth; a server can enforce consistent policy.</li><li><strong>How is the service found?</strong> Clients need a stable name or discovery mechanism; DNS and load balancing can map that name to healthy server instances.</li><li><strong>What happens at scale?</strong> Add instances behind a service endpoint, then consider state, load distribution, and how clients reconnect after failure.</li><li><strong>Could peers help?</strong> Peer-to-peer distribution can reduce central bandwidth or improve locality, but peers may be intermittent or untrusted. Discovery, identity, abuse prevention, and data integrity become explicit design work.</li></ol><div class=\"reader-callout\"><strong>Engineering lesson</strong><p>“P2P scales better” is not a complete design argument. Compare the bottleneck it removes with the coordination, privacy, security, and user-experience costs it introduces.</p></div><p>For a small product, a straightforward client-server design is often easier to operate. For large content distribution or decentralized collaboration, peer participation may be useful for specific data paths while a service still handles accounts, discovery, or trust.</p>","<div class=\"section-kicker\">APPLY IT · MAP A LIVE FEATURE</div><h2 id=\"reader-title\" tabindex=\"-1\">Trace the chat message</h2><p class=\"reader-intro\">Imagine a user presses Send in a mobile chat app. Trace the software participants before thinking about the packets. Assume the app keeps one secure connection open to a chat service; the service then forwards the message to the recipient’s connected device.</p><ol><li><strong>Name the processes:</strong> sender’s mobile app, chat API or gateway, message-delivery service, and recipient’s app.</li><li><strong>Mark the roles:</strong> the sender app is a client when it submits the message; the gateway is a server for that connection. The gateway may act as a client when it calls another internal service.</li><li><strong>Identify the socket endpoints:</strong> the mobile client uses a local ephemeral port and connects to the service’s address and listening port. The recipient has a separate connection; the server does not magically write into the recipient’s process.</li><li><strong>Follow the application meaning:</strong> the message needs an identity, recipient, ordering or timestamp, and delivery state. TCP can deliver bytes reliably on one connection; the app still defines message boundaries and what “delivered” means.</li><li><strong>Test a failure:</strong> if the recipient is offline, what should persist, who retries, and how will duplicate delivery be prevented?</li></ol><div class=\"reader-callout\"><strong>Compare architecture choices</strong><p>A central server simplifies identity, moderation, and offline queues. Direct peer connections could reduce relay traffic, but NAT, device reachability, privacy, and trust make them harder. A hybrid design may use a server for setup and fall back to a relay.</p></div><label for=\"practice-notes\"><strong>Your system sketch</strong></label><textarea id=\"practice-notes\" placeholder=\"Process → role → socket endpoint → application responsibility. Mark what changes when the recipient is offline.\"></textarea><details><summary>Compare with one possible design</summary><p>The sender app writes a message to its socket; the gateway authenticates it, assigns an application message ID, and places it in a durable queue if the recipient is offline. On reconnect, the service delivers it to the recipient’s app, which deduplicates by ID and acknowledges application-level receipt. TCP helps move bytes on each live connection, but persistence, retry policy, ordering across reconnects, and duplicate handling belong to the application system.</p></details>","<div class=\"section-kicker\">DEBUG · CONNECT · TRANSFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the process behind the port</h2><p class=\"reader-intro\">When a feature cannot connect, check the conversation from the outside inward. A valid hostname does not prove a server process is listening; a listening process does not prove the application protocol or business operation is healthy.</p><div class=\"reader-callout\"><strong>A practical connection checklist</strong><p>Confirm the target name and address; verify the server process is bound to the expected interface and port; check firewall and network policy; confirm the client uses the intended transport; then inspect protocol and application logs. On your own machine, tools such as <code>ss -lntp</code> (Linux) or <code>netstat -ano</code> (Windows) can help identify listening ports and owning processes.</p></div><p><strong>Self-check:</strong></p><ol><li>Can one process act as both client and server? Give an example.</li><li>Why can many clients use the same destination port on one server?</li><li>What responsibilities does TCP provide, and what message behavior must the application still define?</li><li>What new problems must a peer-to-peer design solve compared with a central service?</li></ol><details><summary>Review the core ideas</summary><p>A process can make outgoing requests and accept incoming ones, so roles vary by conversation. Connections are distinguished by endpoint pairs, not just the server’s port. TCP provides a reliable ordered byte stream, but the app defines message framing and semantics. P2P adds discovery, reachability, trust, privacy, and coordination decisions.</p></details><p><strong>Connect forward:</strong> next, look at HTTP as a request–response protocol and see how its methods, status codes, and state shape web APIs.</p>"];
  if(id==="module-2-2") return ["<div class=\"section-kicker\">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id=\"reader-title\" tabindex=\"-1\">HTTP is the contract your app speaks</h2><p class=\"reader-intro\">A browser or mobile app needs a shared way to ask for a resource and understand the result. HTTP defines that exchange: a request carries a method, target, and metadata; a response carries a status, metadata, and often content. The network moves the bytes, while HTTP gives those bytes meaning.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>HTTP choices affect whether retries are safe, whether data can be cached, how clients handle errors, and how much traffic a feature creates. A response can arrive successfully at the transport layer while still representing an application error such as “not authorized” or “service unavailable.”</p></div><p><strong>By the end, you can:</strong></p><ol><li>Read the main parts of an HTTP request and response.</li><li>Choose methods and status codes that express application behavior clearly.</li><li>Reason about retries, caching, and user state without confusing HTTP semantics with transport delivery.</li></ol><p><strong>Anchor idea:</strong> HTTP is a conversation protocol between application processes; it defines the request and response meaning on top of transport.</p>","<div class=\"section-kicker\">THE MECHANISM · REQUEST AND RESPONSE</div><h2 id=\"reader-title\" tabindex=\"-1\">Read the exchange like a trace</h2><p class=\"reader-intro\">A client sends a request to a server. The server interprets it, performs application work, and returns a response. A simplified exchange might look like this:</p><pre><code>GET /api/profile HTTP/1.1\nHost: api.example.test\nAccept: application/json\n\n\nHTTP/1.1 200 OK\nContent-Type: application/json\nCache-Control: private, max-age=60\n\n{\"displayName\":\"Ari\"}</code></pre><ol><li><strong>Method:</strong> <code>GET</code> says what kind of operation the client requests. Other common methods include <code>POST</code>, <code>PUT</code>, <code>PATCH</code>, and <code>DELETE</code>.</li><li><strong>Target:</strong> the path identifies the resource or operation, such as <code>/api/profile</code>.</li><li><strong>Headers:</strong> metadata such as accepted formats, authentication, content type, and caching instructions.</li><li><strong>Body:</strong> optional content sent with a request or response, often JSON for an API.</li><li><strong>Status:</strong> a response code summarizes the outcome, such as <code>200</code> for success, <code>404</code> for a missing resource, or <code>503</code> for temporary service unavailability.</li></ol><div class=\"reader-callout\"><strong>Stateless protocol, stateful product</strong><p>HTTP does not remember prior requests by itself. Applications can connect requests using cookies, authorization tokens, or server-side session records. Those mechanisms make a product feel continuous while each request still carries the context the server needs.</p></div>","<div class=\"section-kicker\">DESIGN AND OPERATIONS · A SOFTWARE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">The retry that charged twice</h2><p class=\"reader-intro\">A checkout client sends a payment request. The server processes it, but the network drops the response before the client receives it. The client sees a timeout and retries. The customer is charged twice.</p><ol><li><strong>Separate delivery from outcome:</strong> the client cannot infer that a timed-out request was never processed. The server may have completed the operation and lost only the response on its way back.</li><li><strong>Use method semantics carefully:</strong> a read such as <code>GET</code> is designed to be safe to repeat; <code>PUT</code> is intended to set a resource to a state and is idempotent when implemented correctly. A <code>POST</code> may create a new action each time.</li><li><strong>Make important retries safe:</strong> attach an idempotency key to a payment operation. The server records the result for that key and returns the same result if the client retries.</li><li><strong>Use status codes as signals:</strong> distinguish validation failures, authorization failures, missing resources, rate limits, and temporary server errors; the client’s response policy should match the meaning.</li></ol><div class=\"reader-callout\"><strong>Engineering lesson</strong><p>HTTP can describe the operation and its outcome, but it cannot make a business action safe by itself. The server must enforce deduplication and the client must handle uncertain outcomes deliberately.</p></div><div class='retry-lab' data-retry-lab><div class='retry-lab-head'><span>CHAPTER 2 LAB · RETRY POLICY</span><strong>Make the uncertainty explicit</strong></div><div class='retry-controls'><label>Operation<select data-retry-operation><option value='read'>GET a profile</option><option value='payment'>POST a payment</option><option value='update'>PUT a saved preference</option></select></label><label>Observed outcome<select data-retry-outcome><option value='timeout'>Client timed out after sending</option><option value='503'>Server returned HTTP 503</option><option value='400'>Server returned HTTP 400</option></select></label><label class='retry-check'><input type='checkbox' data-retry-key> Idempotency key recorded by the server</label></div><div class='retry-result' data-retry-result aria-live='polite'></div></div><p>Caching is another design decision. A cache can reduce repeated work and latency, but cache keys and directives must respect user-specific data. “Same URL” does not always mean “same safe response for every user.”</p>","<div class=\"section-kicker\">APPLY IT · INSPECT A REAL REQUEST</div><h2 id=\"reader-title\" tabindex=\"-1\">Read an API call in your browser</h2><p class=\"reader-intro\">Use a public page or one of your own projects. Open the browser’s Developer Tools, choose the Network panel, and trigger a page load or API action. Select one request and map what you see to HTTP’s contract.</p><ol><li><strong>Find the request:</strong> record the method, URL path, and status code. Identify which action in the UI triggered it.</li><li><strong>Inspect request headers:</strong> look for <code>Accept</code>, <code>Content-Type</code>, authorization or cookie context, and any request ID. Do not copy or share secret token values.</li><li><strong>Inspect the response:</strong> note its content type, cache directives, payload size, and response body shape. Check whether the body explains an error that the status alone does not.</li><li><strong>Reason about repetition:</strong> would a refresh or retry repeat a read or create a new action? What should happen if the response is lost after the server completes work?</li><li><strong>Consider caching:</strong> could this response be reused? Is it public, private to one user, or sensitive enough that it must not be stored by a shared cache?</li></ol><div class=\"reader-callout\"><strong>Try a command-line view</strong><p><code>curl -i https://example.com</code> prints response headers and status along with the body. Add <code>-X</code> only when you intentionally want to change the method; avoid replaying actions that create, delete, or charge something.</p></div><label for=\"practice-notes\"><strong>Your request notes</strong></label><textarea id=\"practice-notes\" placeholder=\"Method + path → status → relevant headers → application meaning → safe retry/cache decision\"></textarea><details><summary>Compare with one possible analysis</summary><p>A <code>GET</code> for a profile returning <code>200</code> with JSON succeeded at the HTTP layer; authentication and data correctness still depend on the response and application rules. A <code>Cache-Control: private</code> directive permits a browser’s private cache but tells shared caches not to reuse that response. For a timed-out payment <code>POST</code>, inspect the payment’s operation ID or idempotency key before retrying.</p></details>","<div class=\"section-kicker\">DEBUG · CONNECT · TRANSFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Turn HTTP evidence into a decision</h2><p class=\"reader-intro\">HTTP traces expose the application conversation. Read them alongside transport and service timings so the team can tell whether a request failed to connect, arrived and was rejected, succeeded but returned unexpected data, or completed with a response the client never received.</p><div class=\"reader-callout\"><strong>A compact review checklist</strong><p>What operation did the client request? Which resource did it target? What status and response body came back? Which headers govern authentication, content, caching, or retries? Could the client safely repeat this operation if the outcome is unknown?</p></div><p><strong>Self-check:</strong></p><ol><li>Why can a client timeout leave the operation’s outcome uncertain?</li><li>What does “stateless HTTP” mean if a website still keeps you signed in?</li><li>Why can a shared cache be unsafe for a profile response?</li><li>What server-side design makes a payment retry safe?</li></ol><details><summary>Review the core ideas</summary><p>A server may finish work while the response is lost, so the client cannot tell whether the action happened. Cookies or tokens carry session context across otherwise independent HTTP requests. Shared caches may serve one user’s private data to another if cache policy and keys are wrong. Idempotency keys let the server recognize repeated attempts and return the original outcome instead of performing the payment twice.</p></details><p><strong>Connect forward:</strong> next, compare how DNS and email systems locate destinations and deliver messages across multiple servers.</p>"];
  if(id==="module-2-3") return ["<div class=\"section-kicker\">WHY IT EXISTS · ENGINEERING CONTEXT</div><h2 id=\"reader-title\" tabindex=\"-1\">Email is a journey across independent systems</h2><p class=\"reader-intro\">When you press Send, the message does not jump directly from your inbox to the recipient’s screen. Your mail client submits it to a mail server; that server looks up the recipient domain’s mail route in DNS; SMTP moves the message between mail servers; the receiving system stores it; and the recipient later retrieves it.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>This model helps you debug notifications, password-reset mail, signup verification, and delivery delays. A message can be accepted by your application, accepted by your mail provider, queued by a relay, or placed in spam; each is a different milestone with different evidence.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Explain how DNS helps a sender find the receiving mail server.</li><li>Distinguish SMTP submission and relay from mailbox access with IMAP or POP3.</li><li>Use DNS answers, SMTP replies, queue age, and retry behavior to locate a delay.</li></ol><p><strong>Start with the whole path:</strong> application → sending mail service → DNS lookup for recipient’s MX → SMTP relay and queue → recipient mailbox → IMAP or webmail.</p>","<div class=\"section-kicker\">THE MECHANISM · DNS FINDS THE NEXT HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">How a domain points mail toward a server</h2><p class=\"reader-intro\">The sender knows the recipient’s email domain, such as <code>example.net</code>, but it needs a server address. DNS supplies the records that make that discovery possible.</p><ol><li><strong>Ask for MX records:</strong> the sender’s resolver looks up the domain’s mail exchanger records. Each MX record names a mail host and gives it a preference value.</li><li><strong>Choose an available exchanger:</strong> lower preference numbers are tried first; another listed exchanger can be tried if the preferred host is unavailable.</li><li><strong>Resolve that host:</strong> DNS then returns an IPv4 address (A record), IPv6 address (AAAA record), or both for the mail host.</li><li><strong>Connect and speak SMTP:</strong> the sending mail server connects to the receiving mail server and offers the message for the recipient.</li></ol><div class=\"reader-callout\"><strong>DNS is a directory with a cache</strong><p>Your device usually asks a recursive resolver, which can answer from cache or query other DNS servers. The record’s time to live (TTL) limits how long that cached answer should be reused. A DNS answer helps select a destination; it does not prove the server is reachable or healthy.</p></div><p>A missing or stale MX record can delay or misroute mail. If a domain has no MX record, SMTP has a defined fallback to its address records, but real mail systems are normally configured with explicit MX records.</p>","<div class=\"section-kicker\">DESIGN AND OPERATIONS · A SOFTWARE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">The password-reset email that arrives late</h2><p class=\"reader-intro\">Your app reports “email sent,” but a user’s password-reset link arrives 12 minutes later. That message crosses several boundaries, so start by finding the last confirmed milestone.</p><ol><li><strong>Application handoff:</strong> did the app successfully submit the message to its email provider? Record the provider’s message ID rather than treating a queued API call as delivery.</li><li><strong>DNS routing:</strong> which MX host did the sending provider find for the recipient domain? Did the host resolve to addresses?</li><li><strong>SMTP relay:</strong> what reply did the receiving mail server return? A <code>250</code> response means that server accepted responsibility for the message; it does not prove inbox placement.</li><li><strong>Queue and retry:</strong> a temporary <code>4xx</code> response usually leads to a later retry. The message may wait in a queue while the sender backs off and tries again.</li><li><strong>Mailbox handling:</strong> after acceptance, filtering or recipient-side processing may put the message in spam, quarantine, or another folder.</li></ol><div class=\"reader-callout\"><strong>Engineering lesson</strong><p>Email is store-and-forward. A mail server can accept and persist a message even when the next server is unavailable. That resilience makes email asynchronous, but it also means “sent” must be defined precisely in product logs and support screens.</p></div><div class='dns-mail-lab' data-dns-mail-lab><div class='dns-mail-head'><span>CHAPTER 2 LAB · DELIVERY EVIDENCE</span><strong>Locate the last confirmed milestone</strong></div><div class='dns-mail-controls'><label>MX lookup<select data-mail-mx><option value='valid'>Valid MX host resolves</option><option value='missing'>No MX or address fallback</option><option value='stale'>MX points to an old host</option></select></label><label>SMTP response<select data-mail-smtp><option value='250'>250 · accepted by recipient server</option><option value='451'>451 · temporary failure</option><option value='550'>550 · permanent rejection</option></select></label><label>Mailbox signal<select data-mail-inbox><option value='unknown'>No mailbox evidence yet</option><option value='spam'>Message found in spam</option><option value='inbox'>Message found in inbox</option></select></label></div><div class='dns-mail-result' data-mail-result aria-live='polite'></div></div><p>SMTP is used to submit and relay mail. IMAP lets a mail client synchronize and manage messages in a mailbox; POP3 provides a simpler retrieval model. These protocols solve different legs of the journey.</p>","<div class=\"section-kicker\">APPLY IT · INSPECT DNS RECORDS</div><h2 id=\"reader-title\" tabindex=\"-1\">Trace a mail route from the terminal</h2><p class=\"reader-intro\">Use a public domain you choose, or replace <code>example.net</code> below. These commands inspect public DNS; they do not send an email.</p><pre><code>dig MX example.net&#10;dig A mailhost.example.net&#10;dig AAAA mailhost.example.net&#10;dig TXT example.net</code></pre><ol><li><strong>Start with MX:</strong> note each mail host and its preference value. If you use a real domain, output may change as its administrators update DNS.</li><li><strong>Resolve a returned host:</strong> substitute an MX hostname into the A and AAAA commands. Record whether it has IPv4, IPv6, or both.</li><li><strong>Read the TTL:</strong> DNS output includes how long a resolver may cache the answer. Think about how a recent record change could take time to appear everywhere.</li><li><strong>Explore mail policy records:</strong> a TXT lookup can expose SPF policy. You can also try <code>dig TXT _dmarc.example.net</code>; DKIM records use a selector-specific name supplied by the sender’s configuration.</li><li><strong>Connect evidence to the symptom:</strong> a correct DNS result only establishes the configured route; it does not show that SMTP connected, that the server accepted mail, or that the message reached the inbox.</li></ol><label for=\"practice-notes\"><strong>Your trace notes</strong></label><textarea id=\"practice-notes\" placeholder=\"Recipient domain → MX host and preference → host IP → TTL → what this proves, and what it does not prove\"></textarea><details><summary>Compare with one possible analysis</summary><p>MX records identify the domain’s configured receiving mail hosts and preference order. A or AAAA records map a chosen host to network addresses. TTL affects cache freshness. SPF, DKIM, and DMARC publish or reference domain authentication policy, but a DNS lookup alone cannot confirm that a particular message passed authentication or landed in the inbox.</p></details>","<div class=\"section-kicker\">DEBUG · CONNECT · TRANSFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the first point where delivery stopped</h2><p class=\"reader-intro\">Treat email delivery like a chain of checkpoints. For a delayed message, ask which system last confirmed progress; then inspect the next boundary instead of restarting the investigation at the application.</p><div class=\"reader-callout\"><strong>A practical delivery checklist</strong><p>Find the application or provider message ID; check submission status; inspect recipient-domain MX and address records; read the SMTP response class; check sender queue age and retry count; then verify whether the receiving provider accepted the message and where its mailbox filters placed it.</p></div><p><strong>Self-check:</strong></p><ol><li>Why can a server return <code>250</code> while a message still does not appear in the inbox?</li><li>What does DNS MX tell a sending mail server?</li><li>What should a sender generally do after a temporary SMTP <code>4xx</code> reply?</li><li>Which protocol usually handles server-to-server mail transfer, and which one lets a user synchronize a mailbox?</li></ol><details><summary>Review the core ideas</summary><p>SMTP’s <code>250</code> confirms acceptance by the server that replied; later queueing, filtering, or mailbox processing may still affect delivery. MX records identify mail exchanger hosts, which must then resolve to addresses. A temporary <code>4xx</code> usually calls for queueing and retry with backoff; permanent <code>5xx</code> failures need a different response. SMTP transfers mail; IMAP or POP3 retrieves it for the user.</p></details><p><strong>Connect forward:</strong> next, explore how peer-to-peer systems and content delivery networks distribute application data closer to users.</p>"];
  if(id==="module-2-4") return [
   "<div class='section-kicker'>WHY IT EXISTS · THE WHOLE DELIVERY JOURNEY</div><h2 id='reader-title' tabindex='-1'>How content reaches a global audience</h2><p class='reader-intro'>Imagine thousands of people press Play at once. The product must find a nearby source, deliver video chunks fast enough to keep playback smooth, and avoid overwhelming one origin server. Content distribution is the system that moves bytes closer to demand.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>Placement affects startup time, buffering, cloud egress cost, origin capacity, and failure blast radius. The right choice depends on audience location, object size, freshness, privacy, and how much bandwidth users can contribute.</p></div><p><strong>One playback request:</strong> the app asks for a manifest; the player chooses a bitrate; DNS or routing directs it toward a service location; a CDN edge serves cached chunks or fetches a miss from origin; the player keeps adapting as network conditions change.</p><p><strong>By the end, you can:</strong></p><ol><li>Explain how CDNs reduce distance and origin load.</li><li>Compare direct origin delivery, CDN caching, and peer-assisted delivery.</li><li>Estimate how cache hits and peer contribution change bandwidth demand.</li></ol>",
   "<div class='section-kicker'>SYSTEM MODEL · THREE WAYS TO PLACE CONTENT</div><h2 id='reader-title' tabindex='-1'>Choose where the bytes come from</h2><p class='reader-intro'>The viewer asks for an object; the architecture decides which machines can serve it. Select each design to trace the path and its tradeoffs.</p><div class='delivery-architecture' data-delivery-architecture><div class='delivery-modes' role='group' aria-label='Choose a content delivery design'><button type='button' data-delivery-mode='origin' aria-pressed='true'>Direct from origin</button><button type='button' data-delivery-mode='cdn' aria-pressed='false'>CDN edge cache</button><button type='button' data-delivery-mode='p2p' aria-pressed='false'>Peer-assisted</button></div><div class='delivery-flow' data-delivery-flow aria-live='polite'><span class='delivery-node'>Viewer</span><span class='delivery-arrow' aria-hidden='true'>→</span><span class='delivery-node'>Origin server</span></div><p class='delivery-explainer' data-delivery-explainer>Every viewer pulls from the origin. It is simple, but long network paths and synchronized demand can overload the source.</p></div><div class='reader-callout'><strong>Key distinction</strong><p>A CDN is a set of distributed servers plus routing, caching, and invalidation logic. Adaptive bitrate streaming is a player strategy that chooses among encoded chunk qualities; they often work together, but solve different problems.</p></div><p>CDN routing may use DNS answers, anycast, or provider measurements. “Nearest” is an optimization based on network conditions and policy, not always the smallest geographic distance.</p>",
   "<div class='section-kicker'>ENGINEERING CASE · LATENCY, COST, AND FRESHNESS</div><h2 id='reader-title' tabindex='-1'>A launch overwhelms the origin</h2><p class='reader-intro'>A software team releases a popular training video. Viewers in several regions report slow startup, and the origin’s outbound bandwidth approaches its limit. The video is identical for everyone, but account pages and personalized metadata are not.</p><div class='reader-callout'><strong>Start with the system boundary</strong><p>Static video chunks are cacheable; personalized API responses may not be. Cache misses still reach origin, so a high hit rate matters only when cache keys, TTLs, and invalidation rules match the product’s freshness requirements.</p></div><p><strong>Reason through the response:</strong></p><ol><li>Measure startup time, rebuffer ratio, edge hit rate, origin egress, and regional error rate.</li><li>Check whether the same chunk URL and cache key produce hits across viewers.</li><li>Replicate popular chunks to edge locations; use adaptive bitrate so clients can request a lower-rate representation on constrained links.</li><li>Protect origin with request coalescing, rate limits, and capacity alerts; define what happens when the CDN or origin is unavailable.</li></ol><p>Peer-assisted delivery can offload bandwidth for popular large objects, but needs enough participating peers and introduces privacy, abuse, NAT traversal, and availability questions. Treat peer traffic as an explicit design with user and security controls.</p>",
   "<div class='section-kicker'>HANDS-ON · ESTIMATE THE BANDWIDTH</div><h2 id='reader-title' tabindex='-1'>See how caching changes the load</h2><p class='reader-intro'>Adjust the audience, average stream bitrate, cache hit rate, and peer contribution. The model estimates aggregate egress; it ignores protocol overhead, representation changes, and time variation.</p><div data-delivery-lab><div class='delivery-inputs'><label>Concurrent viewers <output data-delivery-value='viewers'>30,000</output><input data-delivery-input='viewers' type='range' min='1000' max='100000' step='1000' value='30000' aria-label='Concurrent viewers'></label><label>Average bitrate (Mbps) <output data-delivery-value='bitrate'>4</output><input data-delivery-input='bitrate' type='range' min='1' max='12' step='0.5' value='4' aria-label='Average bitrate in megabits per second'></label><label>CDN cache hit rate <output data-delivery-value='cache'>92%</output><input data-delivery-input='cache' type='range' min='0' max='100' step='1' value='92' aria-label='CDN cache hit rate percent'></label><label>Traffic supplied by peers <output data-delivery-value='peers'>10%</output><input data-delivery-input='peers' type='range' min='0' max='50' step='1' value='10' aria-label='Traffic supplied by peers percent'></label></div><div class='delivery-result-grid' aria-live='polite'><div class='delivery-metric'><span>Total viewer demand</span><strong data-delivery-result='demand'>120 Gbps</strong></div><div class='delivery-metric'><span>CDN edge egress</span><strong data-delivery-result='edge'>108 Gbps</strong></div><div class='delivery-metric'><span>Origin egress</span><strong data-delivery-result='origin'>8.6 Gbps</strong></div></div><p class='delivery-explainer' data-delivery-status></p></div><label for='practice-notes'><strong>Working notes:</strong> Which change would you try first, and what metric would prove it helped?</label><textarea id='practice-notes' placeholder='Compare cache warming, bitrate choices, and peer offload…'></textarea>",
   "<div class='section-kicker'>TRANSFER CHECKPOINT · DESIGN THE DELIVERY PATH</div><h2 id='reader-title' tabindex='-1'>Choose the right source for the bytes</h2><p class='reader-intro'>You are reviewing a product that serves public software downloads and private user documents from the same origin. Traffic spikes during releases, and some content changes several times per hour.</p><div class='reader-callout'><strong>Make the engineering argument</strong><p>Separate cacheable public artifacts from private or frequently changing responses; choose TTLs and invalidation behavior deliberately; compare origin egress with edge egress; define fallback behavior for cache misses and regional outages.</p></div><p><strong>Can you explain:</strong></p><ol><li>Why a CDN can lower latency and origin load, and why it cannot eliminate origin traffic?</li><li>How a cache key or stale TTL can expose the wrong version or user’s data?</li><li>When adaptive bitrate improves playback, and what signal the player uses?</li><li>What extra privacy and availability tradeoffs peer-assisted delivery introduces?</li></ol><details><summary>Review the core model</summary><p>Origin stores the authoritative object; edge caches replicate popular content near viewers; players adapt chunk quality to available bandwidth; peers can contribute chunks when the architecture explicitly supports it.</p></details><p><strong>Connect forward:</strong> next, transport services determine how these application messages and chunks move between processes, and what reliability or congestion behavior they receive.</p>"
  ];
  if(id==="module-3-1") return [
   "<div class='section-kicker'>WHY IT EXISTS · FROM APP TO PROCESS</div><h2 id='reader-title' tabindex='-1'>How the right app receives the right bytes</h2><p class='reader-intro'>A laptop can have a browser, chat app, game, and database client using the network at the same time. The operating system and transport layer must keep their conversations separate and deliver arriving data to the correct socket.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>Ports and sockets explain why a server can host many clients on one address, why a process can bind to a port, and why a firewall or load balancer can allow one service while blocking another.</p></div><p><strong>Whole path:</strong> an application writes to a socket; the transport layer adds endpoint information; IP carries the segment to a host; the receiving host uses the protocol and port information to find the listening or connected socket.</p><p><strong>By the end, you can:</strong></p><ol><li>Distinguish a process, socket, port, and host address.</li><li>Explain transport multiplexing and demultiplexing.</li><li>Read a connection tuple when debugging a service.</li></ol>",
   "<div class='section-kicker'>SYSTEM MODEL · MULTIPLEX AND DEMULTIPLEX</div><h2 id='reader-title' tabindex='-1'>A port is a doorway into a host</h2><p class='reader-intro'>On the sender, transport gathers data from multiple sockets and labels each segment with source and destination information. At the receiver, the operating system examines the protocol and port fields to select a socket.</p><div class='reader-callout'><strong>TCP connection identity</strong><p>A TCP connection is identified by its protocol and the pair of endpoint addresses and ports. Multiple clients can connect to the same server port because each client has a different local endpoint. UDP delivery is also demultiplexed using its protocol and destination information.</p></div><ol><li>The client asks the OS for a socket and an ephemeral source port.</li><li>The server listens on a service port such as 443.</li><li>IP gets the segment to the server host; transport maps it to the correct socket.</li></ol><p>A port is not a process by itself; the OS maintains socket state and may apply reuse rules, namespaces, and firewall policy.</p>",
   "<div class='section-kicker'>ENGINEERING CASE · CONNECTIONS AT SCALE</div><h2 id='reader-title' tabindex='-1'>The API is reachable, but the app cannot connect</h2><p class='reader-intro'>A deployment responds to health checks, but users receive connection-refused errors. A teammate sees the process running and assumes the network is fine.</p><div class='reader-callout'><strong>Follow ownership in order</strong><p>Is the process listening on the expected address and port? Does the container publish that port? Does the load balancer target the same port? Do firewall rules and network policies allow this protocol? A running process does not guarantee that a reachable socket exists.</p></div><p>For an established TCP flow, inspect the local and remote address-port pair, connection state, listener backlog, and reset or timeout evidence. For UDP, a sender may receive no error even when no application is listening, so add application-level health evidence.</p><p>When a single server handles thousands of clients, clients reuse the server’s destination port; distinct client endpoints allow the OS to keep concurrent connections separate.</p>",
   "<div class='section-kicker'>HANDS-ON · BUILD A SOCKET TUPLE</div><h2 id='reader-title' tabindex='-1'>Change the endpoint; see what changes</h2><p class='reader-intro'>Select a client port and transport protocol. The service keeps listening on one port, while the full connection identity changes with each client endpoint.</p><div class='socket-lab' data-socket-lab><div class='socket-inputs'><label>Client ephemeral port <input data-socket-client type='number' min='49152' max='65535' value='53124'></label><label>Service port <select data-socket-server><option value='443'>443 · HTTPS</option><option value='53'>53 · DNS</option><option value='22'>22 · SSH</option></select></label><label>Transport <select data-socket-protocol><option>TCP</option><option>UDP</option></select></label></div><div class='socket-path' aria-live='polite'><span>CLIENT PROCESS</span><b data-socket-tuple>192.0.2.10:53124 → 203.0.113.20:443 / TCP</b><span data-socket-destination>SERVER SOCKET · port 443</span></div><p data-socket-note></p></div><p><strong>Try it:</strong> keep the server port fixed, change the client port, and explain why the server can distinguish the two flows.</p>",
   "<div class='section-kicker'>TRANSFER CHECKPOINT · TRACE OWNERSHIP</div><h2 id='reader-title' tabindex='-1'>Debug the path to a socket</h2><p class='reader-intro'>A service is running, but one client cannot connect. State which evidence would distinguish an app-binding problem, a transport problem, and a network-policy problem.</p><div class='reader-callout'><strong>Review the model</strong><p>Applications exchange data through sockets. Transport multiplexes outgoing data and demultiplexes incoming data; ports identify transport endpoints on a host, while IP addresses identify hosts across networks.</p></div><p><strong>Can you answer:</strong></p><ol><li>Why can many TCP clients use the same server port at once?</li><li>What does a listening socket tell you, and what does it not prove?</li><li>Which tuple and connection-state fields would you capture in an incident?</li></ol><p><strong>Connect forward:</strong> UDP uses the same host-to-process delivery idea with a lighter service; next, examine which guarantees an application must provide itself.</p>"
  ];
  if(id==="module-3-2") return [
   "<div class='section-kicker'>WHY IT EXISTS · CHOOSE THE SERVICE</div><h2 id='reader-title' tabindex='-1'>Why send datagrams without a conversation?</h2><p class='reader-intro'>A live voice call, game update, or DNS query may care more about a timely next message than recovering every old one. UDP sends independent datagrams without first establishing a connection or retransmitting lost data on its own.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>Choosing UDP shifts responsibility upward. Your application decides whether to retry, reorder, authenticate, rate-limit, or discard late data; that flexibility can improve latency but creates real implementation work.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Explain UDP’s minimal service and its limits.</li><li>Compare reliability, ordering, and timing needs.</li><li>Decide whether an application should retry a missing message.</li></ol><p>UDP is not automatically faster; the complete application protocol and network conditions determine latency.</p>",
   "<div class='section-kicker'>SYSTEM MODEL · ONE DATAGRAM AT A TIME</div><h2 id='reader-title' tabindex='-1'>UDP leaves policy to the application</h2><p class='reader-intro'>An application writes a message; UDP adds source and destination ports, length, and a checksum; IP routes the datagram to the destination host; the receiver delivers it to a matching socket.</p><div class='reader-callout'><strong>What UDP does not promise</strong><p>No built-in handshake, delivery guarantee, ordering, duplicate suppression, or congestion-control algorithm. A checksum can detect some corruption; it does not repair it. IPv4 and IPv6 checksum rules differ.</p></div><ol><li>Use datagrams when message boundaries matter and waiting for old data may be harmful.</li><li>Add sequence numbers, acknowledgments, deadlines, or retries only if the product needs them.</li><li>Respect congestion and security requirements; a simple transport header does not make a safe protocol.</li></ol><p>QUIC uses UDP as a substrate but implements connection security, streams, and congestion control above it. The application’s actual protocol determines the guarantees.</p>",
   "<div class='section-kicker'>ENGINEERING CASE · REAL-TIME UPDATES</div><h2 id='reader-title' tabindex='-1'>A game update arrives after it is useful</h2><p class='reader-intro'>A multiplayer game sends a player position every 30 ms. A lost update is replaced almost immediately by a newer one, so retransmitting the old position can add delay without improving the player’s view.</p><div class='reader-callout'><strong>Design for the meaning of the message</strong><p>Attach sequence numbers and timestamps; discard stale updates; interpolate briefly between recent positions; bound packet size and send rate; authenticate the protocol and validate coordinates.</p></div><p>Compare that with a purchase request: silently losing it can leave the user uncertain whether money was charged. That operation needs an explicit application protocol with request IDs, acknowledgments, retries with deadlines, and idempotent handling.</p><p>Pick transport from the failure cost and timing needs of the operation, not from a slogan like “UDP is faster.”</p>",
   "<div class='section-kicker'>HANDS-ON · MODEL LOSS AND RETRIES</div><h2 id='reader-title' tabindex='-1'>When does retrying help?</h2><p class='reader-intro'>Adjust message count, datagram loss, and application retries. The model assumes independent equal loss on each attempt; it estimates success probability and traffic, not real network performance.</p><div class='udp-lab' data-udp-lab><div class='udp-inputs'><label>Messages <output data-udp-value='messages'>100</output><input type='range' min='10' max='1000' step='10' value='100' data-udp-input='messages'></label><label>Loss per attempt <output data-udp-value='loss'>10%</output><input type='range' min='0' max='50' step='1' value='10' data-udp-input='loss'></label><label>Application retries <output data-udp-value='retries'>1</output><input type='range' min='0' max='5' step='1' value='1' data-udp-input='retries'></label></div><div class='delivery-result-grid'><div class='delivery-metric'><span>Chance one message arrives</span><strong data-udp-result='success'>99%</strong></div><div class='delivery-metric'><span>Expected datagrams sent</span><strong data-udp-result='traffic'>110</strong></div></div><p data-udp-status aria-live='polite'></p></div><p><strong>Engineering caution:</strong> retries need deadlines and duplicate-safe request handling. A retry may arrive after the original, so use an idempotency key for operations with side effects.</p>",
   "<div class='section-kicker'>TRANSFER CHECKPOINT · STATE YOUR GUARANTEES</div><h2 id='reader-title' tabindex='-1'>What must the application own?</h2><p class='reader-intro'>You are designing a sensor update, a voice packet, and a payment request. They should not all use the same retry policy.</p><div class='reader-callout'><strong>Review the model</strong><p>UDP transports independent datagrams between sockets. It offers lightweight endpoint delivery, while reliability, ordering, freshness, duplicate handling, authentication, and congestion response depend on the application protocol and surrounding stack.</p></div><p><strong>Can you explain:</strong></p><ol><li>Why may a newer game position make an older lost update worthless?</li><li>Why should a payment retry carry an idempotency key and deadline?</li><li>Which guarantee comes from UDP, and which comes from QUIC or the application?</li></ol><p><strong>Connect forward:</strong> TCP builds reliable ordered byte-stream behavior from sequence numbers, acknowledgments, and retransmissions.</p>"
  ];
  if(id==="module-3-3") return [
   "<div class='section-kicker'>WHY IT EXISTS · REPAIR AN UNRELIABLE PATH</div><h2 id='reader-title' tabindex='-1'>How can software trust a byte stream?</h2><p class='reader-intro'>IP can lose, reorder, or duplicate packets. Applications such as web services often need a reliable, ordered stream of bytes; TCP uses acknowledgments, sequence numbers, timers, and retransmissions to build that service.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>TCP reliability affects request latency, head-of-line blocking, connection state, and what packet captures show. It does not guarantee that the server processed an operation exactly once or that the application understands message boundaries.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Trace sequence numbers and cumulative acknowledgments.</li><li>Explain how loss triggers retransmission.</li><li>Distinguish reliable byte delivery from application-level success.</li></ol>",
   "<div class='section-kicker'>SYSTEM MODEL · SEQUENCE, ACKNOWLEDGE, RETRANSMIT</div><h2 id='reader-title' tabindex='-1'>TCP repairs missing bytes</h2><p class='reader-intro'>TCP numbers bytes in the stream. An acknowledgment usually names the next byte the receiver expects; a cumulative ACK therefore confirms a continuous prefix of the stream.</p><ol><li>Sender transmits bytes with a sequence range.</li><li>Receiver checks data and acknowledges the next expected byte.</li><li>If a segment is lost, repeated ACK evidence or a timeout can prompt retransmission.</li><li>Receiver reassembles the byte stream and releases it in order to the application.</li></ol><div class='reader-callout'><strong>Important boundary</strong><p>TCP exposes a stream, not messages. If an app sends two writes, the receiver may read them in one chunk or several; the app needs framing such as a length prefix or delimiter.</p></div><p>Modern TCP uses adaptive retransmission timers and congestion control. Duplicate ACKs and timeouts indicate different evidence and have different latency costs.</p>",
   "<div class='section-kicker'>ENGINEERING CASE · A SLOW REQUEST</div><h2 id='reader-title' tabindex='-1'>One lost segment delays later data</h2><p class='reader-intro'>An API response spans several TCP segments. The second segment is lost, while later segments arrive. The receiver can buffer later bytes but cannot deliver a gap-free stream past the missing range.</p><div class='reader-callout'><strong>Reason from observations</strong><p>Look for retransmitted sequence ranges, duplicate ACKs, retransmission timeouts, round-trip time, and bytes in flight. App-level request logs alone may show delay but not identify the transport event causing it.</p></div><p>With classic TCP, missing earlier bytes can hold up later bytes on that connection. Separate connections or independent streams change the scope of this blocking; QUIC streams can avoid cross-stream ordering stalls while still sharing a congestion-controlled connection.</p><p>Retries at the HTTP layer are a separate mechanism. A timeout does not prove the server failed to perform the operation; design mutation requests to be safe against duplicate attempts.</p>",
   "<div class='section-kicker'>HANDS-ON · STEP THROUGH LOSS RECOVERY</div><h2 id='reader-title' tabindex='-1'>Watch a cumulative ACK move</h2><p class='reader-intro'>The sender transmits byte ranges 1–100, 101–200, and 201–300; the middle segment is lost. Step through the receiver’s evidence and the sender’s repair.</p><div class='tcp-lab' data-tcp-lab><div class='tcp-lane'><span>SENDER</span><strong data-tcp-sender>Ready · send bytes 1–100</strong></div><div class='tcp-lane'><span>NETWORK</span><strong data-tcp-network>Segment 2 will be lost</strong></div><div class='tcp-lane'><span>RECEIVER</span><strong data-tcp-receiver>Next expected byte: 1</strong></div><p data-tcp-status aria-live='polite'>Step to send the first range.</p><div class='tcp-actions'><button type='button' data-tcp-step>Next event</button><button type='button' data-tcp-reset>Reset</button></div></div><div class='tcp-prediction' data-tcp-prediction><span>DECISION POINT</span><p>Bytes 201–300 arrived, but 101–200 are missing. What cumulative ACK does the receiver send?</p><div role='group' aria-label='Choose the next cumulative acknowledgement'><button type='button' data-tcp-prediction-choice='101'>ACK 101</button><button type='button' data-tcp-prediction-choice='201'>ACK 201</button><button type='button' data-tcp-prediction-choice='301'>ACK 301</button></div><p data-tcp-prediction-feedback aria-live='polite'></p></div><p><strong>Try to predict:</strong> Will bytes 201–300 be delivered to the app before the gap is repaired?</p>",
   "<div class='section-kicker'>TRANSFER CHECKPOINT · KNOW WHAT TCP GUARANTEES</div><h2 id='reader-title' tabindex='-1'>Reliable delivery is not exactly-once execution</h2><p class='reader-intro'>A client sends a request, receives no response, and retries after a timeout. The original may have reached the server even if the reply was lost.</p><div class='reader-callout'><strong>Review the model</strong><p>TCP provides an ordered byte stream while the connection is operating; acknowledgments and retransmissions handle network loss. The application still defines message boundaries, operation semantics, retries, and duplicate protection.</p></div><p><strong>Can you explain:</strong></p><ol><li>What does a cumulative ACK confirm?</li><li>Why can a later byte range wait behind an earlier missing range?</li><li>Why does TCP alone not make a payment or database update exactly once?</li></ol><p><strong>Connect forward:</strong> TCP also limits how much data can be in flight; the receiver and the network impose different limits.</p>"
  ];
  if(id==="module-3-4") return [
   "<div class='section-kicker'>WHY IT EXISTS · TWO DIFFERENT BOTTLENECKS</div><h2 id='reader-title' tabindex='-1'>Why does the sender need two windows?</h2><p class='reader-intro'>A sender may be willing to transmit faster than the receiver can buffer; the network may also be congested. TCP limits outstanding data using the receiver’s advertised window and the sender’s congestion window.</p><div class='reader-callout'><strong>Why software engineers learn this</strong><p>These controls explain why a high-capacity server can send slowly, why increasing socket buffers may not improve throughput, and how network load can change latency even when the receiver is healthy.</p></div><p><strong>By the end, you can:</strong></p><ol><li>Distinguish receiver flow control from network congestion control.</li><li>Use the minimum of the two windows to reason about in-flight data.</li><li>Estimate whether the path can be filled at a given RTT.</li></ol>",
   "<div class='section-kicker'>SYSTEM MODEL · MINIMUM WINDOW, THEN THE PATH</div><h2 id='reader-title' tabindex='-1'>The receiver and network set separate caps</h2><p class='reader-intro'>The advertised receive window (rwnd) reports available receiver buffer; congestion window (cwnd) is sender-side control informed by network conditions. Outstanding data is constrained by the smaller window, subject to implementation details and other limits.</p><div class='reader-callout'><strong>Connect the window to the path</strong><p>The bandwidth-delay product is the data needed in flight to keep a path busy: capacity × round-trip time. If the permitted flight is much smaller, throughput can remain below link capacity.</p></div><ol><li>rwnd shrinks when the receiving application is slow to read.</li><li>cwnd changes as the sender responds to network congestion signals.</li><li>Throughput is bounded by path capacity and by permitted bytes in flight divided by RTT.</li></ol><p>Flow control protects the receiver; congestion control protects the shared network. They can both limit the same connection at once.</p>",
   "<div class='section-kicker'>ENGINEERING CASE · FIND THE REAL LIMIT</div><h2 id='reader-title' tabindex='-1'>A fast link, a slow transfer</h2><p class='reader-intro'>A service has a 100-Mbps path and 80-ms RTT, but one TCP transfer averages only 12 Mbps. The client sometimes pauses while parsing a large response.</p><div class='reader-callout'><strong>Separate the hypotheses</strong><p>Inspect cwnd, rwnd, bytes in flight, RTT, retransmissions, receiver read rate, and socket metrics. If rwnd is small, the receiver may be backpressured; if cwnd is small with loss or ECN signals, congestion may be limiting the sender.</p></div><p>Increasing a buffer can absorb bursts but does not add path capacity; oversized queues may increase latency. Check the bandwidth-delay product and measure queueing before tuning buffers.</p><p>At the application layer, stream large responses and consume them incrementally when possible instead of holding data until the entire response is parsed.</p>",
   "<div class='section-kicker'>HANDS-ON · COMPARE WINDOWS WITH PATH CAPACITY</div><h2 id='reader-title' tabindex='-1'>Which limit is binding?</h2><p class='reader-intro'>Adjust the receiver window, congestion window, round-trip time, and path capacity. The simple estimate is min(path capacity, min(rwnd,cwnd) × 8 / RTT), with windows in decimal KB and RTT in milliseconds.</p><div class='window-lab' data-window-lab><div class='window-inputs'><label>Receiver window (KB) <output data-window-value='rwnd'>256</output><input type='range' min='16' max='1024' step='16' value='256' data-window-input='rwnd'></label><label>Congestion window (KB) <output data-window-value='cwnd'>128</output><input type='range' min='16' max='1024' step='16' value='128' data-window-input='cwnd'></label><label>Round-trip time (ms) <output data-window-value='rtt'>80</output><input type='range' min='10' max='300' step='5' value='80' data-window-input='rtt'></label><label>Path capacity (Mbps) <output data-window-value='capacity'>50</output><input type='range' min='5' max='1000' step='5' value='50' data-window-input='capacity'></label></div><div class='delivery-result-grid'><div class='delivery-metric'><span>Permitted flight</span><strong data-window-result='flight'>128 KB</strong></div><div class='delivery-metric'><span>Window-limited rate</span><strong data-window-result='window-rate'>12.8 Mbps</strong></div><div class='delivery-metric'><span>Estimated max rate</span><strong data-window-result='rate'>12.8 Mbps</strong></div></div><p data-window-status aria-live='polite'></p></div>",
   "<div class='section-kicker'>TRANSFER CHECKPOINT · NAME THE LIMIT</div><h2 id='reader-title' tabindex='-1'>Receiver pressure or network congestion?</h2><p class='reader-intro'>A transfer is slow. Explain what measurements would tell you whether the receiver window, congestion window, RTT, or physical path capacity is setting the limit.</p><div class='reader-callout'><strong>Review the model</strong><p>Flow control advertises receiver buffer capacity; congestion control limits sending according to network conditions. The effective flight is bounded by both. A high RTT requires more in-flight data to fill a fast path.</p></div><p><strong>Can you answer:</strong></p><ol><li>What does a small rwnd suggest about the receiver?</li><li>What observations can suggest congestion is constraining cwnd?</li><li>Why can a larger buffer add queueing delay without increasing capacity?</li></ol><p><strong>Connect forward:</strong> next, routers forward packets using network-layer addresses and local tables.</p>"
  ];
  const chapterFour={"module-4-1":["<div class=\"section-kicker\">WHY IT EXISTS · A PACKET NEEDS A NEXT HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">How does a router know where to send a packet?</h2><p class=\"reader-intro\">The Internet has no single device planning every packet’s trip. Routing logic establishes paths across networks; each router stores local forwarding state and uses it to choose a next hop.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Routing explains regional outages, path changes without application deploys, and why a healthy service may be unreachable from one network. It separates network-wide path planning from fast per-packet forwarding.</p></div><p><strong>By the end:</strong> distinguish routing from forwarding, trace a packet through a table, and explain how route changes affect traffic.</p>","<div class=\"section-kicker\">SYSTEM MODEL · CONTROL PLANE TO DATA PLANE</div><h2 id=\"reader-title\" tabindex=\"-1\">Plan globally, forward locally</h2><p class=\"reader-intro\">The control plane learns topology and policy, computes paths, and installs forwarding entries. The data plane applies those entries to packets. A router performs a local lookup for each packet instead of recomputing the entire journey.</p><ol><li>Learn reachable networks from peers or configuration.</li><li>Select paths according to metrics and policy.</li><li>Install a next hop and output interface.</li><li>Look up each arriving packet and forward it.</li></ol><p>A bad route can create a bad table; a correct table can still encounter failed links, full queues, or downstream policy drops.</p>","<div class=\"section-kicker\">ENGINEERING CASE · REGIONAL REACHABILITY</div><h2 id=\"reader-title\" tabindex=\"-1\">One API, two network paths</h2><p class=\"reader-intro\">A service is healthy from the office but times out from a cloud region. DNS returns the same address, yet the locations traverse different providers and routers.</p><ol><li>Compare resolved addresses from both locations.</li><li>Use traceroute or route telemetry to find where paths diverge.</li><li>Check advertisements, policy, and link state near the first unreachable hop.</li><li>Separate forwarding failure from a server that accepts connections but responds slowly.</li></ol><p><strong>Engineering lesson:</strong> “The server is up” does not prove end-to-end reachability. Regional probes localize the boundary.</p>","<div class=\"section-kicker\">HANDS-ON · SELECT A PRECOMPUTED PATH</div><h2 id=\"reader-title\" tabindex=\"-1\">Separate route choice from packet movement</h2><p class=\"reader-intro\">Choose one of two paths installed by the control plane. The router forwards using its local next-hop entry.</p><div class=\"network-lab\" data-route-lab><h3>Packet path explorer</h3><div class=\"network-lab-controls\"><button type=\"button\" data-route-choice=\"primary\" aria-pressed=\"true\">Primary route</button><button type=\"button\" data-route-choice=\"backup\" aria-pressed=\"false\">Backup route</button></div><div class=\"route-map\"><div class=\"route-option is-selected\" data-route-view=\"primary\"><strong>Primary · lower latency</strong><span>Client → Edge R1 → Core R3 → API</span></div><div class=\"route-option\" data-route-view=\"backup\"><strong>Backup · alternate provider</strong><span>Client → Edge R1 → Core R4 → API</span></div></div><p class=\"network-status\" data-route-status aria-live=\"polite\">Forwarding table: API prefix → Core R3, interface 2.</p></div><p>Compare route tables and packet paths from a working and failing region. Which evidence confirms a control-plane change?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · EXPLAIN THE NEXT HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">From route selection to packet movement</h2><p class=\"reader-intro\">When someone says “routing is broken,” ask whether the issue is computation, distribution, table installation, or forwarding. Each stage has different evidence.</p><ol><li>What does routing do that forwarding does not?</li><li>Why use a local lookup per packet?</li><li>Can a correct route still fail to deliver data?</li><li>How would you compare regional reachability?</li></ol><details><summary>Review the core ideas</summary><p>Routing selects paths and populates state. Forwarding applies the local table. Correct state cannot prevent failed links, queue overflow, downstream drops, or application failures.</p></details><p><strong>Connect forward:</strong> follow a packet inside a router, from input port to output queue.</p>"],"module-4-2":["<div class=\"section-kicker\">WHY IT EXISTS · PACKET PROCESSING AT LINE RATE</div><h2 id=\"reader-title\" tabindex=\"-1\">What happens inside a router?</h2><p class=\"reader-intro\">A router receives frames and moves packets to the right output. Its architecture divides the work into input processing, lookup, a switching fabric, and output processing.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>This model explains bottlenecks in routers, load balancers, NIC queues, and packet pipelines. Packets can wait because an input, fabric, or output cannot keep up.</p></div><p><strong>By the end:</strong> identify router components, trace a packet, and explain output queueing and head-of-line blocking.</p>","<div class=\"section-kicker\">SYSTEM MODEL · INGRESS TO EGRESS</div><h2 id=\"reader-title\" tabindex=\"-1\">A router is a packet pipeline</h2><p class=\"reader-intro\">The input receives and validates a frame, extracts the destination, and performs a forwarding lookup. The fabric transfers the packet. The output queues, schedules, and transmits it.</p><ol><li><strong>Input:</strong> receive bits, validate framing, inspect headers.</li><li><strong>Lookup:</strong> map a destination prefix to an output.</li><li><strong>Fabric:</strong> move data across the device.</li><li><strong>Output:</strong> buffer, schedule, and send on the link.</li></ol><p>Input queues form when the fabric is busy; output queues form when arrivals exceed link capacity.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE RIGHT ROUTE, THE WRONG DELAY</div><h2 id=\"reader-title\" tabindex=\"-1\">A video call stutters during a backup</h2><p class=\"reader-intro\">Both applications share an egress link. Routing is correct, but a backup burst fills the output queue. Interactive packets wait behind bulk data, creating jitter.</p><ol><li>Measure utilization and queue depth during the event.</li><li>Find whether delay begins before or after the output queue.</li><li>Consider shaping or scheduling latency-sensitive traffic.</li><li>Bound priorities so bulk transfers still progress.</li></ol><p><strong>Engineering lesson:</strong> routing answers “where next?” Queueing answers “when?”</p>","<div class=\"section-kicker\">HANDS-ON · STEP THROUGH A ROUTER</div><h2 id=\"reader-title\" tabindex=\"-1\">Advance a packet through the pipeline</h2><p class=\"reader-intro\">Step through each router component. Toggle output contention to see why a correctly routed packet may wait before transmission.</p><div class=\"network-lab\" data-router-lab><h3>Router pipeline</h3><ol class=\"router-pipeline\"><li data-router-step=\"0\" class=\"is-active\"><b>1 · Input</b>Frame received</li><li data-router-step=\"1\"><b>2 · Lookup</b>Output selected</li><li data-router-step=\"2\"><b>3 · Fabric</b>Packet switched</li><li data-router-step=\"3\"><b>4 · Output</b>Queued and sent</li></ol><div class=\"network-lab-controls\"><button type=\"button\" data-router-next>Advance packet →</button><button type=\"button\" data-router-reset>Reset</button><label><input type=\"checkbox\" data-router-contention> Busy output queue</label></div><p class=\"network-status\" data-router-status aria-live=\"polite\"></p></div><p>Contention changes when the packet leaves, not which output the lookup selected.</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · LOCATE THE QUEUE</div><h2 id=\"reader-title\" tabindex=\"-1\">Explain delay inside the router</h2><p>A trace can show the correct next hop while latency rises. Identify the interface and queue before changing routing policy.</p><ol><li>What does the input do before the fabric?</li><li>How is queueing different from a wrong route?</li><li>What is head-of-line blocking?</li><li>Why protect low-priority traffic from starvation?</li></ol><details><summary>Review the core ideas</summary><p>Inputs receive and inspect frames; lookup selects output; fabric moves packets; outputs queue and schedule transmission. Head-of-line blocking happens when a packet waiting for one output blocks packets behind it.</p></details><p><strong>Connect forward:</strong> inspect the prefixes that select forwarding entries.</p>"],"module-4-3":["<div class=\"section-kicker\">WHY IT EXISTS · ADDRESS THE DESTINATION</div><h2 id=\"reader-title\" tabindex=\"-1\">How does an IP address guide a packet?</h2><p class=\"reader-intro\">IP datagrams carry source and destination addresses. Prefixes group addresses with shared leading bits; the most specific matching prefix selects a next hop.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Addressing appears in cloud VPCs, Kubernetes, firewalls, VPNs, NAT gateways, and IPv6 migrations. Prefixes explain overlapping routes and why traffic can follow an unexpected path.</p></div><p><strong>By the end:</strong> read CIDR notation, apply longest-prefix matching, and describe NAT and IPv6 trade-offs.</p>","<div class=\"section-kicker\">SYSTEM MODEL · PREFIXES AND ROUTE SELECTION</div><h2 id=\"reader-title\" tabindex=\"-1\">The most specific matching route wins</h2><p class=\"reader-intro\">A /24 fixes 24 leading bits and covers fewer addresses than a /16. A destination may match multiple entries; longest-prefix matching selects the greatest prefix length. A default route /0 catches otherwise unmatched traffic.</p><ol><li>Represent the destination as 32 IPv4 bits.</li><li>Compare its leading bits with every prefix.</li><li>Keep the match with the greatest prefix length.</li><li>Forward to its next hop and interface.</li></ol><p>NAT translates addresses between network realms, often conserving IPv4 space. IPv6 uses 128-bit addresses; NAT itself is not a firewall.</p>","<div class=\"section-kicker\">ENGINEERING CASE · OVERLAPPING NETWORKS</div><h2 id=\"reader-title\" tabindex=\"-1\">A VPN route captures cloud traffic</h2><p class=\"reader-intro\">A developer connects to a VPN and loses access to a cloud service. The VPN advertises a broad private prefix overlapping the cloud network, so the route sends traffic down the tunnel.</p><ol><li>Inspect the destination address returned by DNS.</li><li>Review client routes and compare prefix lengths.</li><li>Find an overlapping or overly broad VPN route.</li><li>Use non-overlapping address plans across environments.</li></ol><p><strong>Engineering lesson:</strong> routes follow prefixes, not service names or developer intent.</p>","<div class=\"section-kicker\">HANDS-ON · LONGEST-PREFIX MATCH</div><h2 id=\"reader-title\" tabindex=\"-1\">Change the destination; inspect the winner</h2><p>Try <code>10.4.8.20</code>, <code>10.4.9.20</code>, and <code>8.8.8.8</code>. The table highlights the most specific matching entry.</p><div class=\"network-lab\" data-ip-lab><h3>Forwarding table lookup</h3><label for=\"ip-destination\">Destination IPv4 address</label><div class=\"network-lab-controls\"><input id=\"ip-destination\" data-ip-destination value=\"10.4.8.20\" inputmode=\"decimal\"></div><table class=\"network-table\"><thead><tr><th>Prefix</th><th>Next hop</th><th>Interface</th></tr></thead><tbody><tr data-prefix=\"10.4.8.0/24\"><td>10.4.8.0/24</td><td>R7</td><td>eth2</td></tr><tr data-prefix=\"10.4.0.0/16\"><td>10.4.0.0/16</td><td>R3</td><td>eth1</td></tr><tr data-prefix=\"172.16.0.0/12\"><td>172.16.0.0/12</td><td>VPN gateway</td><td>tun0</td></tr><tr data-prefix=\"0.0.0.0/0\"><td>0.0.0.0/0</td><td>ISP</td><td>eth0</td></tr></tbody></table><p class=\"network-status\" data-ip-status aria-live=\"polite\"></p></div><p>Explain why /24 beats /16 when both match.</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · READ THE ROUTE TABLE</div><h2 id=\"reader-title\" tabindex=\"-1\">Address plans become production behavior</h2><p>Compare destinations with routes on the client, container, node, and gateway; each may have a different table.</p><ol><li>How many leading bits does /20 fix?</li><li>Why does /24 beat /16?</li><li>What handles an unmatched address?</li><li>What does NAT solve, and what does it not prove?</li></ol><details><summary>Review the core ideas</summary><p>CIDR states fixed leading bits. Longest-prefix matching selects the most specific entry; a default route handles unmatched destinations. NAT translates addresses but does not prove security or reachability.</p></details><p><strong>Connect forward:</strong> see how programmable rules match packet fields and apply actions.</p>"],"module-4-4":["<div class=\"section-kicker\">WHY IT EXISTS · FORWARDING NEEDS POLICY</div><h2 id=\"reader-title\" tabindex=\"-1\">Can a network act on more than destination IP?</h2><p class=\"reader-intro\">Basic forwarding maps a destination prefix to an output. Networks also isolate tenants, prioritize traffic, block packets, and steer flows. Generalized forwarding matches multiple header fields and applies explicit actions.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Match-action rules underpin SDN, cloud security groups, programmable switches, and traffic shaping. They explain why a packet is allowed, dropped, or assigned to a queue.</p></div><p><strong>By the end:</strong> read match-action rules, reason about priority and defaults, and distinguish classification from scheduling.</p>","<div class=\"section-kicker\">SYSTEM MODEL · MATCH THEN ACT</div><h2 id=\"reader-title\" tabindex=\"-1\">Rules turn packet fields into behavior</h2><p class=\"reader-intro\">A table can match ingress port, addresses, protocol, or port. The highest-priority match may forward, drop, rewrite, or classify a packet into a queue.</p><ol><li>Compare packet fields with rule conditions.</li><li>Resolve overlapping matches by priority.</li><li>Apply the action.</li><li>Schedule queued traffic for transmission.</li></ol><p>A controller may program rules, but the device executes them. Broad rules can shadow specific ones; defaults govern unmatched packets.</p>","<div class=\"section-kicker\">ENGINEERING CASE · POLICY AND LATENCY</div><h2 id=\"reader-title\" tabindex=\"-1\">Protect interactive traffic without starving uploads</h2><p class=\"reader-intro\">A gateway receives API requests, DNS queries, and bulk uploads. An engineer classifies traffic into queues, favors latency-sensitive packets, and preserves capacity for bulk work.</p><ol><li>Define which fields identify each class.</li><li>Review rule order to avoid shadowing.</li><li>Measure queue delay and loss by class.</li><li>Test sustained load and verify a safe default action.</li></ol><p><strong>Engineering lesson:</strong> classification decides what a packet is; scheduling decides when it transmits.</p>","<div class=\"section-kicker\">HANDS-ON · TEST MATCH-ACTION RULES</div><h2 id=\"reader-title\" tabindex=\"-1\">Send a sample packet through a policy table</h2><p>Try TCP/443, UDP/53, and TCP/22. The highest-priority matching rule determines the action.</p><div class=\"network-lab\" data-rule-lab><h3>Programmable forwarding table</h3><div class=\"network-lab-controls\"><label>Protocol<br><select data-rule-protocol><option>TCP</option><option>UDP</option></select></label><label>Destination port<br><input type=\"number\" min=\"1\" max=\"65535\" value=\"443\" data-rule-port></label></div><table class=\"network-table\"><thead><tr><th>Priority</th><th>Match</th><th>Action</th></tr></thead><tbody><tr data-rule=\"web\"><td>100</td><td>TCP, port 443</td><td>Forward · queue 1</td></tr><tr data-rule=\"dns\"><td>90</td><td>UDP, port 53</td><td>Forward · queue 0</td></tr><tr data-rule=\"default\"><td>1</td><td>Any other packet</td><td>Drop</td></tr></tbody></table><p class=\"network-status\" data-rule-status aria-live=\"polite\"></p></div><p>Think about what happens when rules overlap, no specific rule matches, or a queue is overloaded.</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · FOLLOW THE RULE</div><h2 id=\"reader-title\" tabindex=\"-1\">Make packet policy explainable</h2><p>A useful rule set explains why packets follow a path, get denied, or receive a service level. Keep that explanation available during review and incidents.</p><ol><li>What fields can a generalized rule match?</li><li>Why does rule priority matter?</li><li>How does classification differ from scheduling?</li><li>What should a safe default do?</li></ol><details><summary>Review the core ideas</summary><p>Generalized forwarding matches fields and performs actions. Priority resolves overlap; defaults handle unmatched packets. Classification assigns behavior or a queue; scheduling picks which packet transmits next.</p></details><p><strong>Chapter connection:</strong> the data plane applies rules; the control plane learns paths and programs forwarding state. Next, routing algorithms compute paths.</p>"]};
  if(chapterFour[id])return chapterFour[id];

  const chapterFive={"module-5-1":["<div class=\"section-kicker\">WHY IT EXISTS · EVERY ROUTER NEEDS A MAP</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a router find a low-cost path?</h2><p class=\"reader-intro\">A router cannot pick a good next hop without learning the topology and the cost of links. Link-state routing gives each router a shared graph, then lets it compute paths from its own position.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Link-state thinking helps explain route convergence after a link change, why metric design changes traffic flow, and why route computation can be separated from packet forwarding.</p></div><p><strong>By the end:</strong> describe link-state advertisements, explain Dijkstra’s algorithm at a high level, and reason about how a link-cost change affects routes.</p>","<div class=\"section-kicker\">SYSTEM MODEL · FLOOD, MAP, COMPUTE</div><h2 id=\"reader-title\" tabindex=\"-1\">Each router calculates from the same graph</h2><p class=\"reader-intro\">Routers discover neighbors, measure or configure link costs, and flood link-state advertisements. Each router builds a topology database, then runs Dijkstra from itself to find a least-cost path to every destination.</p><ol><li>Advertise local neighbors and link costs.</li><li>Flood updates so routers share topology information.</li><li>Build a graph and compute shortest paths.</li><li>Install the first hop of each path in the forwarding table.</li></ol><p>Because each router computes independently, consistent input data matters: stale or missing advertisements can produce inconsistent views.</p>","<div class=\"section-kicker\">ENGINEERING CASE · LINK COST CHANGE</div><h2 id=\"reader-title\" tabindex=\"-1\">Why did traffic move after a maintenance window?</h2><p>A team raises a link metric to drain traffic before maintenance. Routers receive the update, recompute shortest paths, and install new next hops. If one region still sees an old route, the same flow may traverse different paths depending on its entry router.</p><ol><li>Check advertisement freshness and adjacency state.</li><li>Compare topology databases on affected routers.</li><li>Confirm the computed next hop and installed forwarding entry.</li><li>Observe packet loss during convergence separately from steady-state routing.</li></ol><p><strong>Engineering lesson:</strong> route convergence is distributed state propagation plus local recomputation. A metric edit is an operational change with a propagation window.</p>","<div class=\"section-kicker\">HANDS-ON · CHANGE A LINK COST</div><h2 id=\"reader-title\" tabindex=\"-1\">See the least-cost path recalculate</h2><p>Use the slider to change the cost of link B–C. This small topology compares three candidate routes from A to D; the lowest total cost is highlighted.</p><div class=\"network-lab\" data-ls-lab><h3>Link-state path explorer</h3><label>Cost of link B–C: <output data-ls-value>2</output></label><div class=\"network-lab-controls\"><input type=\"range\" min=\"1\" max=\"8\" value=\"2\" data-ls-cost></div><table class=\"network-table\"><thead><tr><th>Candidate path</th><th>Total cost</th></tr></thead><tbody><tr data-ls-route=\"abd\"><td>A → B → D</td><td>7</td></tr><tr data-ls-route=\"acd\"><td>A → C → D</td><td>6</td></tr><tr data-ls-route=\"abcd\"><td>A → B → C → D</td><td data-ls-total>5</td></tr></tbody></table><p class=\"network-status\" data-ls-status aria-live=\"polite\"></p></div><p>Raise the B–C cost. Which path becomes cheapest, and what would the forwarding entry at A contain?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · READ THE ROUTE COMPUTATION</div><h2 id=\"reader-title\" tabindex=\"-1\">From graph to forwarding table</h2><ol><li>What information does a link-state advertisement carry?</li><li>Why can each router compute its own shortest-path tree?</li><li>Which portion of a computed path becomes a local forwarding entry?</li><li>Why monitor convergence after a metric change?</li></ol><details><summary>Review the core ideas</summary><p>Link-state routing floods topology and link costs. Routers build a graph and run Dijkstra from themselves. The forwarding table stores the next hop, not the full end-to-end route. Convergence time matters because routers may temporarily hold inconsistent state.</p></details><p><strong>Connect forward:</strong> compare this shared-topology approach with distance-vector routing, where neighbors exchange destination costs.</p>"],"module-5-2":["<div class=\"section-kicker\">WHY IT EXISTS · ROUTERS CAN COORDINATE LOCALLY</div><h2 id=\"reader-title\" tabindex=\"-1\">How do neighbors teach one another routes?</h2><p class=\"reader-intro\">A router can learn reachability without receiving the whole network map. Distance-vector routing lets each router tell its neighbors the cost it currently knows for each destination.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>This model clarifies distributed convergence, routing loops, and why “bad news” after a failure can take longer to propagate than a newly discovered shorter path.</p></div><p><strong>By the end:</strong> apply the Bellman–Ford update, trace neighbor advertisements, and explain count-to-infinity and loop-mitigation methods.</p>","<div class=\"section-kicker\">SYSTEM MODEL · BELLMAN–FORD UPDATES</div><h2 id=\"reader-title\" tabindex=\"-1\">Best neighbor plus link cost</h2><p>For router x and destination d, the Bellman–Ford relation is <code>Dₓ(d) = minᵥ [c(x,v) + Dᵥ(d)]</code>. Router x adds the link cost to neighbor v to that neighbor’s advertised distance, then picks the cheapest candidate.</p><ol><li>Receive neighbors’ destination-cost vectors.</li><li>Add each neighbor’s link cost to its advertised distance.</li><li>Select the minimum and record the chosen neighbor.</li><li>Advertise changed costs to neighbors.</li></ol><p>Updates repeat until estimates stabilize. Unlike link-state, routers do not need a complete topology map.</p>","<div class=\"section-kicker\">ENGINEERING CASE · BAD NEWS TRAVELS SLOWLY</div><h2 id=\"reader-title\" tabindex=\"-1\">A failed route keeps attracting traffic</h2><p>A link to a destination fails. A neighbor may still advertise its old low cost, so a router believes the neighbor has another way out. The neighbors can then increase their estimates in a loop, the count-to-infinity problem.</p><ol><li>Look for route flaps and steadily increasing metrics.</li><li>Check which neighbor each router selected as next hop.</li><li>Apply loop mitigation such as split horizon, poisoned reverse, or bounded infinity.</li><li>Measure convergence and packet loss after withdrawal.</li></ol><p><strong>Engineering lesson:</strong> local information can be enough for routine updates but ambiguous during failure. The algorithm’s loop protections are part of its reliability model.</p>","<div class=\"section-kicker\">HANDS-ON · WATCH A WITHDRAWAL</div><h2 id=\"reader-title\" tabindex=\"-1\">Step through a simplified bad-news update</h2><p>This teaching model illustrates how stale neighbor information can make a metric rise after a route fails. Real protocols use safeguards, timers, and protocol-specific rules.</p><div class=\"network-lab\" data-dv-lab><h3>Distance-vector withdrawal</h3><div class=\"network-diagram\"><div class=\"network-node\">A<small>router</small></div><span class=\"network-arrow\">↔</span><div class=\"network-node\">B<small>router</small></div><span class=\"network-arrow\">↔</span><div class=\"network-node\">Destination<small>route withdrawn</small></div></div><div class=\"network-lab-controls\"><button type=\"button\" data-dv-step>Exchange next update →</button><button type=\"button\" data-dv-reset>Reset</button></div><p class=\"network-status\" data-dv-status aria-live=\"polite\"></p></div><p>Which route-loop prevention would stop the model’s stale route from being reused?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · REASON ABOUT CONVERGENCE</div><h2 id=\"reader-title\" tabindex=\"-1\">What does a router know about its neighbor?</h2><ol><li>State the Bellman–Ford candidate-cost calculation.</li><li>Why does a new low-cost route often spread quickly?</li><li>Why can a withdrawn route linger?</li><li>How do split horizon and poisoned reverse reduce loops?</li></ol><details><summary>Review the core ideas</summary><p>A router compares neighbor-advertised distances plus local link cost. New routes can propagate quickly because each improvement is shared. Failures can create stale circular beliefs. Split horizon avoids advertising a route back on the interface from which it was learned; poisoned reverse advertises it as unreachable.</p></details><p><strong>Connect forward:</strong> OSPF applies link-state routing within an autonomous system and uses areas to control scale.</p>"],"module-5-3":["<div class=\"section-kicker\">WHY IT EXISTS · ROUTING MUST SCALE</div><h2 id=\"reader-title\" tabindex=\"-1\">How can an organization route without one flat map?</h2><p class=\"reader-intro\">Inside a large organization, every router learning every link creates unnecessary state and update traffic. OSPF organizes an autonomous system into areas while preserving a backbone that connects them.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>OSPF concepts help engineers understand enterprise and cloud network changes, area boundaries, summarized routes, and why an internal path can fail even when the external Internet path is healthy.</p></div><p><strong>By the end:</strong> explain OSPF’s link-state operation, identify area 0 and area border routers, and reason about route summarization.</p>","<div class=\"section-kicker\">SYSTEM MODEL · AREAS AND THE BACKBONE</div><h2 id=\"reader-title\" tabindex=\"-1\">Keep detail local; share reachability across areas</h2><p>OSPF routers in an area exchange link-state information and calculate routes within that area. Area border routers (ABRs) connect areas to the backbone, area 0, and can advertise summarized reachability between them.</p><ol><li>Routers form adjacencies and exchange link-state advertisements.</li><li>Each area maintains a link-state database and computes paths.</li><li>ABRs connect non-backbone areas through area 0.</li><li>Summaries reduce how much topology detail crosses boundaries.</li></ol><p>Hierarchies trade global detail for bounded state and clearer operational domains.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A ROUTE DISAPPEARS AT THE BORDER</div><h2 id=\"reader-title\" tabindex=\"-1\">Debug the area boundary before the application</h2><p>A service is reachable inside one site but not from another area. The local router knows the subnet, yet the remote area has no usable summary or the ABR is not advertising it.</p><ol><li>Verify the destination exists in its originating area.</li><li>Check OSPF adjacency and database consistency on the ABR.</li><li>Inspect inter-area summary routes and area 0 connectivity.</li><li>Confirm the route was installed in the remote forwarding table.</li></ol><p><strong>Engineering lesson:</strong> hierarchical routing introduces boundaries that are useful for scale and important during debugging.</p>","<div class=\"section-kicker\">HANDS-ON · EXPLORE THE OSPF HIERARCHY</div><h2 id=\"reader-title\" tabindex=\"-1\">Select an area and inspect what it knows</h2><p>Choose a network area. The diagram identifies its local routers and which destinations are learned through the backbone summary.</p><div class=\"network-lab\" data-ospf-lab><h3>Area explorer</h3><div class=\"network-lab-controls\"><button type=\"button\" data-ospf-area=\"0\" aria-pressed=\"true\">Area 0 · backbone</button><button type=\"button\" data-ospf-area=\"1\" aria-pressed=\"false\">Area 1 · services</button><button type=\"button\" data-ospf-area=\"2\" aria-pressed=\"false\">Area 2 · users</button></div><div class=\"network-diagram\" data-ospf-diagram></div><p class=\"network-status\" data-ospf-status aria-live=\"polite\"></p></div><p>Why might the users area receive a summary rather than every internal link from the services area?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · ROUTE ACROSS AREAS</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the boundary that owns the route</h2><ol><li>What information does an OSPF area share internally?</li><li>What role does area 0 play?</li><li>Which router connects areas and advertises summaries?</li><li>What evidence separates an intra-area failure from an inter-area failure?</li></ol><details><summary>Review the core ideas</summary><p>OSPF floods link-state information and computes routes within an area. Area 0 is the backbone. ABRs connect areas and can summarize reachability. Check the local database, ABR adjacency, summary route, then installed route to locate a boundary issue.</p></details><p><strong>Connect forward:</strong> BGP uses policy-driven path advertisements to connect separate autonomous systems.</p>"],"module-5-4":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORKS NEED POLICY BETWEEN THEM</div><h2 id=\"reader-title\" tabindex=\"-1\">How does traffic choose an Internet provider path?</h2><p class=\"reader-intro\">The Internet consists of independently operated autonomous systems (ASes). They must exchange reachability while respecting business relationships, security rules, and traffic-engineering goals. BGP is the path-vector protocol used for this interdomain coordination.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>BGP helps explain regional reachability, multi-cloud paths, provider outages, route leaks, and why the shortest AS path is not always chosen. It connects application availability to external routing policy.</p></div><p><strong>By the end:</strong> read an AS path, distinguish reachability from policy, and explain the role of local preference and route filtering.</p>","<div class=\"section-kicker\">SYSTEM MODEL · PATH VECTOR AND ROUTE ATTRIBUTES</div><h2 id=\"reader-title\" tabindex=\"-1\">Reachability plus the path and the policy</h2><p>BGP speakers advertise destination prefixes with attributes such as AS-PATH and NEXT-HOP. AS-PATH records the ASes a route traverses and helps detect loops. Operators apply local policy—often including local preference—before comparing attributes such as path length.</p><ol><li>Receive candidate routes from eBGP peers or iBGP routers.</li><li>Filter routes and assign local preference by policy.</li><li>Choose the best route, then advertise permitted reachability.</li><li>Install a next hop for packet forwarding.</li></ol><p>BGP selects routes according to policy, not a universal shortest-distance objective.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A SHORTER PATH LOSES</div><h2 id=\"reader-title\" tabindex=\"-1\">Why a provider keeps a longer route</h2><p>Two upstreams advertise the same service prefix. One path contains fewer AS hops, but the organization prefers the other provider for cost or reliability. Local preference can make that path win despite its longer AS-PATH.</p><ol><li>Inspect the selected route’s attributes and neighbor.</li><li>Compare local preference and route filters across peers.</li><li>Check AS-PATH for loops or unexpected transit.</li><li>Validate the route in both directions; return traffic may use a different provider.</li></ol><p><strong>Engineering lesson:</strong> Internet paths are policy decisions made independently by many networks. “Shortest” does not mean “best.”</p>","<div class=\"section-kicker\">HANDS-ON · COMPARE BGP CANDIDATES</div><h2 id=\"reader-title\" tabindex=\"-1\">Change policy and watch the winning route</h2><p>Choose whether this router prioritizes local preference or AS-PATH length. In both cases it first excludes routes that fail policy filters.</p><div class=\"network-lab\" data-bgp-lab><h3>BGP route selection</h3><div class=\"network-lab-controls\"><label>Selection emphasis<br><select data-bgp-policy><option value=\"local\">Prefer local preference</option><option value=\"path\">Prefer shorter AS-PATH</option></select></label></div><table class=\"network-table\"><thead><tr><th>Peer</th><th>Local preference</th><th>AS-PATH</th><th>Next hop</th></tr></thead><tbody><tr data-bgp-route=\"provider-a\"><td>Provider A</td><td>100</td><td>64510 64496</td><td>198.51.100.1</td></tr><tr data-bgp-route=\"provider-b\"><td>Provider B</td><td>200</td><td>64520 64530 64496</td><td>203.0.113.2</td></tr></tbody></table><p class=\"network-status\" data-bgp-status aria-live=\"polite\"></p></div><p>Which selected path would you expect to carry outbound traffic? What else could cause the return path to differ?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · READ THE POLICY</div><h2 id=\"reader-title\" tabindex=\"-1\">Explain why this route won</h2><ol><li>What does AS-PATH tell a BGP speaker?</li><li>Why is it not enough to choose the shortest AS-PATH?</li><li>What is local preference used for?</li><li>Why can outbound and return paths differ?</li></ol><details><summary>Review the core ideas</summary><p>BGP advertises prefix reachability with attributes. AS-PATH helps detect loops and describes the advertised path. Local preference expresses local policy; providers and organizations can choose routes for cost, security, or reliability instead of hop count. Each AS chooses independently, so paths can be asymmetric.</p></details><p><strong>Connect forward:</strong> SDN moves some control decisions into software that programs network devices.</p>"],"module-5-5":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORK POLICY CHANGES OFTEN</div><h2 id=\"reader-title\" tabindex=\"-1\">Can software coordinate the network control plane?</h2><p class=\"reader-intro\">Traditional routers combine control logic and packet forwarding in each device. Software-defined networking separates a logically centralized controller from forwarding devices, making network-wide policy easier to automate.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>SDN resembles distributed systems design: controllers maintain state, devices execute instructions, and failures can leave control and data views temporarily inconsistent. It appears in cloud fabrics, data centers, and programmable networks.</p></div><p><strong>By the end:</strong> distinguish control and data planes, trace a rule installation, and identify controller availability and consistency trade-offs.</p>","<div class=\"section-kicker\">SYSTEM MODEL · CONTROLLER AND FORWARDERS</div><h2 id=\"reader-title\" tabindex=\"-1\">One logical control point, many packet processors</h2><p>The controller collects topology and policy, computes rules, then communicates with switches over a southbound interface. Switches match packet fields and perform actions. Applications can use the controller’s northbound interface to express intent.</p><ol><li>Application defines a policy or network intent.</li><li>Controller translates intent into forwarding rules.</li><li>Southbound protocol installs rules on devices.</li><li>Switches execute rules locally for each packet.</li></ol><p>“Logically centralized” does not require one physical server; production controllers are commonly replicated.</p>","<div class=\"section-kicker\">ENGINEERING CASE · PARTIAL RULE DEPLOYMENT</div><h2 id=\"reader-title\" tabindex=\"-1\">A policy reaches some switches, but not all</h2><p>A deployment updates access rules across many switches. A timeout leaves some devices with the new rule and others with the old rule. This partial state can create intermittent access or asymmetric paths.</p><ol><li>Track desired rule version and installed version per switch.</li><li>Make updates idempotent and safe to retry.</li><li>Use staged rollout, acknowledgments, and rollback plans.</li><li>Monitor data-plane behavior after control-plane success.</li></ol><p><strong>Engineering lesson:</strong> a successful controller request is not proof every device is enforcing the intended policy.</p>","<div class=\"section-kicker\">HANDS-ON · INSTALL A FORWARDING RULE</div><h2 id=\"reader-title\" tabindex=\"-1\">Step from intent to packet action</h2><p>Advance through the control and data path. The packet is forwarded only after the device has received and activated the rule.</p><div class=\"network-lab\" data-sdn-lab><h3>SDN rule deployment</h3><ol class=\"router-pipeline\"><li data-sdn-step=\"0\" class=\"is-active\"><b>1 · Intent</b>Allow HTTPS</li><li data-sdn-step=\"1\"><b>2 · Controller</b>Build rule</li><li data-sdn-step=\"2\"><b>3 · Switch</b>Install rule</li><li data-sdn-step=\"3\"><b>4 · Data plane</b>Forward packet</li></ol><div class=\"network-lab-controls\"><button type=\"button\" data-sdn-next>Advance deployment →</button><button type=\"button\" data-sdn-reset>Reset</button></div><p class=\"network-status\" data-sdn-status aria-live=\"polite\"></p></div><p>Which acknowledgment would you log to prove the switch—not just the controller—activated the rule?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · VERIFY THE DEVICE STATE</div><h2 id=\"reader-title\" tabindex=\"-1\">Control plane intent versus data plane reality</h2><ol><li>What does the controller do that a forwarding switch does not?</li><li>Why can logically centralized control still be replicated?</li><li>What can go wrong during a multi-device rule rollout?</li><li>Which telemetry verifies that the data plane behaves as intended?</li></ol><details><summary>Review the core ideas</summary><p>Controllers translate policy into device rules; switches execute those rules. Replication improves controller availability. Partial deployment can create inconsistent behavior, so track versions, acknowledgments, rollout state, and packet outcomes.</p></details><p><strong>Connect forward:</strong> learn how ICMP and management telemetry help operators observe network behavior.</p>"],"module-5-6":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORKS NEED OBSERVABILITY</div><h2 id=\"reader-title\" tabindex=\"-1\">How do operators tell where a packet stopped?</h2><p class=\"reader-intro\">A failed request rarely explains whether the host is down, a route is missing, a packet is filtered, or a link is overloaded. ICMP provides network-layer error and diagnostic messages; management protocols expose device health and counters.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>These tools shorten incident response. Ping and traceroute test reachability and path behavior; SNMP metrics can reveal errors, discards, and utilization before users report an outage.</p></div><p><strong>By the end:</strong> explain ICMP’s diagnostic role, interpret basic ping and traceroute evidence, and connect SNMP counters to operational questions.</p>","<div class=\"section-kicker\">SYSTEM MODEL · DIAGNOSTIC MESSAGES AND METRICS</div><h2 id=\"reader-title\" tabindex=\"-1\">ICMP reports; SNMP measures</h2><p>ICMP messages travel with IP to report events such as destination unreachable or time exceeded. Ping uses echo request/reply; traceroute relies on TTL or hop-limit expiration to reveal intermediate hops. SNMP uses a manager-agent model to read or configure managed objects, including interface counters.</p><ol><li>Use ICMP probes to test whether a destination or hop responds.</li><li>Read interface counters to identify errors, drops, or utilization.</li><li>Correlate measurements with timestamps and service telemetry.</li></ol><p>A missing ICMP reply is not definitive proof that a host is down; firewalls and rate limits may suppress diagnostics.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE HEALTH CHECK LIES</div><h2 id=\"reader-title\" tabindex=\"-1\">A service is up but users still see failures</h2><p>A host responds to ping, but the application times out. The network-layer probe proves only that some ICMP traffic reached the host and returned; it does not confirm the right process is listening or that dependencies are healthy.</p><ol><li>Compare ICMP reachability with TCP connection and application checks.</li><li>Use traceroute carefully to identify where responses stop or change.</li><li>Inspect SNMP interface errors, discards, and utilization near that time.</li><li>Correlate network data with server logs and request IDs.</li></ol><p><strong>Engineering lesson:</strong> one probe answers one question. Combine evidence without treating any single metric as the whole diagnosis.</p>","<div class=\"section-kicker\">HANDS-ON · CHOOSE A DIAGNOSTIC</div><h2 id=\"reader-title\" tabindex=\"-1\">Match the tool to the symptom</h2><p>Choose a symptom. The explorer suggests a first diagnostic and names what it can—and cannot—prove.</p><div class=\"network-lab\" data-icmp-lab><h3>Network diagnosis explorer</h3><div class=\"network-lab-controls\"><button type=\"button\" data-diag=\"reachability\" aria-pressed=\"true\">Host unreachable</button><button type=\"button\" data-diag=\"loss\" aria-pressed=\"false\">Intermittent loss</button><button type=\"button\" data-diag=\"slow\" aria-pressed=\"false\">Slow service</button></div><div class=\"network-diagram\" data-diag-flow></div><p class=\"network-status\" data-diag-status aria-live=\"polite\"></p></div><p>For each symptom, name one application-level check that should accompany network telemetry.</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · GATHER EVIDENCE, NOT ASSUMPTIONS</div><h2 id=\"reader-title\" tabindex=\"-1\">Turn measurements into a debugging path</h2><ol><li>What does a successful ping establish—and what does it leave unknown?</li><li>How does traceroute reveal path information?</li><li>Which SNMP counters can point to link trouble?</li><li>Why correlate network measurements with application telemetry?</li></ol><details><summary>Review the core ideas</summary><p>ICMP supports network errors and diagnostics. Ping and traceroute expose reachability and path clues, but filters may hide replies. SNMP exposes device and interface measurements. Correlate these with transport and application checks to locate the failing layer.</p></details><p><strong>Chapter recap:</strong> routing protocols compute reachability, BGP applies inter-network policy, SDN can program forwarding, and observability helps verify the outcome.</p>"]};
  if(chapterFive[id])return chapterFive[id];
  const chapterSix={"module-6-1":["<div class=\"section-kicker\">WHY IT EXISTS · ONE LINK, ONE HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">What does the link layer add between neighbors?</h2><p class=\"reader-intro\">IP gets a datagram across networks, but each physical connection needs a local way to package bits, identify the next device, and decide who may transmit. The link layer provides those hop-by-hop services over Ethernet, Wi-Fi, and other links.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Link-layer behavior explains local network outages, corrupted frames, Wi-Fi contention, NIC errors, and why a packet capture contains headers that change at each router hop.</p></div><p><strong>By the end:</strong> describe framing, local addressing, link access, and how link services fit beneath IP.</p>","<div class=\"section-kicker\">SYSTEM MODEL · FRAME AND HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">Each hop wraps the same datagram in a local frame</h2><p>An IP datagram moves hop by hop. At each link, the sender encapsulates it in a frame with a link-layer header and trailer. The next device validates the frame, removes that framing, then forwards the datagram into a new frame for the next link.</p><ol><li><strong>Framing:</strong> mark where a unit begins and ends.</li><li><strong>Link addressing:</strong> identify the local sender and receiver.</li><li><strong>Medium access:</strong> coordinate who uses a shared channel.</li><li><strong>Error detection:</strong> detect likely corruption before delivery upward.</li></ol><p>Link-layer addresses are local to a link; routers replace the frame as a datagram crosses to a new link.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE PACKET CAPTURE CHANGES</div><h2 id=\"reader-title\" tabindex=\"-1\">Why do MAC addresses change at a router?</h2><p>A developer compares packet captures on a laptop and a server. The source and destination IP addresses remain end-to-end, but Ethernet source and destination MAC addresses describe only the current local hop. A router removes the incoming frame and builds a new one for its outgoing interface.</p><ol><li>Use IP addresses to reason about the network-layer endpoints.</li><li>Use MAC addresses to reason about adjacent link-layer devices.</li><li>Check the default gateway’s MAC on the local subnet.</li><li>Expect different frame headers at each routed hop.</li></ol><p><strong>Engineering lesson:</strong> packet captures are hop-specific views. Knowing which header belongs to which layer prevents misreading a route as an end-to-end MAC path.</p>","<div class=\"section-kicker\">HANDS-ON · FOLLOW ENCAPSULATION</div><h2 id=\"reader-title\" tabindex=\"-1\">Inspect the frame at two consecutive links</h2><p>Choose a hop to inspect. The IP datagram stays the same while the link addresses identify the neighbors on that hop.</p><div class=\"network-lab\" data-frame-lab><h3>Frame encapsulation explorer</h3><div class=\"network-lab-controls\"><button type=\"button\" data-frame-hop=\"lan\" aria-pressed=\"true\">Laptop → router</button><button type=\"button\" data-frame-hop=\"wan\" aria-pressed=\"false\">Router → server</button></div><div class=\"network-diagram\" data-frame-diagram></div><p class=\"network-status\" data-frame-status aria-live=\"polite\"></p></div><p>Which fields describe the end-to-end network path, and which fields are replaced at each hop?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · READ THE RIGHT HEADER</div><h2 id=\"reader-title\" tabindex=\"-1\">Separate the local hop from the end-to-end route</h2><ol><li>What problem does a frame solve that an IP datagram does not?</li><li>Why are source and destination MAC addresses hop-local?</li><li>Which link service detects corruption?</li><li>Why does the link layer at one hop not guarantee end-to-end delivery?</li></ol><details><summary>Review the core ideas</summary><p>The link layer packages a network-layer datagram for one local link, identifies adjacent devices, coordinates medium access, and detects some errors. Routers remove and replace frames at each hop while forwarding the IP datagram.</p></details><p><strong>Connect forward:</strong> compare the error-detection methods that help a receiver decide whether a frame was corrupted.</p>"],"module-6-2":["<div class=\"section-kicker\">WHY IT EXISTS · BITS CAN CHANGE IN TRANSIT</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a receiver detect a damaged frame?</h2><p class=\"reader-intro\">Noise, interference, and hardware faults can flip bits. A receiver needs a compact way to detect likely corruption before it trusts the frame. Parity, checksums, and cyclic redundancy checks add redundancy so the receiver can compare what arrived with what the sender encoded.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Error detection matters in storage, networking, serialization, and hardware interfaces. It also clarifies an important boundary: detecting corruption is not the same as repairing it or guaranteeing delivery.</p></div><p><strong>By the end:</strong> explain parity and CRC checks, distinguish detection from correction, and name recovery choices such as discard, retransmit, or forward-error correction.</p>","<div class=\"section-kicker\">SYSTEM MODEL · ADD REDUNDANT CHECK BITS</div><h2 id=\"reader-title\" tabindex=\"-1\">Detect errors by checking a relation</h2><p>The sender computes check bits from the payload and sends both. The receiver recomputes the check and compares it with the received value. A mismatch signals likely corruption; some error patterns can evade simple checks, so stronger codes are chosen for the channel and required reliability.</p><ol><li><strong>Parity:</strong> add one bit to make the count of 1s even or odd.</li><li><strong>Checksum:</strong> combine words using arithmetic and compare the result.</li><li><strong>CRC:</strong> treat bits as a polynomial and compute a remainder.</li><li><strong>Recovery:</strong> discard a bad frame, request retransmission, or use extra redundancy to correct it.</li></ol><p>CRC is strong at detecting common burst errors but does not itself recover the original data.</p>","<div class=\"section-kicker\">ENGINEERING CASE · CORRUPTION VERSUS LOSS</div><h2 id=\"reader-title\" tabindex=\"-1\">A checksum fails on a healthy-looking link</h2><p>A NIC reports receive errors while application logs show timeouts. A corrupted frame may be discarded before IP sees it; repeated corruption can look like packet loss to higher layers. The transport may retransmit, but the root cause could be a cable, radio environment, NIC, or duplex mismatch.</p><ol><li>Compare interface error counters with retransmission and loss metrics.</li><li>Look for one direction or one interface with elevated errors.</li><li>Check physical media and radio conditions before tuning TCP retries.</li><li>Distinguish frame-level detection from end-to-end recovery.</li></ol><p><strong>Engineering lesson:</strong> counters at the layer closest to the fault often identify the cause more clearly than an application timeout.</p>","<div class=\"section-kicker\">HANDS-ON · FLIP A BIT</div><h2 id=\"reader-title\" tabindex=\"-1\">See even parity detect one-bit corruption</h2><p>Toggle a data bit. The sender adds an even-parity bit; the receiver flags the frame if the total count of ones is odd. This tiny example shows detection, not general correction.</p><div class=\"network-lab\" data-parity-lab><h3>Parity checker</h3><div class=\"network-lab-controls\"><label>Eight data bits<br><input data-parity-bits value=\"10110010\" maxlength=\"8\" inputmode=\"numeric\"></label><button type=\"button\" data-parity-flip>Flip bit 4</button></div><div class=\"network-diagram\" data-parity-diagram></div><p class=\"network-status\" data-parity-status aria-live=\"polite\"></p></div><p>Try flipping two bits. Why can simple parity miss an even number of bit errors?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · DETECTION IS NOT DELIVERY</div><h2 id=\"reader-title\" tabindex=\"-1\">State what an error code guarantees</h2><ol><li>What does a parity bit detect reliably in this simple example?</li><li>Why can two flipped bits evade parity detection?</li><li>How does CRC differ from error correction?</li><li>Which layer may retransmit after a corrupted frame is discarded?</li></ol><details><summary>Review the core ideas</summary><p>Error-detection codes add redundancy to recognize many corruptions. Even parity detects an odd number of flipped bits but can miss an even number. CRC detects many common patterns. Recovery requires retransmission or forward-error-correction data; detection alone does not guarantee delivery.</p></details><p><strong>Connect forward:</strong> on a shared link, devices also need rules for who may transmit and when.</p>"],"module-6-3":["<div class=\"section-kicker\">WHY IT EXISTS · MANY DEVICES SHARE ONE MEDIUM</div><h2 id=\"reader-title\" tabindex=\"-1\">How do devices take turns on a shared channel?</h2><p class=\"reader-intro\">On a shared broadcast medium, simultaneous transmissions can collide or interfere. A multiple-access protocol coordinates who can use the channel—through reserved slices, contention and backoff, or explicit turns.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>This model explains Wi-Fi airtime, wireless retries, latency under load, and why adding devices can reduce per-device throughput even when each has a fast radio.</p></div><p><strong>By the end:</strong> compare channel partitioning, random access, and taking-turns protocols, and connect contention to throughput and delay.</p>","<div class=\"section-kicker\">SYSTEM MODEL · PARTITION, COMPETE, OR TAKE TURNS</div><h2 id=\"reader-title\" tabindex=\"-1\">Three ways to share a channel</h2><ol><li><strong>Channel partitioning:</strong> assign each sender a frequency band, time slot, or code.</li><li><strong>Random access:</strong> transmit when ready, detect or infer collision, then retry after randomized backoff.</li><li><strong>Taking turns:</strong> use a coordinator or token to grant transmission opportunities.</li></ol><p>Partitioning avoids collisions but can waste idle capacity. Random access is simple and adapts to bursts but can collide. Taking turns can provide fairness but adds coordination overhead and waiting.</p><p>Wi-Fi uses carrier sensing and randomized backoff; wired Ethernet’s historical shared-medium collision behavior differs from modern switched full-duplex links.</p>","<div class=\"section-kicker\">ENGINEERING CASE · WI-FI SLOWS IN A BUSY ROOM</div><h2 id=\"reader-title\" tabindex=\"-1\">More clients compete for airtime</h2><p>A conference room’s Wi-Fi slows as more clients join. Devices share airtime; they wait for a clear channel and back off after contention. A distant or slow client can consume disproportionate airtime because it transmits at a lower rate.</p><ol><li>Measure channel utilization and retransmissions, not only signal bars.</li><li>Check channel overlap and neighboring access points.</li><li>Reduce unnecessary broadcasts and large burst transfers.</li><li>Separate capacity constraints from an application’s server latency.</li></ol><p><strong>Engineering lesson:</strong> airtime is the scarce resource. Connection count and nominal link rate alone do not describe user capacity.</p>","<div class=\"section-kicker\">HANDS-ON · PICK A CHANNEL-ACCESS STRATEGY</div><h2 id=\"reader-title\" tabindex=\"-1\">Compare collision and waiting trade-offs</h2><p>Select an access strategy and set the number of active senders. The model describes expected behavior qualitatively; real throughput depends on packet sizes, timing, and radio conditions.</p><div class=\"network-lab\" data-access-lab><h3>Shared-channel explorer</h3><div class=\"network-lab-controls\"><label>Protocol<br><select data-access-mode><option value=\"random\">Random access with backoff</option><option value=\"partition\">Time partitioning</option><option value=\"turns\">Taking turns</option></select></label><label>Active senders<br><input type=\"range\" min=\"2\" max=\"20\" value=\"8\" data-access-count></label></div><p class=\"network-status\" data-access-status aria-live=\"polite\"></p></div><p>When are reserved time slots wasteful? When is contention a reasonable trade-off?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · REASON ABOUT AIRTIME</div><h2 id=\"reader-title\" tabindex=\"-1\">Choose the protocol for the workload</h2><ol><li>How does channel partitioning avoid collisions?</li><li>Why does random backoff help after contention?</li><li>What fairness benefits can a turn-taking protocol offer?</li><li>Why might a slow Wi-Fi client consume more airtime?</li></ol><details><summary>Review the core ideas</summary><p>Partitioning separates senders by time, frequency, or code. Random access allows contention and backs off after collisions. Turn-taking coordinates permission. Each trades utilization, fairness, delay, and coordination complexity differently.</p></details><p><strong>Connect forward:</strong> see how ARP maps a local IP next hop to a MAC address and how switches learn where hosts live.</p>"],"module-6-4":["<div class=\"section-kicker\">WHY IT EXISTS · LOCAL DELIVERY NEEDS A MAC DESTINATION</div><h2 id=\"reader-title\" tabindex=\"-1\">How does a host find its next-hop hardware address?</h2><p class=\"reader-intro\">An application targets an IP address, but an Ethernet frame needs a local destination MAC address. ARP discovers the MAC for a next-hop IPv4 address on the local network. Ethernet switches then learn which MAC addresses are reachable on each port.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>ARP and switching explain local connectivity failures, duplicate IP symptoms, broadcast storms, stale neighbor caches, and why a remote server’s MAC is not sent across the Internet.</p></div><p><strong>By the end:</strong> trace ARP request/reply, distinguish local destination from default gateway, and explain switch learning and flooding.</p>","<div class=\"section-kicker\">SYSTEM MODEL · DISCOVER THEN LEARN</div><h2 id=\"reader-title\" tabindex=\"-1\">Broadcast the question; learn from the reply</h2><ol><li>Check whether the destination IP is on the local subnet.</li><li>If local, ARP asks who owns that IP; if remote, ARP asks for the default gateway’s IP.</li><li>The target replies with its MAC, and the sender caches the mapping.</li><li>A switch learns each source MAC on the ingress port and forwards known destinations selectively.</li></ol><p>If a destination MAC is unknown, a switch floods the frame within that VLAN. The receiver replies; the switch learns the reply’s source and can then unicast future frames.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE HOST IS ON THE WRONG VLAN</div><h2 id=\"reader-title\" tabindex=\"-1\">Why does ARP keep asking with no answer?</h2><p>A service host has an IP address and link, but clients cannot reach it. The ARP request is broadcast only within its local VLAN; if the host is in a different VLAN or the port is misconfigured, the request never reaches it.</p><ol><li>Check the client’s subnet mask and selected next hop.</li><li>Inspect ARP or neighbor-cache state for the next-hop IP.</li><li>Verify switch-port VLAN membership and trunk configuration.</li><li>Use the switch MAC table to check which port learned the host.</li></ol><p><strong>Engineering lesson:</strong> ARP is link-local. A missing mapping can indicate a local Layer 2 boundary problem before IP routing is even involved.</p>","<div class=\"section-kicker\">HANDS-ON · WATCH A SWITCH LEARN</div><h2 id=\"reader-title\" tabindex=\"-1\">Walk an ARP request through a LAN</h2><p>Advance the exchange. The first frame is flooded because the destination MAC is unknown; the reply teaches the switch where the host is.</p><div class=\"network-lab\" data-switch-lab><h3>ARP and Ethernet switching</h3><div class=\"network-diagram\"><div class=\"network-node\">Laptop<small>IP .10 · MAC AA</small></div><span class=\"network-arrow\">↔</span><div class=\"network-node\">Switch<small>MAC table</small></div><span class=\"network-arrow\">↔</span><div class=\"network-node\">Gateway<small>IP .1 · MAC GG</small></div></div><div class=\"network-lab-controls\"><button type=\"button\" data-switch-next>Advance frame →</button><button type=\"button\" data-switch-reset>Reset</button></div><table class=\"network-table\"><thead><tr><th>Switch learned table</th><th>Port</th></tr></thead><tbody><tr data-switch-entry=\"laptop\"><td>AA · Laptop</td><td>1</td></tr><tr data-switch-entry=\"gateway\"><td>GG · Gateway</td><td>2</td></tr></tbody></table><p class=\"network-status\" data-switch-status aria-live=\"polite\"></p></div><p>Why is the ARP request broadcast inside the VLAN while a later known-destination frame is unicast?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · TRACE THE LOCAL NEXT HOP</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the neighbor the host actually needs</h2><ol><li>When does a host ARP for the destination, and when for the gateway?</li><li>How does a switch learn its forwarding table?</li><li>Why does an unknown unicast get flooded within a VLAN?</li><li>What would a wrong VLAN do to ARP?</li></ol><details><summary>Review the core ideas</summary><p>ARP maps a local IPv4 next-hop address to a MAC. Remote destinations use the gateway’s MAC. Switches learn source MACs by ingress port; unknown destinations are flooded within the VLAN until learning occurs.</p></details><p><strong>Connect forward:</strong> VLANs create separate broadcast domains; MPLS and data-center fabrics add larger-scale segmentation and path control.</p>"],"module-6-5":["<div class=\"section-kicker\">WHY IT EXISTS · SEGMENT AND SCALE THE LAN</div><h2 id=\"reader-title\" tabindex=\"-1\">How do large networks keep local traffic organized?</h2><p class=\"reader-intro\">A single flat broadcast domain is hard to secure and scale. VLANs create logical Layer 2 segments; MPLS labels steer traffic through provider networks; data-center fabrics connect large server populations with predictable paths.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>These ideas appear in cloud tenancy, Kubernetes clusters, private networking, service placement, and diagnosing why two machines on the same switch cannot communicate.</p></div><p><strong>By the end:</strong> explain VLAN tagging and broadcast boundaries, describe MPLS label switching, and recognize leaf-spine data-center topology.</p>","<div class=\"section-kicker\">SYSTEM MODEL · SEGMENT, LABEL, FABRIC</div><h2 id=\"reader-title\" tabindex=\"-1\">Different tools solve different scaling problems</h2><ol><li><strong>VLAN:</strong> assigns Ethernet frames to a logical broadcast domain, commonly using an 802.1Q tag on trunks.</li><li><strong>Inter-VLAN routing:</strong> moves packets between VLANs through a router or Layer 3 switch.</li><li><strong>MPLS:</strong> attaches labels that provider routers use to forward traffic along a label-switched path.</li><li><strong>Data-center fabric:</strong> leaf switches connect servers; spine switches provide multiple paths between leaves.</li></ol><p>VLANs segment local Layer 2 traffic; MPLS steers across provider infrastructure; leaf-spine design scales server connectivity with predictable hop counts.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A SERVICE CANNOT REACH ITS PEER</div><h2 id=\"reader-title\" tabindex=\"-1\">Check segmentation before changing application code</h2><p>Two services have IP addresses in the same data center but cannot exchange frames. They may be placed in different VLANs, with no inter-VLAN route or policy permitting traffic. Alternatively, a trunk may omit the required tag.</p><ol><li>Inspect interface VLAN membership and trunk allowed-VLAN lists.</li><li>Check whether the destination is local or requires Layer 3 routing.</li><li>Verify route and security policy between segments.</li><li>In a fabric, trace the overlay or label path and confirm endpoint learning.</li></ol><p><strong>Engineering lesson:</strong> physical proximity does not guarantee a shared broadcast domain or permitted path. Network segmentation is an explicit part of application deployment.</p>","<div class=\"section-kicker\">HANDS-ON · TEST A VLAN BOUNDARY</div><h2 id=\"reader-title\" tabindex=\"-1\">Select the segment and see whether frames can cross</h2><p>Choose whether two endpoints share a VLAN and whether a Layer 3 gateway is present. The model distinguishes local frame delivery from routed inter-VLAN traffic.</p><div class=\"network-lab\" data-vlan-lab><h3>VLAN reachability explorer</h3><div class=\"network-lab-controls\"><label>Endpoint B VLAN<br><select data-vlan-b><option value=\"10\">VLAN 10</option><option value=\"20\">VLAN 20</option></select></label><label><input type=\"checkbox\" data-vlan-gateway checked> Inter-VLAN gateway configured</label></div><div class=\"network-diagram\" data-vlan-diagram></div><p class=\"network-status\" data-vlan-status aria-live=\"polite\"></p></div><p>What happens to a broadcast sent by endpoint A when B is in another VLAN?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · PICK THE RIGHT BOUNDARY</div><h2 id=\"reader-title\" tabindex=\"-1\">Segment traffic without losing the path</h2><ol><li>What does a VLAN tag identify on a trunk?</li><li>Why does communication across VLANs need a Layer 3 function?</li><li>How does MPLS use labels differently from an IP route lookup?</li><li>What role do leaf and spine switches play?</li></ol><details><summary>Review the core ideas</summary><p>VLANs separate broadcast domains. A router or Layer 3 switch forwards between them under policy. MPLS uses labels to steer traffic in provider networks. Leaf-spine fabrics connect servers through a scalable two-tier topology.</p></details><p><strong>Chapter recap:</strong> links frame and validate datagrams, access protocols share media, ARP and switching handle local delivery, and segmentation scales the network.</p>"]};
  if(chapterSix[id])return chapterSix[id];
  const chapterSeven={"module-7-1":["<div class=\"section-kicker\">WHY IT EXISTS · RADIO LINKS ARE SHARED AND VARIABLE</div><h2 id=\"reader-title\" tabindex=\"-1\">Why does wireless behave differently from a cable?</h2><p class=\"reader-intro\">A wireless sender transmits energy through a shared radio channel. Obstacles, distance, interference, and movement change the signal that reaches the receiver, so the link’s quality can vary over time.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Wireless behavior affects mobile app latency, retry rates, battery use, and why a service works near an access point but fails at the edge of coverage. It explains why a stable API can sit on top of an unstable radio link.</p></div><p><strong>By the end:</strong> explain attenuation and interference, connect signal quality to loss and rate adaptation, and reason about the hidden-terminal problem.</p>","<div class=\"section-kicker\">SYSTEM MODEL · SIGNAL, NOISE, AND SHARED AIRTIME</div><h2 id=\"reader-title\" tabindex=\"-1\">The receiver must distinguish signal from interference</h2><p>As a radio signal travels, its power generally weakens. Other transmitters, reflections, and noise can corrupt reception. The receiver’s signal-to-interference-plus-noise ratio (SINR) helps determine whether it can decode a frame at a given data rate.</p><ol><li>Sender chooses a channel and transmits.</li><li>Distance and obstacles attenuate the signal.</li><li>Interference and noise reduce decoding margin.</li><li>Link adaptation may lower the rate or retry a frame.</li></ol><p>Wireless systems cannot reliably detect all collisions while transmitting, so Wi-Fi uses carrier sensing, acknowledgments, and backoff.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE BUG ONLY HAPPENS IN ONE ROOM</div><h2 id=\"reader-title\" tabindex=\"-1\">Separate radio conditions from application failures</h2><p>A mobile feature works beside the access point but fails in a conference room. The server logs show timeouts; the device reports retries and a weak or changing rate. The underlying issue may be coverage or interference rather than a backend regression.</p><ol><li>Compare signal quality, channel utilization, and retry rate by location.</li><li>Check whether failures align with movement or crowded airtime.</li><li>Keep client retries bounded so radio loss does not create request storms.</li><li>Measure application latency separately from radio association and retransmission time.</li></ol><p><strong>Engineering lesson:</strong> mobile networks add environmental variables. Test across realistic locations, not only on a desk.</p>","<div class=\"section-kicker\">HANDS-ON · VARY DISTANCE AND INTERFERENCE</div><h2 id=\"reader-title\" tabindex=\"-1\">Explore the wireless link budget</h2><p>Change distance and competing radio activity. This illustrative model shows the direction of the effect, not a calibrated RF prediction.</p><div class=\"network-lab\" data-wireless-lab><h3>Wireless conditions explorer</h3><div class=\"network-lab-controls\"><label>Relative distance<br><input type=\"range\" min=\"1\" max=\"10\" value=\"3\" data-radio-distance></label><label>Interference<br><input type=\"range\" min=\"0\" max=\"10\" value=\"2\" data-radio-noise></label></div><div class=\"network-diagram\" data-radio-diagram></div><p class=\"network-status\" data-radio-status aria-live=\"polite\"></p></div><p>Which changes might rate adaptation make? Which changes must the application tolerate?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · DESIGN FOR RADIO VARIATION</div><h2 id=\"reader-title\" tabindex=\"-1\">Wireless loss is part of the system model</h2><ol><li>What causes a signal to become harder to decode?</li><li>How can interference affect rate and retries?</li><li>Why can wireless senders not rely on collision detection like classic shared Ethernet?</li><li>How should an application prevent link retries from becoming a request storm?</li></ol><details><summary>Review the core ideas</summary><p>Distance, obstacles, reflections, and competing transmissions alter radio conditions. Low SINR can cause errors, lower rates, and retries. Wi-Fi coordinates access using carrier sensing, randomized backoff, and acknowledgments. Application retries still need deadlines and idempotency.</p></details><p><strong>Connect forward:</strong> Wi-Fi’s CSMA/CA process coordinates stations competing for a local wireless channel.</p>"],"module-7-2":["<div class=\"section-kicker\">WHY IT EXISTS · WI-FI MUST SHARE RADIO AIRTIME</div><h2 id=\"reader-title\" tabindex=\"-1\">How does Wi-Fi avoid talking over another station?</h2><p class=\"reader-intro\">Wi-Fi stations share a radio channel and cannot always hear every other transmitter. The MAC layer uses carrier sensing, randomized backoff, acknowledgments, and optional RTS/CTS exchanges to reduce collisions and recover from loss.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Wi-Fi contention explains why latency and throughput change as clients join, why a hidden client can cause retries, and why a server-side performance issue may actually be airtime contention.</p></div><p><strong>By the end:</strong> trace CSMA/CA, explain hidden terminals, and identify when RTS/CTS may help or add overhead.</p>","<div class=\"section-kicker\">SYSTEM MODEL · SENSE, WAIT, TRANSMIT, ACK</div><h2 id=\"reader-title\" tabindex=\"-1\">Backoff lowers the chance of repeated collisions</h2><ol><li>Station senses the channel.</li><li>If busy, wait; when clear, count down a random backoff.</li><li>Transmit when the counter reaches zero.</li><li>Receiver sends an acknowledgment; if none arrives, sender retries after a larger backoff.</li></ol><p>RTS/CTS can reserve airtime before a long data frame, reducing some hidden-terminal collisions. Its extra control frames cost airtime, so it is not always beneficial.</p><p>Wi-Fi uses collision avoidance rather than collision detection because a radio cannot reliably listen for a collision while sending.</p>","<div class=\"section-kicker\">ENGINEERING CASE · CLIENTS CANNOT HEAR EACH OTHER</div><h2 id=\"reader-title\" tabindex=\"-1\">A hidden terminal creates retries</h2><p>Two clients can both reach an access point but cannot hear one another because of walls or distance. Each senses an apparently idle channel and transmits; their frames collide at the access point.</p><ol><li>Look for retries that rise when both stations are active.</li><li>Compare channel busy time with client throughput.</li><li>Test RTS/CTS for long frames if hidden terminals are likely.</li><li>Balance collision reduction against control-frame overhead.</li></ol><p><strong>Engineering lesson:</strong> “I can hear the access point” does not mean every other client can hear me.</p>","<div class=\"section-kicker\">HANDS-ON · COMPARE WI-FI ACCESS OPTIONS</div><h2 id=\"reader-title\" tabindex=\"-1\">Model contention and reservation overhead</h2><p>Adjust the number of active clients and toggle RTS/CTS. The output illustrates the trade-off: reservation can reduce hidden-terminal collisions but adds control airtime.</p><div class=\"network-lab\" data-wifi-lab><h3>Wi-Fi airtime model</h3><div class=\"network-lab-controls\"><label>Active clients<br><input type=\"range\" min=\"2\" max=\"24\" value=\"8\" data-wifi-clients></label><label><input type=\"checkbox\" data-wifi-rts> Use RTS/CTS reservation</label></div><div class=\"network-diagram\" data-wifi-diagram></div><p class=\"network-status\" data-wifi-status aria-live=\"polite\"></p></div><p>Would reservation be worthwhile for short frames? What about a crowded room with hidden clients and large transfers?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · REASON ABOUT AIRTIME</div><h2 id=\"reader-title\" tabindex=\"-1\">A radio link is scheduled in small opportunities</h2><ol><li>Why does Wi-Fi use collision avoidance rather than collision detection?</li><li>How does randomized backoff help?</li><li>When can RTS/CTS improve delivery?</li><li>Why can RTS/CTS reduce efficiency for some workloads?</li></ol><details><summary>Review the core ideas</summary><p>Stations sense, wait, back off, transmit, and await acknowledgments. Hidden terminals may collide at the access point even when they cannot hear one another. RTS/CTS can reserve airtime but adds overhead. Throughput and latency depend on contention and packet size.</p></details><p><strong>Connect forward:</strong> compare Wi-Fi with Bluetooth and Zigbee, which target different ranges, data rates, and power budgets.</p>"],"module-7-3":["<div class=\"section-kicker\">WHY IT EXISTS · WIRELESS PROTOCOLS SERVE DIFFERENT NEEDS</div><h2 id=\"reader-title\" tabindex=\"-1\">Why are there multiple wireless standards?</h2><p class=\"reader-intro\">Wireless devices need different balances of range, throughput, energy use, cost, and topology. Wi-Fi connects high-bandwidth local clients; Bluetooth supports nearby peripherals; Zigbee targets low-power sensing and control.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Choosing a radio affects product battery life, latency, deployment density, gateway requirements, and the failure modes your application must handle.</p></div><p><strong>By the end:</strong> compare the design goals of Wi-Fi, Bluetooth, and Zigbee and map an application’s constraints to a suitable protocol family.</p>","<div class=\"section-kicker\">SYSTEM MODEL · RANGE, RATE, POWER, TOPOLOGY</div><h2 id=\"reader-title\" tabindex=\"-1\">Choose around the workload, not a single speed number</h2><ul><li><strong>Wi-Fi:</strong> local IP networking with comparatively high throughput and higher power use.</li><li><strong>Bluetooth Low Energy:</strong> short-range peripherals and sensors with low energy consumption.</li><li><strong>Zigbee:</strong> low-rate, low-power device networks that can form mesh topologies.</li></ul><p>These are broad engineering tendencies, not guarantees; actual performance depends on version, spectrum, environment, device class, and network configuration.</p><p>Also ask how devices join, authenticate, sleep, retransmit, and reach an IP application or gateway.</p>","<div class=\"section-kicker\">ENGINEERING CASE · CONNECTING A BATTERY SENSOR</div><h2 id=\"reader-title\" tabindex=\"-1\">The fastest radio may be the wrong product choice</h2><p>A battery sensor reports temperature every minute. Wi-Fi could carry the readings but may spend unnecessary energy maintaining connectivity. A low-power radio may extend battery life, provided the system has a gateway and the application tolerates lower throughput and intermittent sleep.</p><ol><li>Estimate payload size and reporting frequency.</li><li>Set a battery-life and range target.</li><li>Choose a radio and topology that fit the deployment.</li><li>Design gateway buffering and reconnect behavior for sleeping devices.</li></ol><p><strong>Engineering lesson:</strong> choose the link around system constraints—energy, latency, data volume, range, and infrastructure—not protocol familiarity.</p>","<div class=\"section-kicker\">HANDS-ON · MATCH A RADIO TO A USE CASE</div><h2 id=\"reader-title\" tabindex=\"-1\">Compare the protocol trade-offs</h2><p>Select a radio family and inspect where it tends to fit. Use the result as a starting point; verify actual device and environment specifications before shipping.</p><div class=\"network-lab\" data-radio-choice-lab><h3>Wireless technology chooser</h3><div class=\"network-lab-controls\"><button type=\"button\" data-radio-choice=\"wifi\" aria-pressed=\"true\">Wi-Fi</button><button type=\"button\" data-radio-choice=\"ble\" aria-pressed=\"false\">Bluetooth LE</button><button type=\"button\" data-radio-choice=\"zigbee\" aria-pressed=\"false\">Zigbee</button></div><table class=\"network-table\"><thead><tr><th>Design factor</th><th data-radio-factor></th></tr></thead><tbody><tr><td>Typical fit</td><td data-radio-fit></td></tr><tr><td>Trade-off</td><td data-radio-trade></td></tr><tr><td>System question</td><td data-radio-question></td></tr></tbody></table><p class=\"network-status\" data-radio-status aria-live=\"polite\"></p></div><p>Which non-network requirement—battery, deployment topology, or data rate—drives your choice?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · STATE THE TRADE-OFF</div><h2 id=\"reader-title\" tabindex=\"-1\">Wireless design is an application architecture decision</h2><ol><li>Which radio family fits high local throughput?</li><li>Why might a low-power radio need a gateway?</li><li>What does a mesh topology change?</li><li>Which workload metrics should you estimate before selecting a standard?</li></ol><details><summary>Review the core ideas</summary><p>Wi-Fi often favors throughput and IP connectivity; Bluetooth LE often favors nearby low-power devices; Zigbee often favors low-rate, low-power mesh sensing and control. Device version, range, energy, topology, and environment all matter.</p></details><p><strong>Connect forward:</strong> cellular systems maintain connectivity as a device moves between access points and cells.</p>"],"module-7-4":["<div class=\"section-kicker\">WHY IT EXISTS · USERS MOVE WHILE SESSIONS CONTINUE</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a phone change cells without ending a session?</h2><p class=\"reader-intro\">A mobile device moves through coverage areas while applications expect a continuous connection. Cellular networks measure radio conditions, prepare a target cell, transfer the device’s connection, and update forwarding so traffic follows it.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Mobility explains short pauses, changing IP paths, reconnects, variable latency, and why a long-lived application session can break during a commute even when the app itself has not changed.</p></div><p><strong>By the end:</strong> describe handoff stages, distinguish radio handoff from application session continuity, and design clients for temporary path changes.</p>","<div class=\"section-kicker\">SYSTEM MODEL · MEASURE, PREPARE, HAND OFF</div><h2 id=\"reader-title\" tabindex=\"-1\">The network coordinates a moving endpoint</h2><ol><li>Device and network measure signal quality and neighboring cells.</li><li>Source cell decides that a handoff is useful.</li><li>Target cell reserves radio and network resources.</li><li>Device switches, then the core updates the path to the new cell.</li></ol><p>Hard and soft handoff behaviors vary across cellular generations and architectures. Application transports may see delay, loss, address changes, or a temporary disconnect during mobility.</p><p>Session continuity can involve buffering, retransmission, and application-level reconnect logic above the radio handoff.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A REQUEST TIMES OUT IN A TRAIN</div><h2 id=\"reader-title\" tabindex=\"-1\">A successful handoff does not preserve every request</h2><p>A mobile client begins a request in one cell and moves into another. The radio handoff succeeds, but the transport may pause or lose packets; a request can time out after the server has already performed its work.</p><ol><li>Use bounded request deadlines and reconnect with backoff.</li><li>Make side-effecting operations idempotent.</li><li>Persist resumable progress for uploads or long streams.</li><li>Instrument radio changes separately from server and application errors.</li></ol><p><strong>Engineering lesson:</strong> the network can preserve reachability without guaranteeing a seamless application session. Design for brief interruptions and uncertain outcomes.</p>","<div class=\"section-kicker\">HANDS-ON · STEP THROUGH A CELL HANDOFF</div><h2 id=\"reader-title\" tabindex=\"-1\">Watch the route move with the device</h2><p>Advance a device from Cell A to Cell B. Observe when the target resources are ready and when the core forwarding path changes.</p><div class=\"network-lab\" data-handoff-lab><h3>Mobility handoff</h3><div class=\"network-diagram\"><div class=\"network-node\" data-cell=\"a\">Cell A<small>serving</small></div><span class=\"network-arrow\">→</span><div class=\"network-node\" data-cell=\"b\">Cell B<small>target</small></div></div><ol class=\"router-pipeline\"><li data-ho-step=\"0\" class=\"is-active\"><b>1 · Measure</b>Signal changes</li><li data-ho-step=\"1\"><b>2 · Prepare</b>Reserve target</li><li data-ho-step=\"2\"><b>3 · Switch</b>Device moves</li><li data-ho-step=\"3\"><b>4 · Update</b>Traffic rerouted</li></ol><div class=\"network-lab-controls\"><button type=\"button\" data-ho-next>Advance handoff →</button><button type=\"button\" data-ho-reset>Reset</button></div><p class=\"network-status\" data-ho-status aria-live=\"polite\"></p></div><p>At what point should the application consider reconnecting? What telemetry distinguishes a handoff pause from a server delay?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · KEEP THE SESSION RESILIENT</div><h2 id=\"reader-title\" tabindex=\"-1\">Mobility changes the path; the app still owns its contract</h2><ol><li>What signals can trigger a handoff?</li><li>Why prepare resources in the target cell before switching?</li><li>Can a successful radio handoff guarantee an application request completed?</li><li>How do idempotency and resumable transfers help mobile clients?</li></ol><details><summary>Review the core ideas</summary><p>Handoffs measure radio quality, prepare target resources, move the device, then update the network path. Temporary delay or loss can still affect transport and applications. Deadlines, retries with backoff, idempotency, and resumable work help applications tolerate mobility.</p></details><p><strong>Chapter recap:</strong> wireless links contend and vary; radio families make different power and range trade-offs; cellular networks coordinate handoffs to keep devices connected.</p>"]};
  if(chapterSeven[id])return chapterSeven[id];
  const chapterEight={"module-8-1":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORKS CARRY TRUSTED AND UNTRUSTED INPUT</div><h2 id=\"reader-title\" tabindex=\"-1\">What security properties should a networked feature preserve?</h2><p class=\"reader-intro\">Network security begins with the assets a system must protect and the threats that could harm them. Confidentiality limits who can read data; integrity detects unauthorized changes; availability keeps services usable.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Every endpoint, token, dependency, and network boundary changes the risk of a product. Engineers make security decisions in API design, authentication, logging, deployment, and failure handling—not only in a security team.</p></div><p><strong>By the end:</strong> identify assets and trust boundaries, map threats to security properties, and prioritize mitigations based on impact and likelihood.</p>","<div class=\"section-kicker\">SYSTEM MODEL · ASSETS, THREATS, CONTROLS</div><h2 id=\"reader-title\" tabindex=\"-1\">Security starts with a threat model</h2><ol><li>List valuable assets: credentials, personal data, code, service availability.</li><li>Draw trust boundaries and data flows.</li><li>Ask who can attack each boundary and what they could do.</li><li>Choose controls that reduce a specific risk and verify them.</li></ol><p>Controls can prevent, detect, or limit damage. Encryption can protect confidentiality in transit; authorization can limit actions; monitoring can reveal abuse; backups support recovery.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A PUBLIC API LEAKS CUSTOMER DATA</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the boundary where access was too broad</h2><p>A public endpoint returns more fields than its UI needs. A client-side screen hides sensitive data, but the API response still exposes it. The trust boundary is the server response, so authorization and data minimization must happen there.</p><ol><li>Identify which data is sensitive and who should access it.</li><li>Check server-side authorization for each object and action.</li><li>Return only fields required by the caller’s task.</li><li>Log access decisions without storing secrets or full sensitive payloads.</li></ol><p><strong>Engineering lesson:</strong> security properties are enforced at the boundary that owns the data, not by hiding it in a client.</p>","<div class=\"section-kicker\">HANDS-ON · MAP A THREAT TO A CONTROL</div><h2 id=\"reader-title\" tabindex=\"-1\">Which security property is at risk?</h2><p>Choose a scenario. The model identifies the primary property at risk and a practical first control.</p><div class=\"network-lab\" data-threat-lab><h3>Threat-model starter</h3><div class=\"network-lab-controls\"><button type=\"button\" data-threat=\"read\" aria-pressed=\"true\">Stolen session reads records</button><button type=\"button\" data-threat=\"alter\" aria-pressed=\"false\">Proxy alters a request</button><button type=\"button\" data-threat=\"flood\" aria-pressed=\"false\">Traffic flood exhausts API</button></div><div class=\"network-diagram\" data-threat-flow></div><p class=\"network-status\" data-threat-status aria-live=\"polite\"></p></div><p>Write the asset, trust boundary, attacker capability, and one control that reduces the risk.</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · SECURITY IS A SYSTEM PROPERTY</div><h2 id=\"reader-title\" tabindex=\"-1\">Turn risks into engineering requirements</h2><ol><li>What do confidentiality, integrity, and availability protect?</li><li>Why is a hidden UI field not an authorization control?</li><li>How do prevention, detection, and recovery controls differ?</li><li>What makes a threat model actionable?</li></ol><details><summary>Review the core ideas</summary><p>Identify assets, boundaries, threats, and attacker capabilities. Map them to confidentiality, integrity, or availability, then choose verifiable controls at the system boundary that owns the risk.</p></details><p><strong>Connect forward:</strong> cryptography supplies tools for confidentiality and integrity, but the protocol must apply them correctly.</p>"],"module-8-2":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORKS CANNOT ASSUME A TRUSTED PATH</div><h2 id=\"reader-title\" tabindex=\"-1\">How can two endpoints protect messages in transit?</h2><p class=\"reader-intro\">Packets may cross networks and devices the application team does not control. Cryptography lets endpoints protect data against eavesdropping and tampering, even when intermediate routers simply forward ciphertext.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Developers choose TLS libraries, manage keys and certificates, protect secrets at rest, and decide whether integrity-only or confidentiality protection is needed. Misusing cryptographic primitives can undo the guarantees they are meant to provide.</p></div><p><strong>By the end:</strong> distinguish encryption, hashing, and message authentication; compare symmetric and public-key cryptography; and use established protocol libraries.</p>","<div class=\"section-kicker\">SYSTEM MODEL · MATCH THE PRIMITIVE TO THE GOAL</div><h2 id=\"reader-title\" tabindex=\"-1\">Encryption hides; hashes summarize; MACs authenticate</h2><ul><li><strong>Symmetric encryption:</strong> the same secret key encrypts and decrypts efficiently.</li><li><strong>Public-key cryptography:</strong> a key pair supports operations such as key agreement or signatures.</li><li><strong>Cryptographic hash:</strong> maps data to a fixed-size digest; alone, it does not prove who created the data.</li><li><strong>MAC:</strong> uses a shared secret to authenticate message integrity.</li></ul><p>Modern TLS combines authenticated key exchange and symmetric authenticated encryption. Use vetted libraries and protocols; do not invent algorithms or store keys in source code.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A CHECKSUM IS NOT AN AUTHENTICATOR</div><h2 id=\"reader-title\" tabindex=\"-1\">An attacker replaces data and recomputes the digest</h2><p>An application stores a payload and an unkeyed hash. The hash can detect accidental corruption, but an attacker who can replace both payload and hash can create a matching pair. A keyed MAC or digital signature is needed to authenticate origin and integrity.</p><ol><li>Define whether the threat is accidental error or malicious modification.</li><li>Use a MAC for shared-secret authentication or a signature for public verification.</li><li>Use authenticated encryption when confidentiality and integrity are both required.</li><li>Protect keys and rotate them through a managed process.</li></ol><p><strong>Engineering lesson:</strong> select primitives from the threat model, not from a word such as “hash” or “encrypt.”</p>","<div class=\"section-kicker\">HANDS-ON · CHOOSE THE RIGHT CRYPTO OPERATION</div><h2 id=\"reader-title\" tabindex=\"-1\">Match the goal to the primitive</h2><p>Select what the system needs. The explorer shows a suitable primitive and one common mistake.</p><div class=\"network-lab\" data-crypto-lab><h3>Cryptography decision guide</h3><div class=\"network-lab-controls\"><button type=\"button\" data-crypto-goal=\"hide\" aria-pressed=\"true\">Hide a message</button><button type=\"button\" data-crypto-goal=\"verify\" aria-pressed=\"false\">Detect tampering</button><button type=\"button\" data-crypto-goal=\"origin\" aria-pressed=\"false\">Prove who signed it</button></div><div class=\"network-diagram\" data-crypto-diagram></div><p class=\"network-status\" data-crypto-status aria-live=\"polite\"></p></div><p>Why does an unkeyed hash not prove who produced a message?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · STATE THE GUARANTEE</div><h2 id=\"reader-title\" tabindex=\"-1\">Use cryptography without inventing a protocol</h2><ol><li>What does symmetric encryption require both endpoints to share?</li><li>What does a hash alone not authenticate?</li><li>When would a MAC or digital signature be appropriate?</li><li>Why use a vetted TLS and cryptography library?</li></ol><details><summary>Review the core ideas</summary><p>Encryption protects confidentiality. Hashes detect changes only when the expected digest is trusted. MACs authenticate integrity with a shared secret. Signatures enable verification with a public key. Authenticated encryption combines confidentiality and integrity. Key management and correct protocol use are essential.</p></details><p><strong>Connect forward:</strong> signatures and certificates help a receiver authenticate who controls a public key.</p>"],"module-8-3":["<div class=\"section-kicker\">WHY IT EXISTS · A PUBLIC KEY NEEDS A TRUSTED IDENTITY</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a client know which key belongs to a server?</h2><p class=\"reader-intro\">A public key can verify a signature, but the client still needs confidence that the key belongs to the intended service. Digital signatures and certificate authorities bind identities to public keys through a verifiable chain.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Certificate validation, token signing, package verification, and key rotation depend on understanding what a signature proves—and what it does not prove.</p></div><p><strong>By the end:</strong> trace signing and verification, explain certificate chains, and avoid confusing encryption with authentication.</p>","<div class=\"section-kicker\">SYSTEM MODEL · SIGN WITH PRIVATE KEY, VERIFY WITH PUBLIC KEY</div><h2 id=\"reader-title\" tabindex=\"-1\">A signature binds a key to specific bytes</h2><ol><li>Signer computes a digest of the message.</li><li>Signer uses a private key to create a signature over that digest.</li><li>Verifier computes the digest independently and checks the signature using the public key.</li><li>Verifier trusts identity only if the public key is itself bound to that identity through a trusted certificate or key-distribution process.</li></ol><p>A signature supports integrity and origin authentication for a key. It does not hide the message. A certificate chain connects a leaf certificate to a trusted root, subject to name, time, and policy checks.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A PACKAGE SIGNATURE FAILS</div><h2 id=\"reader-title\" tabindex=\"-1\">Do not skip verification to make the build pass</h2><p>A build pipeline fails to verify a downloaded package signature after a key rotation. Disabling verification restores the build but also removes the evidence that the artifact came from an approved publisher.</p><ol><li>Confirm the expected signer and published key-rotation guidance.</li><li>Verify certificate validity and chain trust.</li><li>Check the exact artifact digest and signature metadata.</li><li>Update trusted keys through a reviewed mechanism; preserve verification.</li></ol><p><strong>Engineering lesson:</strong> signature failures are identity and integrity signals, not cosmetic warnings to suppress.</p>","<div class=\"section-kicker\">HANDS-ON · TAMPER WITH A SIGNED MESSAGE</div><h2 id=\"reader-title\" tabindex=\"-1\">See which changes verification detects</h2><p>Generate a conceptual signature for a message. Change the message and observe that verification fails. The exercise models the guarantee; real signatures use vetted cryptographic libraries.</p><div class=\"network-lab\" data-sign-lab><h3>Signature verification</h3><div class=\"network-lab-controls\"><label>Message<br><input data-sign-message value=\"release=1.4.2\"></label><button type=\"button\" data-sign-tamper>Change signed content</button><button type=\"button\" data-sign-reset>Restore original</button></div><div class=\"network-diagram\" data-sign-diagram></div><p class=\"network-status\" data-sign-status aria-live=\"polite\"></p></div><p>Why would encrypting the message be a different goal from signing it?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · SEPARATE KEY PROOF FROM IDENTITY TRUST</div><h2 id=\"reader-title\" tabindex=\"-1\">Check the chain behind the signature</h2><ol><li>What does a valid signature establish about the signed bytes?</li><li>Why is a public key alone not enough to identify a website?</li><li>What does a certificate authority contribute?</li><li>Why should a build fail closed when signature verification fails?</li></ol><details><summary>Review the core ideas</summary><p>A valid signature shows the bytes match a signature made by the corresponding private key. A certificate or other trust mechanism binds that public key to an identity. Verification must include certificate and policy checks; signatures provide integrity and authenticity, not secrecy.</p></details><p><strong>Connect forward:</strong> TLS uses certificate validation and a handshake to authenticate network endpoints and establish session keys.</p>"],"module-8-4":["<div class=\"section-kicker\">WHY IT EXISTS · ENCRYPTION NEEDS THE RIGHT ENDPOINT</div><h2 id=\"reader-title\" tabindex=\"-1\">How does a client authenticate the server it contacted?</h2><p class=\"reader-intro\">A secure channel is useful only if the client knows it is connected to the intended endpoint. TLS authenticates a server certificate, negotiates fresh traffic keys, and protects application bytes in transit.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Correct certificate validation prevents man-in-the-middle attacks. Mutual TLS can authenticate clients as well as servers for service-to-service communication.</p></div><p><strong>By the end:</strong> trace a simplified TLS handshake, explain hostname and certificate validation, and identify when mutual TLS is appropriate.</p>","<div class=\"section-kicker\">SYSTEM MODEL · AUTHENTICATE, AGREE, PROTECT</div><h2 id=\"reader-title\" tabindex=\"-1\">The handshake builds a secure session</h2><ol><li>Client and server negotiate supported TLS parameters.</li><li>Server presents a certificate for its identity.</li><li>Client validates the certificate chain, validity, and requested hostname.</li><li>Handshake establishes shared session keys; subsequent records are encrypted and integrity-protected.</li></ol><p>Mutual TLS adds client-certificate authentication. TLS protects a channel; application authorization still decides what an authenticated identity may do.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE CERTIFICATE CHECK WAS DISABLED</div><h2 id=\"reader-title\" tabindex=\"-1\">A quick workaround removes endpoint identity</h2><p>An internal service has a certificate mismatch, so a developer disables certificate validation. The request now “works,” but a proxy or attacker could impersonate the service without detection.</p><ol><li>Check the requested hostname against certificate subject alternative names.</li><li>Verify the trust chain and expiration.</li><li>Fix service discovery or certificate issuance; do not ignore validation.</li><li>Use mutual TLS when both service identities need cryptographic authentication.</li></ol><p><strong>Engineering lesson:</strong> encryption without endpoint authentication can create a private channel to the wrong party.</p>","<div class=\"section-kicker\">HANDS-ON · STEP THROUGH TLS AUTHENTICATION</div><h2 id=\"reader-title\" tabindex=\"-1\">Find where identity is checked</h2><p>Advance through a simplified server-authenticated TLS setup. Toggle client-certificate requirements to see when mutual authentication is added.</p><div class=\"network-lab\" data-tls-lab><h3>TLS handshake model</h3><label><input type=\"checkbox\" data-tls-mtls> Require client certificate (mutual TLS)</label><ol class=\"router-pipeline\"><li data-tls-step=\"0\" class=\"is-active\"><b>1 · Client hello</b>Capabilities</li><li data-tls-step=\"1\"><b>2 · Certificate</b>Server identity</li><li data-tls-step=\"2\"><b>3 · Validate</b>Name and trust</li><li data-tls-step=\"3\"><b>4 · Session keys</b>Protected channel</li></ol><div class=\"network-lab-controls\"><button type=\"button\" data-tls-next>Advance handshake →</button><button type=\"button\" data-tls-reset>Reset</button></div><p class=\"network-status\" data-tls-status aria-live=\"polite\"></p></div><p>Which checks must succeed before sending credentials or sensitive application data?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · KEEP TRANSPORT SECURITY AND AUTHORIZATION DISTINCT</div><h2 id=\"reader-title\" tabindex=\"-1\">A secure channel is not permission to every action</h2><ol><li>What does a server certificate help the client authenticate?</li><li>Why verify the hostname as well as the certificate chain?</li><li>What extra identity does mutual TLS establish?</li><li>Why does TLS not replace application authorization?</li></ol><details><summary>Review the core ideas</summary><p>TLS authenticates endpoints according to certificate and trust policy, negotiates keys, then protects records. Mutual TLS authenticates the client certificate too. The application still needs authorization checks for each action and resource.</p></details><p><strong>Connect forward:</strong> combine endpoint authentication with network controls and monitoring in applied security designs.</p>"],"module-8-5":["<div class=\"section-kicker\">WHY IT EXISTS · SECURITY REQUIRES LAYERS</div><h2 id=\"reader-title\" tabindex=\"-1\">How do network defenses work together?</h2><p class=\"reader-intro\">No single control stops every attack. Secure systems combine endpoint authentication, encryption, least-privilege access, network segmentation, secure name resolution, logging, and recovery plans.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Applied network security is part of ordinary product engineering: protect API boundaries, avoid leaking credentials, validate dependencies, rate-limit abuse, and make security events observable.</p></div><p><strong>By the end:</strong> map common network controls to threats, layer protections without confusing their roles, and design safe failure and incident response.</p>","<div class=\"section-kicker\">SYSTEM MODEL · PREVENT, DETECT, CONTAIN, RECOVER</div><h2 id=\"reader-title\" tabindex=\"-1\">Defense in depth covers different failure modes</h2><ol><li><strong>Prevent:</strong> TLS, strong authentication, authorization, input validation, and secure defaults.</li><li><strong>Detect:</strong> audit logs, anomaly monitoring, intrusion detection, and alerting.</li><li><strong>Contain:</strong> segmentation, rate limits, revocable credentials, and limited blast radius.</li><li><strong>Recover:</strong> backups, key rotation, incident playbooks, and tested restoration.</li></ol><p>Firewalls filter traffic according to policy; VPNs create protected tunnels; DNSSEC authenticates DNS data but does not encrypt queries. Each control has a scoped guarantee.</p>","<div class=\"section-kicker\">ENGINEERING CASE · A CREDENTIAL LEAK BECOMES AN INCIDENT</div><h2 id=\"reader-title\" tabindex=\"-1\">Contain the impact before rotating everything blindly</h2><p>An API token is accidentally committed to a public repository. The immediate risk is unauthorized use; changing the token is necessary, but a complete response also checks logs, scopes, downstream access, and whether other secrets were exposed.</p><ol><li>Revoke the exposed credential and issue a replacement through a secret manager.</li><li>Review audit logs for access during the exposure window.</li><li>Limit the token’s scope and rotate dependent credentials if needed.</li><li>Add secret scanning and a tested incident response path.</li></ol><p><strong>Engineering lesson:</strong> prevention matters, but containment and detection determine how much damage an exposure causes.</p>","<div class=\"section-kicker\">HANDS-ON · BUILD A DEFENSE PATH</div><h2 id=\"reader-title\" tabindex=\"-1\">Select a threat and trace layered controls</h2><p>Choose the primary threat. The diagram shows controls at more than one boundary and the evidence an engineering team should collect.</p><div class=\"network-lab\" data-defense-lab><h3>Applied security path</h3><div class=\"network-lab-controls\"><button type=\"button\" data-defense=\"intercept\" aria-pressed=\"true\">Traffic interception</button><button type=\"button\" data-defense=\"abuse\" aria-pressed=\"false\">Credential abuse</button><button type=\"button\" data-defense=\"flood\" aria-pressed=\"false\">Traffic flood</button></div><div class=\"network-diagram\" data-defense-diagram></div><p class=\"network-status\" data-defense-status aria-live=\"polite\"></p></div><p>Which control prevents the attack, which detects it, and how would you limit the blast radius?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · EXPLAIN EACH CONTROL’S SCOPE</div><h2 id=\"reader-title\" tabindex=\"-1\">Secure the path without assuming one control is enough</h2><ol><li>What does TLS protect, and what does it not authorize?</li><li>How do segmentation and rate limiting contain different risks?</li><li>What security property does DNSSEC provide?</li><li>Why must incident response include evidence and recovery?</li></ol><details><summary>Review the core ideas</summary><p>Defense in depth layers prevention, detection, containment, and recovery. TLS protects channel confidentiality and integrity and authenticates endpoints; firewalls and segmentation shape access; monitoring detects unusual use; tested recovery limits impact.</p></details><p><strong>Chapter recap:</strong> threat models define the goal, cryptographic protocols protect messages and identities, and layered controls reduce risk across the whole system.</p>"]};
  if(chapterEight[id])return chapterEight[id];
  const chapterNine={"module-9-1":["<div class=\"section-kicker\">WHY IT EXISTS · MEDIA HAS TIMING AND RATE CONSTRAINTS</div><h2 id=\"reader-title\" tabindex=\"-1\">Why is audio/video networking different from a file download?</h2><p class=\"reader-intro\">A file can often arrive late and still be useful. A live voice packet that arrives after its playback deadline may be worthless. Multimedia applications trade compression, buffering, quality, and responsiveness under changing network conditions.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Real-time media makes network delay, jitter, loss, and bandwidth visible to users. Developers need to set budgets across capture, encoding, network, buffering, and playback rather than treating the network as a transparent pipe.</p></div><p><strong>By the end:</strong> describe media rate and delay requirements, distinguish loss tolerance from reliability, and reason about the end-to-end playout budget.</p>","<div class=\"section-kicker\">SYSTEM MODEL · COMPRESS, PACKETIZE, PLAY</div><h2 id=\"reader-title\" tabindex=\"-1\">Media quality is an end-to-end pipeline</h2><ol><li>Capture audio or video frames.</li><li>Encode them into a representation at a chosen rate.</li><li>Packetize and send over a variable network path.</li><li>Buffer enough to smooth jitter, then decode at the playback deadline.</li></ol><p>Compression reduces bandwidth but can add computation or quality loss. Buffering smooths delay variation but increases end-to-end latency. Real-time media often conceals or skips late loss instead of retransmitting data that misses its deadline.</p>","<div class=\"section-kicker\">ENGINEERING CASE · THE CALL SOUNDS CLEAR BUT FEELS LAGGY</div><h2 id=\"reader-title\" tabindex=\"-1\">Latency can be the main quality failure</h2><p>A video call has few dropped packets and high audio clarity, but participants keep talking over one another. The network and playback buffers add enough delay to make conversation unnatural.</p><ol><li>Measure one-way or round-trip latency and jitter.</li><li>Break the delay budget into capture, encode, network, buffer, and decode time.</li><li>Reduce buffering carefully; too little causes audible gaps.</li><li>Use adaptation and concealment based on deadlines, not retries alone.</li></ol><p><strong>Engineering lesson:</strong> media quality is multi-dimensional. Low packet loss does not guarantee a good real-time experience.</p>","<div class=\"section-kicker\">HANDS-ON · SET A MEDIA DELAY BUDGET</div><h2 id=\"reader-title\" tabindex=\"-1\">See how buffering trades smoothness for responsiveness</h2><p>Adjust path jitter and playout buffer. The model shows whether the selected buffer can absorb variation and how much latency it adds.</p><div class=\"network-lab\" data-media-lab><h3>Playout budget explorer</h3><div class=\"network-lab-controls\"><label>Network jitter<br><input type=\"range\" min=\"10\" max=\"250\" value=\"80\" data-media-jitter></label><label>Playout buffer<br><input type=\"range\" min=\"20\" max=\"300\" value=\"100\" data-media-buffer></label></div><div class=\"network-diagram\" data-media-diagram></div><p class=\"network-status\" data-media-status aria-live=\"polite\"></p></div><p>What happens when the buffer is smaller than jitter? What user-visible cost appears when you increase it?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · DESIGN A PLAYBACK DEADLINE</div><h2 id=\"reader-title\" tabindex=\"-1\">Optimize for the user’s timing requirement</h2><ol><li>Why might a late retransmission be less useful than concealment?</li><li>What does a larger playout buffer improve?</li><li>What user cost does that buffer add?</li><li>Which metrics separate delay, jitter, and loss?</li></ol><details><summary>Review the core ideas</summary><p>Multimedia encodes and packetizes media, then buffers and plays to deadlines. Larger buffers absorb more jitter but add latency. Real-time apps may conceal or skip late loss; reliable file transfer has different goals.</p></details><p><strong>Connect forward:</strong> adaptive streaming selects video segments at bitrates that fit current throughput and buffer state.</p>"],"module-9-2":["<div class=\"section-kicker\">WHY IT EXISTS · VIDEO DEMAND CHANGES OVER TIME</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a video stream keep playing as bandwidth changes?</h2><p class=\"reader-intro\">A viewer’s available throughput can rise and fall while a video is playing. Adaptive bitrate streaming divides media into segments encoded at several quality levels; the player chooses each next segment based on measured delivery rate and buffer health.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Streaming design balances startup time, resolution, rebuffering, CDN load, and bandwidth cost. A player that chooses bitrate poorly can make a fast network appear broken or waste available capacity.</p></div><p><strong>By the end:</strong> explain segmentation and bitrate ladders, reason about buffer-based adaptation, and identify why throughput estimates can be noisy.</p>","<div class=\"section-kicker\">SYSTEM MODEL · MANIFEST, SEGMENTS, ADAPTATION</div><h2 id=\"reader-title\" tabindex=\"-1\">The player controls each next request</h2><ol><li>Manifest describes available representations and segment URLs.</li><li>Player requests a short segment at one chosen bitrate.</li><li>Measured throughput and buffer occupancy update the next choice.</li><li>CDN cache serves the segment; player decodes and appends it to the buffer.</li></ol><p>Short segments adapt quickly but create more request overhead. A throughput-only rule can oscillate; buffer-aware logic helps avoid rebuffering and overly aggressive upgrades.</p>","<div class=\"section-kicker\">ENGINEERING CASE · RESOLUTION OSCILLATES</div><h2 id=\"reader-title\" tabindex=\"-1\">A noisy estimate makes the player switch too often</h2><p>A player upgrades quality after one fast segment, then runs out of buffer when the next segment is slow. It repeatedly switches between high and low resolution, distracting the viewer.</p><ol><li>Measure segment download time and buffer occupancy together.</li><li>Keep a safety margin below estimated throughput.</li><li>Use hysteresis or smoothing to avoid rapid quality oscillation.</li><li>Track rebuffer events and startup time by device and network class.</li></ol><p><strong>Engineering lesson:</strong> adaptation is a control problem under uncertainty. A little unused bandwidth can be safer than a quality level the path cannot sustain.</p>","<div class=\"section-kicker\">HANDS-ON · ADAPT TO AVAILABLE THROUGHPUT</div><h2 id=\"reader-title\" tabindex=\"-1\">See which representation fits the link</h2><p>Adjust available throughput and buffer. The player chooses the highest representation below a conservative share of measured capacity.</p><div class=\"network-lab\" data-stream-lab><h3>Adaptive bitrate player</h3><div class=\"network-lab-controls\"><label>Available throughput (Mbps)<br><input type=\"range\" min=\"1\" max=\"20\" value=\"8\" data-stream-rate></label><label>Buffered video (seconds)<br><input type=\"range\" min=\"0\" max=\"30\" value=\"12\" data-stream-buffer></label></div><div class=\"network-diagram\" data-stream-diagram></div><p class=\"network-status\" data-stream-status aria-live=\"polite\"></p></div><p>What should the player do when buffer is low even though one segment downloaded quickly?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · STABILIZE QUALITY UNDER UNCERTAINTY</div><h2 id=\"reader-title\" tabindex=\"-1\">Quality selection is a feedback loop</h2><ol><li>What does a manifest tell the player?</li><li>Why divide a video into segments?</li><li>Why should bitrate stay below the most recent throughput sample?</li><li>How does buffer occupancy affect a quality decision?</li></ol><details><summary>Review the core ideas</summary><p>Adaptive streaming uses a manifest and multiple encoded representations. The player requests segments and chooses the next bitrate from throughput and buffer state. Conservative estimates and hysteresis reduce rebuffering and quality oscillation.</p></details><p><strong>Connect forward:</strong> voice and interactive media have tighter deadlines, so buffering and retransmission trade-offs are different.</p>"],"module-9-3":["<div class=\"section-kicker\">WHY IT EXISTS · VOICE MUST ARRIVE BEFORE PLAYBACK</div><h2 id=\"reader-title\" tabindex=\"-1\">Why does a voice call skip late packets?</h2><p class=\"reader-intro\">Interactive audio has strict playout deadlines. Retransmitting a missing packet may deliver it after the listener already needed it; a short gap or concealment can be less disruptive than adding another round trip.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Voice and real-time applications require explicit latency and jitter budgets. The right choice depends on whether the data remains useful after delay, not just whether packets can be recovered.</p></div><p><strong>By the end:</strong> explain packetization and jitter buffers, compare concealment with retransmission, and identify how packet size affects overhead and delay.</p>","<div class=\"section-kicker\">SYSTEM MODEL · FRAME, PACKETIZE, BUFFER, DECODE</div><h2 id=\"reader-title\" tabindex=\"-1\">A jitter buffer trades delay for smooth playback</h2><p>Audio samples are grouped into packets. Short packetization reduces waiting before send but increases header overhead; larger packets use bandwidth more efficiently but add delay. A jitter buffer reorders and delays packets to play them at steady intervals.</p><ol><li>Capture and encode a short audio frame.</li><li>Transmit packets with timing information.</li><li>Reorder arrivals and buffer within a playout deadline.</li><li>Decode on time; conceal or skip missing late packets.</li></ol><p>Congestion control and adaptive bitrate help reduce persistent overload; blindly retransmitting every late frame can worsen congestion.</p>","<div class=\"section-kicker\">ENGINEERING CASE · RELIABLE DELIVERY MAKES THE CALL WORSE</div><h2 id=\"reader-title\" tabindex=\"-1\">An old packet arrives after the conversation moved on</h2><p>A real-time app retransmits every lost voice packet. The retry consumes airtime and arrives late, while newer packets wait behind it. The user hears pauses and lag even though transport eventually delivers more bytes.</p><ol><li>Classify whether each message is deadline-sensitive or durable.</li><li>Use bounded playout and concealment for stale audio.</li><li>Apply congestion control rather than adding retries under overload.</li><li>Preserve reliability for signaling and state changes that remain important later.</li></ol><p><strong>Engineering lesson:</strong> “reliable” means delivering the right thing at the right time for the application, not retransmitting every packet regardless of usefulness.</p>","<div class=\"section-kicker\">HANDS-ON · TUNE THE JITTER BUFFER</div><h2 id=\"reader-title\" tabindex=\"-1\">Find the balance between gaps and conversational delay</h2><p>Adjust measured jitter and buffer depth. A buffer below jitter risks late frames; a larger buffer smooths playback at the cost of conversational latency.</p><div class=\"network-lab\" data-voice-lab><h3>Real-time audio buffer</h3><div class=\"network-lab-controls\"><label>Observed jitter (ms)<br><input type=\"range\" min=\"10\" max=\"250\" value=\"60\" data-voice-jitter></label><label>Buffer depth (ms)<br><input type=\"range\" min=\"20\" max=\"300\" value=\"80\" data-voice-buffer></label></div><p class=\"network-status\" data-voice-status aria-live=\"polite\"></p></div><p>Would you increase buffering for a live call? What about a recorded stream?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · MATCH RECOVERY TO DEADLINES</div><h2 id=\"reader-title\" tabindex=\"-1\">Not every packet deserves the same retry policy</h2><ol><li>Why does packetization size change delay and overhead?</li><li>How does a jitter buffer smooth arrivals?</li><li>When is concealment better than retransmission?</li><li>Which real-time packets still need reliable handling?</li></ol><details><summary>Review the core ideas</summary><p>Voice frames have playout deadlines. Jitter buffers smooth timing but add latency. Late audio may be concealed or skipped; signaling and durable state may still need reliable delivery. The application’s timing contract determines recovery behavior.</p></details><p><strong>Connect forward:</strong> RTP carries real-time media timing information, while SIP can set up and manage sessions.</p>"],"module-9-4":["<div class=\"section-kicker\">WHY IT EXISTS · MEDIA AND CALL CONTROL ARE DIFFERENT</div><h2 id=\"reader-title\" tabindex=\"-1\">How does a call establish a media path?</h2><p class=\"reader-intro\">A voice or video session needs signaling to locate peers and negotiate a session, plus a media transport to carry time-sensitive packets. SIP is commonly used for session signaling; RTP carries media with sequence and timing metadata.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>Separating control from media helps diagnose call setup failures versus choppy audio. It also exposes NAT traversal, codec negotiation, and the need for secure signaling and media.</p></div><p><strong>By the end:</strong> distinguish SIP signaling from RTP media, read a simplified call flow, and explain how NAT traversal affects connectivity.</p>","<div class=\"section-kicker\">SYSTEM MODEL · SIGNAL FIRST, MEDIA AFTER</div><h2 id=\"reader-title\" tabindex=\"-1\">SIP coordinates; RTP transports timed media</h2><ol><li>Caller resolves the destination and sends a SIP invitation.</li><li>Peers or a server negotiate codecs and media parameters.</li><li>ICE/STUN/TURN techniques help establish a reachable path through NATs and firewalls.</li><li>RTP packets carry audio/video with sequence numbers and timestamps.</li><li>Signaling ends or changes the session independently of media packet delivery.</li></ol><p>RTP provides timing and sequencing context but does not itself guarantee delivery or encrypt media. Secure deployments use appropriate signaling and media protection.</p>","<div class=\"section-kicker\">ENGINEERING CASE · CALL CONNECTS, BUT NO AUDIO FLOWS</div><h2 id=\"reader-title\" tabindex=\"-1\">Control signaling succeeded; the media path did not</h2><p>Two users see a connected call, but one hears no audio. SIP signaling established session state, yet RTP packets may be blocked by NAT or firewall policy, or media parameters may disagree.</p><ol><li>Verify negotiated codec and media addresses.</li><li>Check whether RTP packets leave and arrive in both directions.</li><li>Confirm ICE candidate checks and TURN relay fallback.</li><li>Separate signaling success from actual media flow.</li></ol><p><strong>Engineering lesson:</strong> a control-plane success response does not prove the data plane is carrying media.</p>","<div class=\"section-kicker\">HANDS-ON · TRACE A SIMPLE CALL SETUP</div><h2 id=\"reader-title\" tabindex=\"-1\">Step through signaling and media separately</h2><p>Advance from invitation to media. Toggle a restrictive NAT to see why a relay may be needed even after SIP negotiation succeeds.</p><div class=\"network-lab\" data-call-lab><h3>Call setup trace</h3><label><input type=\"checkbox\" data-call-nat> Restrictive NAT/firewall</label><ol class=\"router-pipeline\"><li data-call-step=\"0\" class=\"is-active\"><b>1 · SIP invite</b>Start session</li><li data-call-step=\"1\"><b>2 · Negotiate</b>Codec and address</li><li data-call-step=\"2\"><b>3 · Reachability</b>ICE checks</li><li data-call-step=\"3\"><b>4 · RTP</b>Media packets</li></ol><div class=\"network-lab-controls\"><button type=\"button\" data-call-next>Advance call →</button><button type=\"button\" data-call-reset>Reset</button></div><p class=\"network-status\" data-call-status aria-live=\"polite\"></p></div><p>Which step tells you the call is connected at the control layer? Which proves media is flowing?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · TEST BOTH SESSION AND MEDIA PATHS</div><h2 id=\"reader-title\" tabindex=\"-1\">Call state is not the same as audio delivery</h2><ol><li>What does SIP coordinate?</li><li>What timing data does RTP carry?</li><li>Why can NAT block media after session negotiation?</li><li>What evidence confirms packets flow in both directions?</li></ol><details><summary>Review the core ideas</summary><p>SIP sets up and manages sessions. RTP transports media with timing and sequence information. NAT traversal may require ICE and a relay such as TURN. Inspect the negotiated parameters and bidirectional media packets separately from signaling.</p></details><p><strong>Connect forward:</strong> QoS policies classify and schedule traffic when network resources are limited.</p>"],"module-9-5":["<div class=\"section-kicker\">WHY IT EXISTS · NETWORK CAPACITY IS SHARED</div><h2 id=\"reader-title\" tabindex=\"-1\">How can a network protect latency-sensitive traffic?</h2><p class=\"reader-intro\">When traffic demand exceeds link capacity, queues grow and packets wait or drop. Quality-of-service mechanisms classify flows, mark traffic, manage queues, and schedule transmission to meet different performance goals.</p><div class=\"reader-callout\"><strong>Why software engineers learn this</strong><p>QoS affects voice, video, APIs, storage replication, and bulk transfers. Application teams need to understand what a network can prioritize—and that local prioritization cannot create capacity where none exists.</p></div><p><strong>By the end:</strong> distinguish classification from scheduling, explain queue delay and admission control, and design QoS policies that remain fair under load.</p>","<div class=\"section-kicker\">SYSTEM MODEL · CLASSIFY, QUEUE, SCHEDULE</div><h2 id=\"reader-title\" tabindex=\"-1\">QoS manages contention; it does not make bandwidth infinite</h2><ol><li>Classify packets from trusted policy inputs.</li><li>Optionally mark traffic, for example with DSCP, for downstream handling.</li><li>Place packets into queues with different service policies.</li><li>Schedule queues while controlling buffer growth and drops.</li></ol><p>Priority scheduling can reduce latency for selected traffic but starve others if unbounded. Weighted fair queuing or shaping can reserve a share and smooth bursts. Admission control prevents promising more traffic than capacity allows.</p>","<div class=\"section-kicker\">ENGINEERING CASE · VOICE DEGRADES DURING A BACKUP</div><h2 id=\"reader-title\" tabindex=\"-1\">Prioritize carefully and measure the result</h2><p>A backup saturates a WAN link and voice calls develop jitter. Marking voice packets at the application edge is not enough if downstream devices ignore or rewrite the mark, or if the priority queue is too small.</p><ol><li>Measure link utilization, queue delay, drops, and traffic classes.</li><li>Trust and remark traffic at the network boundary.</li><li>Bound priority traffic and shape bulk bursts.</li><li>Test fairness and call quality while the link is congested.</li></ol><p><strong>Engineering lesson:</strong> QoS is an end-to-end policy. Classification, marking, queueing, and scheduling must align across the path.</p>","<div class=\"section-kicker\">HANDS-ON · COMPARE QUEUE POLICIES</div><h2 id=\"reader-title\" tabindex=\"-1\">See how scheduling changes delay and fairness</h2><p>Choose a scheduler while an interactive stream and bulk transfer compete for a constrained link.</p><div class=\"network-lab\" data-qos-lab><h3>Queue scheduler</h3><div class=\"network-lab-controls\"><label>Policy<br><select data-qos-policy><option value=\"fifo\">First in, first out</option><option value=\"priority\">Strict priority</option><option value=\"weighted\">Weighted fair</option></select></label><label>Interactive traffic share<br><input type=\"range\" min=\"10\" max=\"90\" value=\"30\" data-qos-share></label></div><div class=\"network-diagram\" data-qos-diagram></div><p class=\"network-status\" data-qos-status aria-live=\"polite\"></p></div><p>Which policy best fits a mixed workload, and what fairness guardrail would you add?</p>","<div class=\"section-kicker\">TRANSFER CHECKPOINT · MAKE THE SERVICE GOAL MEASURABLE</div><h2 id=\"reader-title\" tabindex=\"-1\">Prioritize a class without hiding overload</h2><ol><li>How does classification differ from scheduling?</li><li>What can DSCP marking tell downstream devices?</li><li>Why can strict priority starve bulk traffic?</li><li>How does admission control help protect an overloaded path?</li></ol><details><summary>Review the core ideas</summary><p>QoS classifies traffic, may mark it, and schedules queues under contention. Strict priority can protect latency but starve other traffic. Weighted scheduling and shaping can improve fairness. QoS manages scarce capacity; it does not create more capacity.</p></details><p><strong>Course recap:</strong> applications create traffic with different delivery needs; each network layer adds mechanisms to carry, route, protect, and schedule it.</p>"]};
  if(chapterNine[id])return chapterNine[id];
  return genericPages;
 
  }

  window.BIT_FOUNDRY_NETWORKING_LESSONS = Object.freeze({
    activities: Object.freeze(activities),
    lessonDetails: Object.freeze(lessonDetails),
    buildLessonPages
  });
})();
